    public void displayETKThistoryfromexistingdata(ExtentTest logInfo) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flightNo = pax.getSegmentFlight(0);
            String startDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String originCity = pax.getSegmentOriginCity(0);
            String destinationCity = pax.getSegmentDestinationCity(0);

            //             6:LD015/08AUGPTY#ALL/ET
            String command = "6:LD" + flightNo + "/" + startDate + originCity + "#ALL/ET";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "E/TICKETED PAX", logInfo);

            String response = isharesPageObjects4.SHARES_RESPONSE.getText();
            int firstPNRindex = response.indexOf(destinationCity, response.indexOf(destinationCity) + 1);
            String firstPNR = response.substring(firstPNRindex + 4, firstPNRindex + 10);

            //             *BD4KNB
            command = "*" + firstPNR;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, firstPNR, logInfo);

            //             *ET
            command = "*ET";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, firstPNR, logInfo);

            //             *EH
            command = "*EH";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "T:Q1", "FP ", logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


