    public void enter_baggage_Catalog_display_command(ExtentTest logInfo) {
        try {
//           *ET-nnnn/BAG

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            gl.logCommand(logInfo, "*EH");
            //RESTRICTED UNTIL TIME OF DEPARTURE
            gl.sendCmdValidateResponse("*EH", logInfo);
            String response = isharesPageObjects4.SHARES_RESPONSE.getText();

            String[] rows = response.split("\n");
            String[] text = rows[0].split(" ");

            for (int i = 1; i < text.length; i++) {

                if (!text[i].equalsIgnoreCase("") && text[i].contains("2")) {
                    String LNIATA = text[i];
                    gl.logCommand(logInfo, "*ET-" + LNIATA + "/BAG");
                    gl.sendCmdValidateResponse("*ET-" + LNIATA + "/BAG", "STANDARD BAGGAGE CHARGES", logInfo);
                    break;
                }

            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

