    public void restrictingSimultaneousCheckin(ExtentTest logInfo) {
        try {
//             6:CT851/09FEBPTY
            gl.ignoreTRNS(logInfo);

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String origin = pax.getSegmentOriginCity(0);
            String flight = pax.getSegmentFlight(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));

            String restrictCommand = "6:CT" + flight + "/" + date + origin;
            gl.logCommand(logInfo, restrictCommand);
            gl.sendCmdValidateResponse(restrictCommand, "CHECK-IN RESTRICTED TO LOCAL STATION", "SHIP NOT ASSIGNED", "RESTRICTED TO CONTROLING STATION", logInfo);

            if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("SHIP NOT ASSIGNED")) {

                isharesPage2.openFlight(logInfo, flight, date, origin);
                isharesPageObjects4.FORMSIZE_DROPDOWN.click();
                isharesPageObjects4.FORMSIZE_SELECT1.click();
                gl.waitForProfileLoad();

                gl.logCommand(logInfo, restrictCommand);
                gl.sendCmdValidateResponse(restrictCommand, "CHECK-IN RESTRICTED TO LOCAL STATION", "RESTRICTED TO CONTROLING STATION/CRT", logInfo);
            }

            if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("RESTRICTED TO CONTROLING STATION/CRT")) {
                String command1 = "6-CQA" + "/" + "C***";
                gl.logCommand(logInfo, command1);
                gl.sendCmdValidateResponse(command1, "ASSIGNED CONTROLLING SET FOR", "CONTROLLING SET CHANGED TO", logInfo);

                gl.logCommand(logInfo, restrictCommand);
                gl.sendCmdValidateResponse(restrictCommand, "CHECK-IN RESTRICTED TO LOCAL STATION", logInfo);
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }
    }

