    public void enterSequentialSharesStepsToExecuteTheFlow(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String flight = pax.getSegmentFlight(0);
            String COS = pax.getCOS();
            String Origin = pax.getSegmentOriginCity(0);
            String Destination = pax.getSegmentDestinationCity(0);

            //0 CM 306Y 10DEC  LAXPTY NN1
            String command = "0 CM " + flight + COS + Date + Origin + Destination + "NN1";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "ETKT ELIGIBLE", logInfo);

            //-PIHU/TST
            command = "-" + pax.getfName() + "/" + pax.getlName();
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "*", logInfo);

            //6P#7T/#9PTY/N000#ER
            command = "6P|7T/|9" + Origin + "/N000|ER";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "RCVD-P", logInfo);
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

