    public void commandClearInoperativeSHARES(ExtentTest logInfo) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flight = pax.getSegmentFlight(0);
            String StartDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String Airline = pax.getAirline(0);
            String origin = pax.getSegmentOriginCity(0);
            String destination = pax.getSegmentDestinationCity(0);
            String fName = pax.getfName();
            String lName = pax.getlName();

            //            6:*360/08AUGPTY.Y
            String command = "6:*" + flight + "/" + StartDate + origin + ".Y";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, flight, logInfo);

            //            6:CI360/08AUGPTY.Y#@9A
            command = "6:CI" + flight + "/" + StartDate + origin + ".Y#@9A";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, logInfo);

            String response = isharesPageObjects4.SHARES_RESPONSE.getText();
            if (response.contains("SHIP NOT ASSIGNED") || response.contains("FLT NOT OPEN")) {
                isharesPage2.openFlight(logInfo, flight, StartDate, origin);

                isharesPageObjects4.FORMSIZE_DROPDOWN.click();
                isharesPageObjects4.FORMSIZE_SELECT1.click();

                command = "6:CI" + flight + "/" + StartDate + origin + ".Y#@9A";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "INOP", logInfo);
            } else {
                Assert.assertTrue(response.contains("INOP"));
            }


        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void runProcessThroughPassenger(ExtentTest logInfo) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flight = pax.getSegmentFlight(0);
            String StartDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String Airline = pax.getAirline(0);
            String origin = pax.getSegmentOriginCity(0);
            String destination = pax.getSegmentDestinationCity(0);
            String fName = pax.getfName();
            String lName = pax.getlName();

            //            6:391/10JANPTY-POP/SAM
            String command = "6:" + flight + "/" + StartDate + origin + "-" + lName + "/" + fName;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, flight, logInfo);

            //            6-AP0391/10JANPTY-POP/SAM
            command = "6-AP" + flight + "/" + StartDate + origin + "-" + lName + "/" + fName;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, flight, logInfo);

            //            6-U391/10JANSJO-POP/SAM#@
            command = "6-U" + flight + "/" + StartDate + destination + "-" + lName + "/" + fName + "#@";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, flight, logInfo);

            //            6-LD391/10JANPTY-PAX/POP/SAM
            command = "6-LD" + flight + "/" + StartDate + destination + "-PAX" + "/" + lName + "/" + fName;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, flight, logInfo);

            //            6-UG391/10JANSJO-POP/SAM.Y
            command = "6-UG" + flight + "/" + StartDate + destination + "-" + lName + "/" + fName + ".Y";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, flight, logInfo);

            //            6-LD391/10JANPTY-PAX/POP/SAM
            command = "6-LD" + flight + "/" + StartDate + origin + "-PAX" + "/" + lName + "/" + fName;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, flight, logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

