    public String addSSRFQTV(ExtentTest logInfo, String SSRType) {
        Passenger pax = mPassengers.get(getDriverID()).get(0);
        String flight = pax.getSegmentFlight(0);
        String origin = pax.getSegmentOriginCity(0);
        String destination = pax.getSegmentDestinationCity(0);
        String COS = pax.getCOS();
        String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
        String Airline = pax.getAirline(0);

        String addSSRFQTV = "";
        if (SSRType.equals("ADUPHK")) {
            // SSRFQTVUPHK/AD9872920052-BASSOTTO/EDUARDO#01.01
            addSSRFQTV = "SSRFQTVUPHK/AD9872920052" + "-" + pax.getfName() + "/" + pax.getlName() + "#01.01";
        } else if (SSRType.equals("UPUPHK")) {
            // SSRFQTVUPHK/AD9872920052-BASSOTTO/EDUARDO#01.01
            addSSRFQTV = "SSRFQTVUPHK/UP914883" + "-" + pax.getfName() + "/" + pax.getlName() + "#01.01";
        } else if (SSRType.equals("FQTR")) {
            // SSRFQTRCMHK/CM231730448-JOHN/JERSY
            addSSRFQTV = "SSRFQTCMPHK/CM231730448" + "-" + pax.getfName() + "/" + pax.getlName();
        } else {
            // SSRFQTVCMNN/230002804-LANDERO/CARLO#01.01
            addSSRFQTV = "SSRFQTV" + Airline + "NN/230002804" + "-" + pax.getfName() + "/" + pax.getlName() + "#01.01";
        }

        return addSSRFQTV;
    }

    public String addSSRSeat(ExtentTest logInfo, String SSR, String SeatNo) {

        Passenger pax = mPassengers.get(getDriverID()).get(0);
        String flight = pax.getSegmentFlight(0);
        String origin = pax.getSegmentOriginCity(0);
        String destination = pax.getSegmentDestinationCity(0);
        String COS = pax.getCOS();
        String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
        String Airline = pax.getAirline(0);

        String SSRSeat = "";
        // SSRSEATCMNN1LAXPTY0402Y05MAR-1GG/PARLE.12F_
        if (SSR.equalsIgnoreCase("SeatAdd")) {
            SSRSeat = "SSRSEAT" + Airline + "NN1" + origin + destination + flight + COS + date + "-" + pax.getfName() + "/" + pax.getlName() + "." + SeatNo;
        } else if (SSR.equalsIgnoreCase("SeatCancel")) {
            SSRSeat = "SSRSEAT" + Airline + "XX1" + origin + destination + flight + COS + date + "-" + pax.getfName() + "/" + pax.getlName() + "." + SeatNo;
        }
        return SSRSeat;
    }

