    public void TTYMessageBasicAirlinePbr(ExtentTest logInfo, String SystemType, String UniquePnr, String PNRType) {
        try {
            //            Y
            //            PTYRMCM
            //            .HDQRM1S 251335
            //            HDQ1S SUSUSQ
            //            1JHON/KIM
            //            CM120Y12APRPTYMEXNN1

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String PaxFname = pax.getfName();
            int TotalSegments = mPassengers.get(getDriverID()).get(0).getTotalSegments();
            if (TotalSegments == 3) {
                TotalSegments = 2;
            }
            String totalSegments = String.valueOf(TotalSegments);

            String Line2 = null;   //PTYRMCM
            if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL")) {
                Line2 = "PTYRMCM";
            } else {
                Line2 = "CLTYSCM";
            }

            if (UniquePnr.isEmpty()) {
                UniquePnr = isharesPage2.GenerateUniquePnr(logInfo);
            }

            String BasicAirlinePnr;

            if (PNRType.equals("RLR")) {
                BasicAirlinePnr = "Y" + "\n" +
                        Line2 + "\n" +
                        ".HDQRM1" + SystemType + " 251335" + "\n" +
                        "RLR" + "\n" +
                        "HDQ1" + SystemType + " " + UniquePnr + "/W84C/57524401/GRU/1S/T/BR" + "\n" +
                        isharesPage2.GDSPnrTotalPax() + isharesPage2.GDSPnrTotalSegments(totalSegments);
            } else {
                BasicAirlinePnr = "Y" + "\n" +
                        Line2 + "\n" +
                        ".HDQRM1" + SystemType + " 251335" + "\n" +
                        "HDQ1" + SystemType + " " + UniquePnr + "\n" +
                        isharesPage2.GDSPnrTotalPax() + isharesPage2.GDSPnrTotalSegments(totalSegments);
            }
            isharesPageObjects4.FORMSIZE_DROPDOWN.click();
            isharesPageObjects4.FORMSIZE_SELECT24.click();

            gl.logCommand(logInfo, BasicAirlinePnr);
            System.out.println("BaseCommand " + BasicAirlinePnr);
            gl.copyCmdToClipboardAndPaste(BasicAirlinePnr, isharesPageObjects4.FORMSIZE_SELECT2_TEXTAREA);

            isharesPageObjects4.SEND_ISHARES.click();
            logInfo.pass("I passed TTY message");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            gl.waitForProfileLoad();
            String response = isharesPageObjects4.SHARES_RESPONSE.getText();
            gl.logResponse(logInfo, response);
            Assert.assertTrue(response.contains("MESSAGE ACCEPTED"));

            isharesPageObjects4.FORMSIZE_DROPDOWN.click();
            isharesPageObjects4.FORMSIZE_SELECT1.click();

            isharesPage2.checkTTYPNR(logInfo, UniquePnr);

            logInfo.pass("I enter TTY message to generate PNR");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

