            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, logInfo);

            //6P#ER
            command = "6P#ER";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, pax.getPnr(), logInfo);

            //T-$4444333322221001/1224/N1234#ET
