            gl.sendCmdValidateResponse(command, "EMPTY FIELD IN FOP", logInfo);

            //T-$0
            command = "T-$0";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "EMPTY FIELD IN FOP", logInfo);

            //*QES444
            command = "*QES444";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "UNBL TO RTRV PNR", logInfo);

            String retrievePnr = "*" + pax.getPnr();
            gl.logCommand(logInfo, retrievePnr);
            gl.sendCmdValidateResponse(retrievePnr, pax.getPnr(), logInfo);

            //T-$4000123412341234/903#CMA50.25/ET
