    public void TTYMessageToRequestSineIn(ExtentTest logInfo, String ResponseType, String SystemType) {
        try {
//            Y
//            PTYRMCM
//            .MUCRM1A 251335
//            FAM
//            2N493/05MAR#PTY/FX

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flight = pax.getSegmentFlight(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String origin = pax.getSegmentOriginCity(0);
            String destination = pax.getSegmentDestinationCity(0);

            String ArrivalFlightTime = pax.getSegmentArrivalTime(0);
            String DepartFlightTime = pax.getSegmentDepartureTime(0);

            if (DepartFlightTime.length() == 4) {
                DepartFlightTime = "0" + pax.getSegmentDepartureTime(0);
            }
            if (ArrivalFlightTime.length() == 4) {
                ArrivalFlightTime = "0" + pax.getSegmentArrivalTime(0);
            }


            String Line2 = null;   //PTYRMCM
            if (globalConstants.testEnv.equalsIgnoreCase("sharesURL")) {
                Line2 = "PTYRMCM";
            } else {
//                Line2 = "CLTYSCM";
                Line2 = "PTYRMCM";
            }

            String SegmentData = null;
            if (ResponseType.equalsIgnoreCase("SineInRequired")) {
                //2N0876/07MAY#PTY/FX
                SegmentData = "2N" + flight + "/" + date + "|" + origin + "/LX FLIGHT CANCELLED";
            }
            String BasicAirlinePnr = "Y" + "\n" +
                    Line2 + "\n" +
                    ".MUCRM1" + SystemType + "\n" +
                    "FAM" + "\n" +
                    SegmentData;

            isharesPageObjects4.FORMSIZE_DROPDOWN.click();
            isharesPageObjects4.FORMSIZE_SELECT24.click();

            gl.logCommand(logInfo, BasicAirlinePnr);
            System.out.println("BaseCommand " + BasicAirlinePnr);
            gl.copyCmdToClipboardAndPaste(BasicAirlinePnr, isharesPageObjects4.FORMSIZE_SELECT2_TEXTAREA);

            isharesPageObjects4.SEND_ISHARES.click();
            logInfo.pass("I passed TTY message");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            gl.waitForProfileLoad();

            String response = isharesPageObjects4.SHARES_RESPONSE.getText();
            gl.logResponse(logInfo, response);
            Assert.assertTrue(response.contains("MESSAGE ACCEPTED") || response.contains("SIGN IN"));

            isharesPageObjects4.FORMSIZE_DROPDOWN.click();
            isharesPageObjects4.FORMSIZE_SELECT1.click();

            logInfo.pass("I enter TTY message to modify flight");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

