    public void iDisplayPNRpresentinparticularQueue(ExtentTest logInfo, String POS, String MsgNumber) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flight = pax.getSegmentFlight(0);
            String Origin = pax.getSegmentOriginCity(0);
            String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));

            //QC/CRC/ALL
            String command = "QC/" + POS + "/ALL";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "PNR QUEUES", flight, logInfo);

            String response = isharesPageObjects4.SHARES_RESPONSE.getText();
            int index = response.indexOf("PNR QUEUES");
            MsgNumber = response.substring(index + 12, index + 14);

            isharesPage1.ignoreTRNS(logInfo);
            //Q/CRC/24
            command = "Q/" + POS + "/" + MsgNumber;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "*FQ", flight, "ETKT", logInfo);

            //QXI
            command = "QXI";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "OFF Q DUTY PNR IGNORED", flight, logInfo);

            //Q/CRC/24
            command = "Q/" + POS + "/" + MsgNumber;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "*FQ", flight, "ETKT", logInfo);

            isharesPage1.ignoreTRNS(logInfo);
            //QXI
            command = "QXI";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "OFF Q DUTY", flight, logInfo);
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


