    public void enter_CA_verifyCreditcard(ExtentTest logInfo, String CardType, String CardNumber, String ExpiryDate, String Cid, String isValid) {
        try {
            String cardDetails;
            String command = "";
            String cardTypeExt = "";

            if (CardType.equals("Visa")) {
                cardTypeExt = "VI";
            } else if (CardType.equals("AMEX")) {
                cardTypeExt = "AX";
            } else if (CardType.equals("MasterCard")) {
                cardTypeExt = "MC";
            }
            if (ExpiryDate.isEmpty()) {
                //          CA125VI6343434343434343/1125
                cardDetails = CardNumber + "/" + Cid;
                command = "CA125" + cardTypeExt + cardDetails;
            } else {
                //          CA12VI64005554444444403/1225/V623
                cardDetails = CardNumber + "/" + ExpiryDate + "/" + Cid;
                command = "CA12" + cardTypeExt + cardDetails;
            }
            gl.logCommand(logInfo, command);
            if (isValid.equals("Yes")) {
                gl.sendCmdValidateResponse(command, "OK", logInfo);
            } else {
                gl.sendCmdValidateResponse(command, "INVALID", logInfo);
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


