    public void getFLIFOForAParticularFlight_Date_Carrier(ExtentTest logInfo, String flight, String Carrier) {
        try {
            //      21249/09JULPTY-UA
            //      28565/10JUL/MDE-AV
            //      21916/27MARPTY-AA
            //      277/10JULIST-TK
            //      21002/10JUL-LH
            Passenger pax = mPassengers.get(getDriverID()).get(0);
//            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
//            String Origin = pax.getSegmentOriginCity(0);
            String Carrier1 = pax.getAirline(0);
            if (!Carrier.equalsIgnoreCase(Carrier1)) {
                Carrier1 = Carrier;
            }
            String command = "";
            if (Carrier1.equalsIgnoreCase("AV")) {
                command = "2" + flight + "/" + gl.sharesFormatDateFromGUI(pax.getSegmentDate(0)) + "/" + pax.getSegmentOriginCity(0) + "-" + Carrier1;
            } else if (Carrier1.equalsIgnoreCase("LH")) {
                command = "2" + flight + "/" + gl.sharesFormatDateFromGUI(pax.getSegmentDate(0)) + "-" + Carrier1;
            } else {
                command = "2" + flight + "/" + gl.sharesFormatDateFromGUI(pax.getSegmentDate(0)) + pax.getSegmentOriginCity(0) + "-" + Carrier1;
            }

            gl.logCommand(logInfo, command);
            if (Carrier1.equalsIgnoreCase("AA") || Carrier1.equalsIgnoreCase("DL") || Carrier1.equalsIgnoreCase("EK") || Carrier1.equalsIgnoreCase("IB")) {
                gl.sendCmdValidateResponse(command, "CARRIER", "CARRIER NOT IN STAR ALLIANCE", logInfo);
            } else {
                gl.sendCmdValidateResponse(command, "STARNET", "*** STARNET FLIFO DATA ***", logInfo);
            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

