    public void EnterQM_CommandToVerifyInvalidMessages(ExtentTest logInfo, String Code) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            //  K-T-PARTNER/*/TTY/**
            String command = "K-T-PARTNER/*/TTY/**";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "TTY", logInfo);

            String TTYcode = "";

            String response = isharesPageObjects4.SHARES_RESPONSE.getText();
            String[] rows = response.split("\n");

            for (int i = 0; i < rows.length; i++) {
                if (rows[i].contains("3M")) {
                    String[] text = rows[i].split("\\*{5}");
                    TTYcode = text[1];
                }
            }
//            QM/PAR#LAST
            command = "QM/" + TTYcode + "|LAST";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, pax.getSegmentFlight(0), "MSG", logInfo);

//            QM/FCF#LAST
            command = "QM/" + Code + "|LAST";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "INVALID", logInfo);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

