    public void enterbasicentry_command(ExtentTest logInfo, String command) {
        try {
            String validatetext = "";
            if (command.contains("LA$") || command.contains("LP$")) {
                validatetext = "FARE";
            } else if (command.equals("D$$@")) {
                validatetext = "*NO SESSION EXISTS";
            } else if (command.equals("$")) {
                command = "$-" + mPassengers.get(getDriverID()).get(0).getSegmentOriginCity(0) + mPassengers.get(getDriverID()).get(0).getSegmentDestinationCity(0);
                validatetext = "$:";
            } else if (command.equals("D$$@ALL@")) {
                validatetext = "*NO SESSION EXISTS";
            } else if (command.equals("D$$@ADVANCED")) {
                validatetext = "D$$@ADVANCED";
            } else if (command.equals("D$2@ALL-QAP3")) {
                validatetext = "RULES DISPLAY";
            } else if (command.equals("D$$@C")) {
                validatetext = "D$$@C";
            } else if (command.equals("D$$@ALL-1")) {
                validatetext = "D$$@ALL-1";
            }
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, validatetext, "FARE COMPONENT", logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


