    public String acceptAPISDeletion(ExtentTest logInfo, String response) {
        String acceptedResponse = response.split("\n")[1].substring(1) + "\n" + response.split("\n")[2];
        try {

            for (int i = 3; i < response.split("\n").length; i++) {
                acceptedResponse = acceptedResponse + (response.split("\n")[i].contains("GIVEN NAMES") ? ("\n" + response.split("\n")[i]) : "");
                acceptedResponse = acceptedResponse + (response.split("\n")[i].contains("LAST NAME") ? ("\n" + response.split("\n")[i]) : "");
                acceptedResponse = acceptedResponse + (response.split("\n")[i].contains("DATE OF BIRTH") ? ("\n" + response.split("\n")[i]) : "");
                acceptedResponse = acceptedResponse + (response.split("\n")[i].contains("GENDER") ? ("\n" + response.split("\n")[i]) : "");
                acceptedResponse = acceptedResponse + (response.split("\n")[i].contains("NATIONALITY") ? ("\n" + response.split("\n")[i]) : "");
                acceptedResponse = acceptedResponse + (response.split("\n")[i].contains("COUNTRY OF RESIDENCE") ? ("\n" + response.split("\n")[i]) : "");
                acceptedResponse = acceptedResponse + (response.split("\n")[i].contains("DOCUMENT TYPE") ? ("\n" + response.split("\n")[i]) : "");
                acceptedResponse = acceptedResponse + (response.split("\n")[i].contains("DOCUMENT NUMBER") ? ("\n" + response.split("\n")[i]) : "");
                acceptedResponse = acceptedResponse + (response.split("\n")[i].contains("COUNTRY OF ISSUANCE") ? ("\n" + response.split("\n")[i]) : "");
                acceptedResponse = acceptedResponse + (response.split("\n")[i].contains("EXPIRATION DATE") ? ("\n" + response.split("\n")[i]) : "");
                acceptedResponse = acceptedResponse + (response.split("\n")[i].contains("CONFIRM DELETE") ? ("\n" + response.split("\n")[i] + "Y") : "");

            }

            if (!acceptedResponse.contains("CONFIRM DELETE")) {
                acceptedResponse = acceptedResponse + "CONFIRM DELETE:Y" + "\n" + "280210                                  * EXPIRATION DATE";
            }
            System.out.println(acceptedResponse);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
        return acceptedResponse;
    }

    public void voluntaryDeniedBoardingPassengersForExclusiveOption(ExtentTest logInfo) {
        try {
//                6:DV360/29DECPTY-EARTH/WORLD/NF
//               6:LDV-182

            gl.ignoreTRNS(logInfo);
            String volDeniedBoardingCmd = null;
            String indexNo = null;

            ArrayList<Passenger> passengers = mPassengers.get(getDriverID());
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String flightNo = pax.getSegmentFlight(0);
            String Origin = pax.getSegmentOriginCity(0);

            for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {

                if ( pax.getPaxType().equalsIgnoreCase("NRSA") ||  pax.getPaxType().equalsIgnoreCase("NRPS")
                        || pax.getPaxType().equalsIgnoreCase("Waitlist")) {

                    volDeniedBoardingCmd = "6:DV" + flightNo + "/" + date + Origin + "-"
                            + mPassengers.get(getDriverID()).get(i).getfName() + "/" + mPassengers.get(getDriverID()).get(i).getlName() + "/NF";
                    gl.logCommand(logInfo, volDeniedBoardingCmd);
                    gl.sendCmdValidateResponse(volDeniedBoardingCmd, "INVLD ENT -PSGR IS NON-REVENUE", "FLT NOT OPEN", "MULTIPLE ITEMS", logInfo);

                } else {

                    volDeniedBoardingCmd = "6:DV" + flightNo + "/" + date + Origin + "-"
                            + mPassengers.get(getDriverID()).get(i).getfName() + "/" + mPassengers.get(getDriverID()).get(i).getlName() + "/NF";
                    gl.logCommand(logInfo, volDeniedBoardingCmd);
                    gl.sendCmdValidateResponse(volDeniedBoardingCmd, "PSGR ADDED TO VOL OVERSOLD LIST", "FLT NOT OPEN", "MULTIPLE ITEMS", logInfo);

                    if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("MULTIPLE ITEMS")) {

                        String response = isharesPageObjects4.SHARES_RESPONSE.getText();

                        for (int j = 0; j < response.split("\n").length; j++) {

                            if (response.split("\n")[j].contains( mPassengers.get(getDriverID()).get(i).getfName())) {

                                indexNo = response.split("\n")[j].split(" ")[1];

                                for (int k = 0; k < response.split("\n")[j].split(" ").length; k++)
                                    System.out.println("Sl no.: " + k + " " + "Text: " + response.split("\n")[j].split(" ")[k]);
                                break;
                            }
                        }

//                    6:LDV-182
                        if (mPassengers.get(getDriverID()).get(0).getPaxType().equalsIgnoreCase("NRSA") || mPassengers.get(getDriverID()).get(0).getPaxType().equalsIgnoreCase("NRPS")
                                || mPassengers.get(getDriverID()).get(0).getPaxType().equalsIgnoreCase("Waitlist")) {
                            gl.logCommand(logInfo,"6:LDV-" + indexNo);
                            gl.sendCmdValidateResponse("6:LDV-" + indexNo, "INVLD ENT -PSGR IS NON-REVENUE", logInfo);
                        } else {
                            gl.logCommand(logInfo,"6:LDV-" + indexNo);
                            gl.sendCmdValidateResponse("6:LDV-" + indexNo, "PSGR ADDED TO VOL OVERSOLD LIST",  mPassengers.get(getDriverID()).get(i).getfName(), logInfo);
                        }
                    }
                }
            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


