    public void openAlternateFlight(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String FlightNo = pax.getSegmentFlight(1);
            String departureDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String OriginCity = pax.getSegmentOriginCity(0);

            isharesPageObjects4.FORMSIZE_DROPDOWN.click();
            isharesPageObjects4.FORMSIZE_SELECT2.click();
            gl.waitForProfileLoad();
            String command = "6:*A" + FlightNo + "/" + departureDate + OriginCity;
            gl.logCommand(logInfo, command);
            gl.sendCmdForForm2ValidateResponse(command, logInfo);

            if (!isharesPageObjects4.SHARES_RESPONSE.getText().contains("SHIP ASSIGNED")) {
                String EqpNumber;
                String response = isharesPageObjects4.SHARES_RESPONSE.getText();
                EqpNumber = response.substring(response.indexOf(FlightNo) + 4, response.indexOf(FlightNo) + 10).trim();

                String command2 = "6:I*F" + EqpNumber;
                gl.logCommand(logInfo, command2);
                gl.sendCmdForForm2ValidateResponse(command2, logInfo);
                String FleetNumber = "";

                if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL") || globalConstants.testEnv.equalsIgnoreCase("sharesD3URL")) {
                    FleetNumber = isharesPageObjects4.SHARES_RESPONSE.getText().substring(128, 132);
                } else {
                    FleetNumber = isharesPageObjects4.SHARES_RESPONSE.getText().substring(130, 134);
                }

                System.out.println("Flight ship index " + FleetNumber);
                String command3 = "6:CA" + departureDate + "\n" + FlightNo + OriginCity + FleetNumber;
                gl.logCommand(logInfo, command3);
                isharesPageObjects4.FORMSIZE_SELECT2_TEXTAREA.click();
                gl.copyCmdToClipboardAndPaste(command3, isharesPageObjects4.FORMSIZE_SELECT2_TEXTAREA);
                isharesPageObjects4.SEND_ISHARES.click();
                gl.waitForProfileLoad();
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                response = isharesPageObjects4.SHARES_RESPONSE.getText();
                gl.logResponse(logInfo, response);
                Assert.assertTrue(response.contains("SHIP ASSIGNED"));
            }

            isharesPageObjects4.FORMSIZE_DROPDOWN.click();
            isharesPageObjects4.FORMSIZE_SELECT1.click();
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");

        }
    }


    public int[] getPaxIDs(String response, int paxIndex) {
        int x = 0;
        int[] paxIDs = new int[2];
        Passenger pax = mPassengers.get(getDriverID()).get(paxIndex);

        for (int i = 0; i < response.split("\n").length; i++) {
            if (response.split("\n")[i].contains(pax.getPnr2()) || response.split("\n")[i].contains(pax.getPnr())) {
                paxIDs[x++] = Integer.parseInt(response.split("\n")[i].substring(0, 4).trim());
            }
        }
        return paxIDs;
    }

    public void checkinOfTwoPNRsWithMultipleItemsErrorForForcedSelecteePax(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            int[] paxIDs = new int[2];
            boolean repeatTrns;

            gl.ignoreTRNS(logInfo);

            for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                repeatTrns = true;

                for (int a = 0; a < 2; a++) {
                    while (repeatTrns) {
                        gl.logCommand(logInfo, isharesPage2.addCheckinCmd(pax.getSegmentOriginCity(0), i));
                        gl.copyCmdToClipboardAndPaste(isharesPage2.addCheckinCmd(pax.getSegmentOriginCity(0), i), isharesPageObjects4.FORMSIZE_SELECT2_TEXTAREA);
                        gl.waitForProfileLoad();

                        isharesPageObjects4.SEND_ISHARES.click();
                        gl.waitForProfileLoad();
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        String response = isharesPageObjects4.SHARES_RESPONSE.getText();
                        gl.logResponse(logInfo, response);

                        if (response.contains("NOT OPEN")) {
                            isharesPage2.openFlight(logInfo, mPassengers.get(getDriverID()).get(0).getSegmentFlight(0), gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0)), pax.getSegmentOriginCity(0));
                            gl.ignoreTRNS(logInfo);
                        } else if (response.contains("PASSENGER DISPLAY") || response.contains("UNABLE TO RETRIEVE FDR-CHK DATA BASE")) {
                            Assert.fail();
                        } else if (response.contains("MULTIPLE ITEMS")) {
                            paxIDs = getPaxIDs(response, i);
                            repeatTrns = false;
                        } else {
                            repeatTrns = false;
                        }

                    }

//                    6:LSF-76
                    String command = "6:LSF-" + paxIDs[a];
                    gl.logCommand(logInfo, command);
                    gl.copyCmdToClipboardAndPaste(command, isharesPageObjects4.FORMSIZE_SELECT2_TEXTAREA);
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                    isharesPageObjects4.SEND_ISHARES.click();
                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    gl.logResponse(logInfo, isharesPageObjects4.SHARES_RESPONSE.getText());

                    //**** PRIMARY DOCUMENT DETAILS*****

                    String IncompleteADCInfo;
                    if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL") || globalConstants.testEnv.equalsIgnoreCase("sharesD3URL")) {
                        IncompleteADCInfo = isharesPageObjects4.SHARES_RESPONSE.getText();
                    } else {
                        IncompleteADCInfo = isharesPageObjects4.INPUT_TEXT_AREA_ROWS24.getText();
                    }
                    System.out.println(IncompleteADCInfo);
                    String CompleteADCInfo = isharesPage2.add_PrimaryADC(IncompleteADCInfo, i);
                    System.out.println(CompleteADCInfo);
                    while (!isharesPage2.validatePrimaryADC_Multi_Checkin(CompleteADCInfo, logInfo))  //to check Primary details are entered properly or not
                    {
                        CompleteADCInfo = isharesPage2.reformPrimaryADC(i);
                    }
                    logInfo.pass("Primary Document Details entered for ID: " + paxIDs[a] + "for PAX: " + mPassengers.get(getDriverID()).get(i).getFullName());

                    repeatTrns = true;
                }
            }
            isharesPageObjects4.FORMSIZE_DROPDOWN.click();
            isharesPageObjects4.FORMSIZE_SELECT1.click();

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

