    public void iEnterT$_PaymentWithRemarks(ExtentTest logInfo, String Remarks) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            if (Remarks.equalsIgnoreCase("FREEFLOWREMARK")) {
                //T-$CK#@ F R E F L O W R E M A R K
                String command = "T-$CK#@ F R E F L O W R E M A R K";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "NON-INVOICE TKT STOCK", "CK FOR POSSIBLE FULL/PARTIAL EXISTING E-TKT-RETRY", logInfo);

                logInfo.pass("Pay by Check");

                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FIN OR IGN TRANS", "FARE", logInfo);

            } else if (Remarks.equalsIgnoreCase("AAAAA")) {
                //T-$GR//////AAAAA
                String command = "T-$GR//////AAAAA";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "NON-INVOICE TKT STOCK", "CK FOR POSSIBLE FULL/PARTIAL EXISTING E-TKT-RETRY", logInfo);

                logInfo.pass("Pay by CBANCANCANC");

                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FIN OR IGN TRANS", "FARE", logInfo);
            } else if (Remarks.equalsIgnoreCase("Check")) {
                //T-$CK#@
                String command = "T-$CK#@";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "NON-INVOICE TKT STOCK", "CK FOR POSSIBLE FULL/PARTIAL EXISTING E-TKT-RETRY", logInfo);

                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FIN OR IGN TRANS", "FARE", logInfo);
            } else if (Remarks.equalsIgnoreCase("UE_CheckError")) {
                //T-$CK#@
                String command = "T-N1.1|$UE/FCERT/OB35.00/AC$4005554444444403/1219/N05389D|@XFNIL|ET";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "TAX AMOUNT TOO LARGE FOR ACO", "NON-INVOICE TKT STOCK", logInfo);
            }

            gl.logCommand(logInfo, endAndretrieve);
            gl.sendCmdValidateResponse(ignoreAndRetrieve, pax.getPnr(), logInfo);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

