    public void activateAndDeactivateLANATA(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String Lniata = pax.getLniata();

            String LINIATA = null;
            boolean LINIATAFound = false;

            gl.waitForProfileLoad();
            String checkLANATA = "KSSALL";

            gl.sendCmdValidateResponse(checkLANATA, logInfo);
            String response = isharesPageObjects4.SHARES_RESPONSE.getText();
            String[] AllLANATA = response.split("\n");

            String LANATA = isharesPageObjects4.LNIATA_CODE.getText();
            String ActivateLANATA = "OCM*KCT1ACT/" + Lniata;
            gl.sendCmdValidateResponse(ActivateLANATA, logInfo);
            String ActivateReponse = isharesPageObjects4.SHARES_RESPONSE.getText();

            if (!ActivateReponse.contains("SET ALREADY ACTIVE FOR S.C.")) {

                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                logInfo.pass("Selecting LANATA to remove from the LANATA table");

                do {
                    int i = 1;
                    for (i = i; i < AllLANATA.length - 2; i++) {
                        System.out.println("Index for F: " + AllLANATA[i].substring(13));
                        if (AllLANATA[i].substring(13, 14).equalsIgnoreCase("F") || AllLANATA[i].substring(13, 14).equalsIgnoreCase("D")) {
                            System.out.println("Index for F" + AllLANATA[i].substring(13, 18));
                            LINIATA = AllLANATA[i].substring(13, 19);
                            if (!LINIATA.equals("F66000") && !LINIATA.equals("F66001")) {
                                LINIATAFound = true;

                                logInfo.pass("I deactivate LANATA");
                                String DeactivateLANATA = "OCM*KCT1DAC/" + LINIATA;
                                gl.logCommand(logInfo, DeactivateLANATA);
                                gl.sendCmdValidateResponse(DeactivateLANATA, logInfo);

                                if (!isharesPageObjects4.SHARES_RESPONSE.getText().contains("OK")) {
                                    LINIATAFound = false;
                                } else {
                                    break;
                                }

                            }
                        }
                    }

                } while (!LINIATAFound);

                logInfo.pass("I activate LANATA");
                ActivateLANATA = "OCM*KCT1ACT/" + Lniata;
                gl.logCommand(logInfo, ActivateLANATA);
                gl.sendCmdValidateResponse(ActivateLANATA, "OK", "SET ALREADY ACTIVE FOR S.C.", logInfo);
                gl.waitForProfileLoad();
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
        }

    }

