    public void checkinOfTwoPNRsWithMultipleItemsErrorForWaitlistNRPSNRSANormalPax(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            int[] paxIDs = new int[2];
            boolean repeatTrns;

            gl.ignoreTRNS(logInfo);

            for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                repeatTrns = true;

                for (int a = 0; a < 2; a++) {
                    while (repeatTrns) {
                        if (pax.getpnrType().contains("Waitlist")) {
                            gl.logCommand(logInfo, isharesPage2.addCheckinCmdWaitlistPax(pax.getSegmentOriginCity(0), i));
                            gl.copyCmdToClipboardAndPaste(isharesPage2.addCheckinCmdWaitlistPax(pax.getSegmentOriginCity(0), i), isharesPageObjects4.FORMSIZE_SELECT2_TEXTAREA);
                            gl.waitForProfileLoad();
                        } else {
                            gl.logCommand(logInfo, isharesPage2.addCheckinCmd(pax.getSegmentOriginCity(0), i));
                            gl.copyCmdToClipboardAndPaste(isharesPage2.addCheckinCmd(pax.getSegmentOriginCity(0), i), isharesPageObjects4.FORMSIZE_SELECT2_TEXTAREA);
                            gl.waitForProfileLoad();
                        }
                        isharesPageObjects4.SEND_ISHARES.click();
                        gl.waitForProfileLoad();
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        String response = isharesPageObjects4.SHARES_RESPONSE.getText();

                        if (response.contains("NOT OPEN")) {
                            isharesPage2.openFlight(logInfo, mPassengers.get(getDriverID()).get(0).getSegmentFlight(0), gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0)), pax.getSegmentOriginCity(0));
                            gl.ignoreTRNS(logInfo);
                        } else if (response.contains("PASSENGER DISPLAY") || response.contains("UNABLE TO RETRIEVE FDR-CHK DATA BASE")) {
                            Assert.fail();
                        } else if (response.contains("MULTIPLE ITEMS")) {
                            paxIDs = getPaxIDs(response, 0);
                            repeatTrns = false;
                        } else {
                            repeatTrns = false;
                        }
                    }
                    boolean repeatUnAssignedTrns = false;
                    do {

                        for (int k = 0; k < (a + 1); k++) {
                            String command;
                            //  6:LK-76
                            if (k == 1)
                                command = "6:LK-" + paxIDs[k] + "\n" + "B0";
                            else
                                command = "6:LK-" + paxIDs[k];
                            gl.logCommand(logInfo, command);

                            gl.copyCmdToClipboardAndPaste(command, isharesPageObjects4.FORMSIZE_SELECT2_TEXTAREA);
                            gl.waitForProfileLoad();
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                            isharesPageObjects4.SEND_ISHARES.click();
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        }
                        //**** PRIMARY DOCUMENT DETAILS*****

                        String IncompleteADCInfo;
                        if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL") || globalConstants.testEnv.equalsIgnoreCase("sharesD3URL")) {
                            IncompleteADCInfo = isharesPageObjects4.SHARES_RESPONSE.getText();
                        } else {
                            IncompleteADCInfo = isharesPageObjects4.INPUT_TEXT_AREA_ROWS24.getText();
                        }
                        System.out.println(IncompleteADCInfo);
                        String CompleteADCInfo = isharesPage2.add_PrimaryADC(IncompleteADCInfo, i);
                        System.out.println(CompleteADCInfo);

                        while (!isharesPage2.validatePrimaryADC(CompleteADCInfo, logInfo))  //to check Primary details are entered properly or not
                        {
                            CompleteADCInfo = isharesPage2.reformPrimaryADC(i);

                        }
                        logInfo.pass("Primary Document Details entered for " + mPassengers.get(getDriverID()).get(i).getFullName());
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                        Assert.assertTrue(isharesPageObjects4.SHARES_RESPONSE.getText().contains("SEATS ASSIGNED") || isharesPageObjects4.SHARES_RESPONSE.getText().contains("ADDED TO"));

                        if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("SEATS UNASSIGNED") && (!isharesPageObjects4.SHARES_RESPONSE.getText().contains("ADDED TO"))) {
                            paxIDs = getPaxIDs(isharesPageObjects4.SHARES_RESPONSE.getText(), 0);
                            repeatUnAssignedTrns = true;
                        }
                        else {
                            repeatUnAssignedTrns =false;
                        }

                    } while (repeatUnAssignedTrns);
                    repeatTrns = true;
                }
            }

            isharesPageObjects4.FORMSIZE_DROPDOWN.click();
            isharesPageObjects4.FORMSIZE_SELECT1.click();

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


