    public void seatExchangeByName(ExtentTest logInfo) {
        try {

            ArrayList<Passenger> pax = mPassengers.get(getDriverID());

            String flight = pax.get(0).getSegmentFlight(0);
            String date = gl.sharesFormatDateFromGUI(pax.get(0).getSegmentDate(0));
            String origin = pax.get(0).getSegmentOriginCity(0);
            String COS = pax.get(0).getCOS();
            String destination = pax.get(0).getSegmentDestinationCity(0);

            String seatCmd = "";
            String[] seatNumber = new String[pax.size()];
            boolean seatAssigned = false;
            String[] seatAlphabet = {"A", "F"};

//                 6:*302/18JANPTY.Y
            String command = "6:*" + flight + "/" + date + origin + "." + COS;
            gl.sendCmdValidateResponse(command, origin.toUpperCase() + "-" + destination.toUpperCase(), "NONSMK", "@-AVAIL  .-TAKEN", logInfo);
            gl.ignoreTRNS(logInfo);

            for (int j = 0; j < pax.size(); j++) {
                for (String alphabet : seatAlphabet) {
                    for (int i = 5; i <= 35; i++) {
//                      6:X360/21DECPTY-TEST/LAD#21E
                        gl.ignoreTRNS(logInfo);

                        seatCmd = "6:X" + flight + "/" + date + origin + "-" + pax.get(j).getfName() + "/" + pax.get(j).getlName()
                                + "|" + i + alphabet;
                        gl.logCommand(logInfo, seatCmd);
                        gl.sendCmdValidateResponse(seatCmd, logInfo);
                        logInfo.pass("I exchange the seat");

                        String response = isharesPageObjects4.SHARES_RESPONSE.getText();
                        if (response.contains("FLT NOT OPEN") || response.contains("SHIP NOT ASSIGNED")) {
                            isharesPage2.openFlight(logInfo, flight, date, origin);
                            isharesPageObjects4.FORMSIZE_DROPDOWN.click();
                            isharesPageObjects4.FORMSIZE_SELECT1.click();
                            gl.sendCmdValidateResponse(seatCmd, logInfo);
                            response = isharesPageObjects4.SHARES_RESPONSE.getText();
                        }

                        if (response.contains(i + alphabet) && (!response.contains("NO SEATS PROCESSED"))) {
                            seatNumber[j] = i + alphabet;
                            seatAssigned = true;
                            gl.sendCmdValidateResponse("*" + pax.get(0).getPnr(), seatNumber[j], logInfo);
                            gl.sendCmdValidateResponse(command, logInfo);
                            logInfo.pass("I validated seat assigned successfully");
                            break;
                        }
                    }
                    if (seatAssigned)
                        break;
                }
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

