    public void enter_passenger_Details_for_specific_Pax(ExtentTest logInfo,String paxIndex) {
        try {

                Passenger pax = mPassengers.get(getDriverID()).get(Integer.parseInt(paxIndex));

                if (pax.getPaxType().equalsIgnoreCase("ADT") && !pax.getIsSameSurname()) {
                    String command = "-" + pax.getfName() + "/" + pax.getlName();

                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, pax.getfName().toUpperCase(), pax.getlName().toUpperCase(), logInfo);

                    logInfo.pass(MarkupHelper.createLabel("I entered pax details for : "+pax.getPaxType()+" -> "+pax.getFullName(), ExtentColor.GREEN));

                } else if (pax.getPaxType().equalsIgnoreCase("CHD") && !pax.getIsSameSurname()) {
                    //-SWAN/KAM*-CHD06
                    String command = "-" + pax.getfName() + "/" + pax.getlName() + "*-CHD06";

                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, pax.getfName().toUpperCase(), pax.getlName().toUpperCase(), logInfo);

                    logInfo.pass(MarkupHelper.createLabel("I entered pax details for : "+pax.getPaxType()+" -> "+pax.getFullName(), ExtentColor.GREEN));

                } else if (pax.getPaxType().equalsIgnoreCase("INS") && !pax.getIsSameSurname()) {
                    //-GAYLE/SWAM*-INS/10JAN21
                    String command = "-" + pax.getfName() + "/" + pax.getlName() + "*-INS/" + pax.getDOB();

                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, pax.getfName().toUpperCase(), pax.getlName().toUpperCase(), logInfo);

                    logInfo.pass(MarkupHelper.createLabel("I entered pax details for : "+pax.getPaxType()+" -> "+pax.getFullName(), ExtentColor.GREEN));

                } else if (pax.getPaxType().equalsIgnoreCase("INF") && !pax.getIsSameSurname()) { //ADT+INF

                    //-JEORGE/BROWN*-INFPUPPY/21JAN21

                    String command = "-" + pax.getAccompaniedPaxDetails().getfName() + "/" +
                            pax.getAccompaniedPaxDetails().getlName() + "*-INF" + pax.getlName() + "/" +
                            pax.getDOB();

                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, pax.getlName().toUpperCase(), logInfo);

                    logInfo.pass(MarkupHelper.createLabel("I entered pax details for : "+pax.getPaxType()+" -> "+pax.getFullName(), ExtentColor.GREEN));

                } else if (pax.getPaxType().equalsIgnoreCase("NRSA") && !pax.getIsSameSurname()) {
                    pax.setIsNRSA(true);
                    String command = "-S01C03/" + pax.getfName() + "/" + pax.getlName();

                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, pax.getfName().toUpperCase(), pax.getlName().toUpperCase(), logInfo);

                    logInfo.pass(MarkupHelper.createLabel("I entered pax details for : "+pax.getPaxType()+" -> "+pax.getFullName(), ExtentColor.GREEN));

                } else if (pax.getPaxType().equalsIgnoreCase("NRPS") && !pax.getIsSameSurname()) {

                    pax.setIsNRPS(true);
                    String command = "-P00B03/" + pax.getfName() + "/" + pax.getlName();

                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, pax.getfName().toUpperCase(), pax.getlName().toUpperCase(), logInfo);

                    logInfo.pass(MarkupHelper.createLabel("I entered pax details for : "+pax.getPaxType()+" -> "+pax.getFullName(), ExtentColor.GREEN));

                } else if (pax.getPaxType().equalsIgnoreCase("FQTV") && !pax.getIsSameSurname()) {

                    pax.setIsFQTV(true);
                    String command = "-" + pax.getfName() + "/" + pax.getlName() + "*" + pax.getFFNumber();

                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, pax.getfName().toUpperCase(), pax.getlName().toUpperCase(), logInfo);

                    logInfo.pass(MarkupHelper.createLabel("I entered pax details for : "+pax.getPaxType()+" -> "+pax.getFullName(), ExtentColor.GREEN));

                }


        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }




