    public void search_flightavailability(ExtentTest logInfo, String origin, String destination, String params, String flight) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String StartDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));

            String command = "";

            if (params.isEmpty()) {
                command = "A" + flight + "/" + StartDate + " " + origin + destination;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "INVLD FLT NBR", logInfo);
            } else if (params.contains("$B4/30")) {
                command = "A" + flight + "/" + StartDate + " " + origin + destination + " " + params;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "DAY SEARCH LEVEL EXCEEDS MAX OF 07", logInfo);
            } else if (params.contains("DL/CO")) {
                command = "A" + flight + "/" + StartDate + origin + destination + "-" + params;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "INVLD FLT NBR", logInfo);
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

