    public void changeThePaxtype(ExtentTest logInfo, String Totalpax, String Entry) {

        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String DOB = gl.sharesFormatDateFromGUIWithYear(-300);
            String Cmd;
            Faker faker = new Faker(new Locale("en-US"));
            String inflname = faker.name().lastName().replaceAll("[^a-zA-Z0-9]", "").toUpperCase();
            int PaxChangedCount = 0;

            if (Entry.equalsIgnoreCase("ADT_INF")) {

                for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {

                    if (pax.getPaxType().equalsIgnoreCase("ADT")) {
                        // -1@*-INFSAM/07MAY2023
                        Cmd = "-" + (i + 1) + "@*-INF" + inflname + "/" + DOB;
                        gl.logCommand(logInfo, Cmd);
                        gl.sendCmdValidateResponse(Cmd, "*", logInfo);
                        PaxChangedCount++;
                        pax.setPaxType("INF");
                    }
                    if (PaxChangedCount == Integer.parseInt(Totalpax)) {
                        break;
                    }
                }

            } else if (Entry.equalsIgnoreCase("Delete_INF")) {

                for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                    if (pax.getPaxType().equalsIgnoreCase("INF")) {
                        // -2@*-INF
                        Cmd = "-" + (i + 1) + "*-" + "INF";
                        gl.logCommand(logInfo, Cmd);
                        gl.sendCmdValidateResponse(Cmd, "*", logInfo);
                        pax.setPaxType("ADT");
                    }
                }

            }
            else if (Entry.equalsIgnoreCase("ADT_CHD")) {

                for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                    if (pax.getPaxType().equalsIgnoreCase("ADT")) {
                        // -1@TEST/KIM*-CHD09
                        Cmd = "-" + (i + 1) + "@" + pax.getfName() + "/" + pax.getlName() +"*-CHD09";
                        gl.logCommand(logInfo, Cmd);
                        gl.sendCmdValidateResponse(Cmd, "*", logInfo);
                        PaxChangedCount++;
                        pax.setPaxType("CHD");
                    }
                    if (PaxChangedCount == Integer.parseInt(Totalpax)) {
                        break;
                    }
                }

            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

