    public void CaptureTheFlightDetailsBeforeCancellingTheSegment(ExtentTest logInfo, String segmentNumber) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            int index = Integer.parseInt(segmentNumber);
            String FlightNumber = pax.getSegmentFlight(index);
            pax.setOldFlightNumber(FlightNumber);
            String Origin = pax.getSegmentOriginCity(index);
            pax.setOldOriginCity(Origin);
            String Destination = pax.getSegmentDestinationCity(index);
            pax.setOldDestinationCity(Destination);
            String OldDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(1));
            pax.setOldDate(OldDate);
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

