    public void doTheCheckinOfSharesPNRForOriginCityForPax(ExtentTest logInfo, String CheckinType, String TotalPax) {

        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String origin = pax.getSegmentOriginCity(0);

            boolean repeatTrns;
            int totalPax = Integer.parseInt(TotalPax);

            gl.ignoreTRNS(logInfo);

            for (int i = 0; i < totalPax; i++) {

                repeatTrns = true;

                String BagCount = "";
                int BaggageInfo;

//                ***** Entering Base command *****

                while (repeatTrns) {

                    if (CheckinType.equalsIgnoreCase("MultiplePaxCheckin")) {
                        gl.copyCmdToClipboardAndPaste(addCheckinCmdMultiplePaxCheckin(logInfo, origin, i), isharesPageObjects4.FORMSIZE_SELECT2_TEXTAREA);
                    } else {
                        gl.logCommand(logInfo, isharesPage2.addCheckinCmd(origin, i));
                        gl.copyCmdToClipboardAndPaste(isharesPage2.addCheckinCmd(origin, i), isharesPageObjects4.FORMSIZE_SELECT2_TEXTAREA);
                        gl.waitForProfileLoad();
                        BaggageInfo = isharesPage2.addCheckinCmd(origin, i).indexOf("\n") + 1;
                        BagCount = isharesPage2.addCheckinCmd(origin, i).substring(BaggageInfo);
                        System.out.println(BagCount + "BagCount");
                    }

                    isharesPageObjects4.SEND_ISHARES.click();
                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    String response = isharesPageObjects4.SHARES_RESPONSE.getText();

                    if (response.contains("NOT OPEN")) {
                        isharesPage2.openFlight(logInfo, mPassengers.get(getDriverID()).get(0).getSegmentFlight(0), gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0)), origin);
                        gl.ignoreTRNS(logInfo);

                    } else if (response.contains("PASSENGER DISPLAY") || response.contains("UNABLE TO RETRIEVE FDR-CHK DATA BASE")) {
                        Assert.fail();

                    } else if (response.contains("UNDELIVERED MESSAGES")) {

                        BaggageInfo = isharesPage2.addCheckinCmd(origin, i).indexOf("\n") + 1;
                        BagCount = isharesPage2.addCheckinCmd(origin, i).substring(BaggageInfo);

                    } else {

                        repeatTrns = false;
                    }
                }

                //***********Multiple item error*************//

                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                String response = isharesPageObjects4.SHARES_RESPONSE.getText();

                if (response.contains("MULTIPLE ITEMS")) {

                    String response1 = isharesPageObjects4.SHARES_RESPONSE.getText();

                    //Capturing ID for the PNR

                    int index = response1.indexOf(pax.getPnr());
                    String indexVal = response1.substring((index - 27), (index - 24)).trim();
                    String MultiListCmd = "6:LK-" + indexVal + "\n" + BagCount; // Selected pax with ID
                    gl.logCommand(logInfo, MultiListCmd);
                    gl.copyCmdToClipboardAndPaste(MultiListCmd, isharesPageObjects4.FORMSIZE_SELECT2_TEXTAREA);
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    gl.waitForProfileLoad();
                    isharesPageObjects4.SEND_ISHARES.click();

                }

                //**** PRIMARY DOCUMENT DETAILS*****

//                    *** PRIMARY DETAILS FOR OTHER PAX ***

                String IncompleteADCInfo;

                if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL")) {

                    IncompleteADCInfo = isharesPageObjects4.SHARES_RESPONSE.getText();

                } else {

                    IncompleteADCInfo = isharesPageObjects4.INPUT_TEXT_AREA_ROWS24.getText();

                }
                System.out.println(IncompleteADCInfo);
                String CompleteADCInfo = isharesPage2.add_PrimaryADC(IncompleteADCInfo, i);
                System.out.println(CompleteADCInfo);

                while (!isharesPage2.validatePrimaryADC(CompleteADCInfo, logInfo))  //to check Primary details are entered properly or not
                {
                    CompleteADCInfo = isharesPage2.reformPrimaryADC(i);

                }

                logInfo.pass("Primary Document Details entered for other PAX");

                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");


//       **** SECONDARY DOCUMENT DETAILS for other PAX ****

                if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL")) {

                    if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("DOCTYPE: P-PASSPORT")) {

                        String IncompleteDoctypeInfo = isharesPageObjects4.SHARES_RESPONSE.getText();
                        String CompleteDoctypeInfo = isharesPage2.add_SecondaryADC(IncompleteDoctypeInfo);
                        System.out.println(CompleteDoctypeInfo + "\n");

                        while (!isharesPage2.validateSecondaryADC(CompleteDoctypeInfo, logInfo))  //to check Secondary details are entered properly or not
                        {
                            CompleteDoctypeInfo = isharesPage2.reformSecondaryADC();

                        }
                    }

                } else {

                    if (isharesPageObjects4.INPUT_TEXT_AREA_ROWS24.getText().contains("DOCTYPE: P-PASSPORT")) {

                        String IncompleteDoctypeInfo = isharesPageObjects4.INPUT_TEXT_AREA_ROWS24.getText();
                        String CompleteDoctypeInfo = isharesPage2.add_SecondaryADC(IncompleteDoctypeInfo);
                        System.out.println(CompleteDoctypeInfo + "\n");
                        while (!isharesPage2.validateSecondaryADC(CompleteDoctypeInfo, logInfo))  //to check Secondary details are entered properly or not
                        {
                            CompleteDoctypeInfo = isharesPage2.reformSecondaryADC();
                        }
                    }

                }

                logInfo.pass("Secondary Document Details entered for other PAX");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                if (!CheckinType.equalsIgnoreCase("MultiplePaxCheckin")) {
                    if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL")) {

                        if (!isharesPageObjects4.SHARES_RESPONSE.getText().contains("SEATS ASSIGNED")) {

                            IncompleteADCInfo = isharesPageObjects4.SHARES_RESPONSE.getText();
                            System.out.println(IncompleteADCInfo);
                            CompleteADCInfo = isharesPage2.add_PrimaryADC(IncompleteADCInfo, i);
                            System.out.println(CompleteADCInfo);
                            while (!isharesPage2.validatePrimaryADC(CompleteADCInfo, logInfo)) {
                                CompleteADCInfo = isharesPage2.reformPrimaryADCMultipleSegments(i);
                            }

                        } else if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("SEATS ASSIGNED") && !pax.getPaxType().contains("NRSA") && !pax.getPaxType().contains("NRPS")) {
                            mPassengers.get(getDriverID()).get(i).setSequenceNo(Integer.parseInt(isharesPage2.returnSequenceNumber(logInfo, isharesPageObjects4.SHARES_RESPONSE.getText())));
                        }

                    } else {

                        if (!isharesPageObjects4.SHARES_RESPONSE.getText().contains("SEATS ASSIGNED")) {

                            IncompleteADCInfo = isharesPageObjects4.INPUT_TEXT_AREA_ROWS24.getText();
                            System.out.println(IncompleteADCInfo);
                            CompleteADCInfo = isharesPage2.add_PrimaryADC(IncompleteADCInfo, i);
                            System.out.println(CompleteADCInfo);

                            while (!isharesPage2.validatePrimaryADC(CompleteADCInfo, logInfo)) {
                                CompleteADCInfo = isharesPage2.reformPrimaryADCMultipleSegments(i);
                            }

                        } else if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("SEATS ASSIGNED") && !pax.getPaxType().contains("NRSA") && !pax.getPaxType().contains("NRPS")) {
                            mPassengers.get(getDriverID()).get(i).setSequenceNo(Integer.parseInt(isharesPage2.returnSequenceNumber(logInfo, isharesPageObjects4.SHARES_RESPONSE.getText())));
                        }
                    }
                    logInfo.pass("Primary Document Details entered for other PAX once again");
                }
            }

            mText.put(getDriverID(), isharesPageObjects4.SHARES_RESPONSE.getText());
            isharesPageObjects4.FORMSIZE_DROPDOWN.click();
            isharesPageObjects4.FORMSIZE_SELECT1.click();

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);

            Assert.fail("This step failed.. so stopping...");

        }

    }

