    public void changePaxToINF(ExtentTest logInfo, String Entry) {

        try {
//                3@DON/CHEN*-1INFSAM/01JUL23
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                Faker faker = new Faker(new Locale("en-US"));
                String lastname = faker.name().lastName().replaceAll("[^a-zA-Z0-9]", "");
                pax = mPassengers.get(getDriverID()).get(i);

                if (Entry.equalsIgnoreCase("ChangePaxType")) {
                    if (pax.getPaxType().equalsIgnoreCase("ADT")) {
                        pax.setPaxType("INF");
                        String command = "-" + (i + 1) + "@" + pax.getfName() + "/" + pax.getlName() + "*-1INF" + lastname + "/" +
                                mPassengers.get(getDriverID()).get(0).getDOB();

                        gl.logCommand(logInfo, command);
                        gl.sendCmdValidateResponse(command, "*", logInfo);
                        break;
                    }
                } else if (Entry.equalsIgnoreCase("ChangeINFName")) {
                    if (pax.getPaxType().equalsIgnoreCase("INF")) {
                        String command = "-" + (i + 1) + "@" + pax.getfName() + "/" + pax.getlName() + "*-1INF" + lastname + "/" +
                                mPassengers.get(getDriverID()).get(0).getDOB();

                        gl.logCommand(logInfo, command);
                        gl.sendCmdValidateResponse(command, "*", logInfo);
                        break;
                    }
                } else if (Entry.equalsIgnoreCase("DeleteInf")) {
                    if (pax.getPaxType().equalsIgnoreCase("INF")) {
                        //-3@*-INF
                        String command = "-" + (i + 1) + "@" + "*-INF";
                        gl.logCommand(logInfo, command);
                        gl.sendCmdValidateResponse(command, "*", logInfo);
                        break;
                    }
                }
            }

            if (Entry.equalsIgnoreCase("MulitInitalINF")) {
                String command = "-2REEVES/KMR/AMRS*-2INFSTEVENS*BEN.TIM/" + mPassengers.get(getDriverID()).get(0).getDOB();
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "*", logInfo);
            }
            if (Entry.equalsIgnoreCase("MulitInitalINS")) {
                String command = "-2JOLLY/JIMI/AMY*-INS/12JAN22-INFCHINU/" + mPassengers.get(getDriverID()).get(0).getDOB();
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "*", logInfo);
            }
            if (!Entry.equalsIgnoreCase("DeleteInf")) {
                gl.logCommand(logInfo,"6P#ER");
                gl.sendCmdValidateResponse("6P#ER", "6P#ER *", pax.getPnr().toUpperCase(), logInfo);
                gl.sendCmdIfRequired("ER", pax.getPnr().toUpperCase(), logInfo);
            }


        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

