    public void modifyAPISToNo(ExtentTest logInfo) {

        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String Lniata = pax.getLniata();
            int totalPax = mPassengers.get(getDriverID()).size();

            for (int i = 0; i < totalPax; i++) {
                String Address = "";
                //  W<LNIATA>*
                String code = "W" + Lniata + "*";
                gl.logCommand(logInfo, code);
                gl.sendCmdValidateResponse(code, "W" + Lniata, logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                String response = isharesPageObjects4.SHARES_RESPONSE.getText();
                String[] Response = response.split("\n");
                for (String Res : Response) {
                    String[] res = Res.split(" ");
                    if (res[0].contains("060")) {
                        Address = res[1];
                        break;
                    }
                }
                //            ZDFIL CM 9488E10E 000.FFF
                String command = "ZDFIL CM " + Address + " 000.FFF";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "FILE ADDRESS", logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                response = isharesPageObjects4.SHARES_RESPONSE.getText();
                Response = response.split("\n");
                for (String Res : Response) {
                    String[] res = Res.split(" ");

                    if (res[0].contains(" ")) {
                        if (res[1].contains("00000090-")) {
                            Address = res[5];
                            break;
                        }
                    } else {
                        if (res[0].contains("00000090-")) {
                            Address = res[4];
                            break;
                        }
                    }

                }

                if (i == 0) {
                    //ZAFIL CM 94016697 11C D5/VALDATA-E8
                    command = "ZAFIL CM " + Address + " 11C D5/VALDATA-E8";
                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, "BEGIN DISPLAY OF FILE ADDRESS", logInfo);
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                } else if (i == 1) {
                    // ZAFIL CM 94C3E843 2C1 D5/VALDATA-E8
                    command = "ZAFIL CM " + Address + " 2C1 D5/VALDATA-E8";
                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, "BEGIN DISPLAY OF FILE ADDRESS", logInfo);
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                } else if (i == 2) {
                    //ZAFIL CM 94C3E843 466 D5/VALDATA-E8
                    command = "ZAFIL CM " + Address + " 466 D5/VALDATA-E8";
                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, "BEGIN DISPLAY OF FILE ADDRESS", logInfo);
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                }
            }


        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }

