    public int[] getPaxIDsFromPaxListToModifyOrDeleteMessages(String response, int paxIndex) {
        int x = 0;
        int[] paxIDs = new int[2];

        for (int i = 0; i < response.split("\n").length; i++) {
            if (response.split("\n")[i].contains(mPassengers.get(getDriverID()).get(paxIndex).getfName()) || response.split("\n")[i].contains(mPassengers.get(getDriverID()).get(paxIndex).getlName())) {
                paxIDs[x++] = Integer.parseInt(response.split("\n")[i].substring(1, 5).trim());
            }
        }
        return paxIDs;
    }

