    public void changeNamesOfPassengersInMultiInitialPNRWithThreePax(ExtentTest logInfo) {
        try {
//                   -1@3MARTINEZ/ROMEO/RITA/ROMUALDO
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            Faker fname = new Faker(new Locale("en-US"));
            String LastName = fname.name().lastName();
            String FirstName = fname.name().firstName();
            String FirstName1 = fname.name().firstName();
            String FirstName2 = fname.name().firstName();

            String command = "-1@3" + LastName + "/" + FirstName + "/" + FirstName1 + "/" + FirstName2;
            command = command.toUpperCase();

            gl.sendCmdValidateResponse(command, command.toUpperCase(), logInfo);
            gl.logCommand(logInfo, command);
            logInfo.pass("I change the name of the passengers");

            gl.logCommand(logInfo, saveAndRetrieve);
            gl.sendCmdValidateResponse(saveAndRetrieve, "6P#ER *", command.substring(3), "TRANSACT WILL UNSEAT", logInfo);

            gl.logCommand(logInfo, endAndretrieve);
            gl.sendCmdIfRequired(endAndretrieve, FirstName.toUpperCase(), "TRANSACT WILL UNSEAT", logInfo);

            String response = isharesPageObjects4.SHARES_RESPONSE.getText();
            Assert.assertTrue(response.contains(LastName.toUpperCase() + "/" + FirstName.toUpperCase()) || response.contains("TRANSACT WILL UNSEAT"));

            if (response.contains("TRANSACT WILL UNSEAT")) {
                gl.sendCmdValidateResponse(endAndretrieve, pax.getPnr(), logInfo);
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


