    public void removeVolunteerStatusAfterCheckinForMultiInitialPax(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            int[] paxIDs = new int[2];
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            boolean repeatTrns;
            gl.ignoreTRNS(logInfo);

            repeatTrns = true;

            for (int a = 0; a < 2; a++) {
                while (repeatTrns) {
//                        6:DVR829/28DECPTY-JOHN/KRIN/FRIN
                    String cmd = "6:DVR" + pax.getSegmentFlight(0) + "/" + date + pax.getSegmentOriginCity(0) + "-"
                            + mPassengers.get(getDriverID()).get(0).getfName() + "/";

                    for (int j = 0; j < mPassengers.get(getDriverID()).size(); j++) {
                        cmd = cmd + "/" + mPassengers.get(getDriverID()).get(j).getlName();
                    }

                    gl.logCommand(logInfo, cmd);
                    gl.sendCmdValidateResponse(cmd, logInfo);
                    String response = isharesPageObjects4.SHARES_RESPONSE.getText();

                    if (response.contains("NOT OPEN")) {
                        isharesPage2.openFlight(logInfo, mPassengers.get(getDriverID()).get(0).getSegmentFlight(0), gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0)), pax.getSegmentOriginCity(0));
                        gl.ignoreTRNS(logInfo);
                    } else if (response.contains("PASSENGER DISPLAY") || response.contains("UNABLE TO RETRIEVE FDR-CHK DATA BASE")) {
                        Assert.fail();
                    } else if (response.contains("MULTIPLE ITEMS")) {
                        paxIDs = getPaxIDs(response, 0);
                        repeatTrns = false;
                    } else {
                        repeatTrns = false;
                    }

                }

//                   6:LDVR-175
                String command = "6:LDVR-" + paxIDs[a];
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "PSGR REMOVED FROM VOL OVERSOLD LIST", logInfo);
            }

//               6-LD360/06MARPTY#OS
            String displayList = "6:LD" + pax.getSegmentFlight(0) + "/" + gl.sharesFormatDateFromGUI(pax.getSegmentDate(0)) +
                    pax.getSegmentOriginCity(0) + "|OS";

            gl.logCommand(logInfo, displayList);
            gl.sendCmdValidateResponse(displayList, "OVER SELLS", logInfo);

            Assert.assertFalse(isharesPageObjects4.SHARES_RESPONSE.getText().contains(pax.getPnr()) || isharesPageObjects4.SHARES_RESPONSE.getText().contains(pax.getPnr2()));

            isharesPageObjects4.FORMSIZE_DROPDOWN.click();
            isharesPageObjects4.FORMSIZE_SELECT1.click();

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

