    public void changeASpecificSeatOfASegment(ExtentTest logInfo) {
        try {
            Random random = new Random();
            String[] alphabets = new String[]{"A", "B", "C", "D", "E", "F"};
            String newSeatNo;

//            6:A
            String command = "6:A";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "SEATS ASSIGNED", logInfo);

            String seatNumber = null;
            String response = isharesPageObjects4.SHARES_RESPONSE.getText();

            for (int i = 0; i < response.split("\n").length; i++) {
                if (response.split("\n")[i].contains(mPassengers.get(getDriverID()).get(0).getfName())) {
                    String[] temp = response.split("\n")[i].split(" ");
                    seatNumber = temp[temp.length - 1].replace("*", "");
                    System.out.println("Seat Number : " + seatNumber);
                }
            }

            gl.logCommand(logInfo, "6P#ER");
            gl.sendCmdValidateResponse("6P#ER", seatNumber, logInfo);

            gl.sendCmdIfRequired("ER", seatNumber, logInfo);

//            6-A1#8F
//            @#8A

            do {
                int max = 35, min = 5;
                int number = random.nextInt(max - min + 1) + min;
                newSeatNo = number + alphabets[random.nextInt(5)];

                isharesPageObjects4.FORMSIZE_DROPDOWN.click();
                isharesPageObjects4.FORMSIZE_SELECT2.click();

                command = "6:A1|" + newSeatNo + "\n" + "@|" + seatNumber;
                gl.copyCmdToClipboardAndPaste(command, isharesPageObjects4.FORMSIZE_SELECT2_TEXTAREA);
                isharesPageObjects4.SEND_ISHARES.click();
                gl.waitForProfileLoad();
            } while (!isharesPageObjects4.SHARES_RESPONSE.getText().contains(newSeatNo));

            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            response = isharesPageObjects4.SHARES_RESPONSE.getText();
            Assert.assertTrue(response.contains(newSeatNo));

            isharesPageObjects4.FORMSIZE_DROPDOWN.click();
            isharesPageObjects4.FORMSIZE_SELECT1.click();

            gl.logCommand(logInfo, "6P#ER");
            gl.sendCmdValidateResponse("6P#ER", newSeatNo, logInfo);

            gl.sendCmdIfRequired("ER", newSeatNo, logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


