    public void forRedemptionFAFAvailability(ExtentTest logInfo, String OriginCity, String Destination, String redemption, String withDate, String formatType) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            //A PTYLAX 01JUN$P/R
            //A PTYLAX 01JUN$G/R
            String command = "";
            if (withDate.equals("No")) {
                command = "A " + OriginCity + Destination + redemption;
            } else {
                if (formatType.equals("noSpace")) {
                    command = "A" + date + OriginCity + Destination + redemption;
                } else {
                    command = "A " + OriginCity + Destination + " " + date + " " + redemption;
                }
            }
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, date, OriginCity, logInfo);
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

