    public void validate_PNR_Data(ExtentTest logInfo, String PNRInfo, String PaymentType) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            int TotalPax = mPassengers.get(getDriverID()).size();
            String TicketNumber;

            String pnr = pax.getPnr();
            String retrievePnr = "*" + pnr;
            gl.logCommand(logInfo, retrievePnr);
            gl.sendCmdValidateResponse(retrievePnr, pnr, logInfo);

            int segSequence = 1;
            String command = "";
            if (PaymentType.equalsIgnoreCase("Cash")) {
                //T-$
                command = "T-$";
            } else if (PaymentType.equalsIgnoreCase("Visa")) {
                command = "T-$EE" + mPassengers.get(getDriverID()).get(0).getTicketNumber() + "/FVI#ET";
            } else if (PaymentType.equalsIgnoreCase("EvenExchangeWithCash")) {
                //  T-$EE22300000822/FCASH#N1.1#ET
                for (int j = 0; j <= TotalPax - 1; j++) {
                    command = "";
                    TicketNumber = mPassengers.get(getDriverID()).get(j).getTicketNumber();
                    //      T-$EE23022300008146/FCASH#N1.1#ET
                    command = "T-$EE" + TicketNumber + "/FCASH|N" + segSequence + "." + (j + 1) + "|ET";
                }
            } else if (PaymentType.equalsIgnoreCase("UsingRefund")) {
                String tax = "2865.0";
                String TaxName = "OXUS22.20/AY5.60/XT";
                //   T-$UE23022300011705/FVI/OB2566.00/OXUS22.20/AY5.60/XT101.72/RF$RD*PENALTY$25#N1.1#ET
                for (int j = 0; j <= TotalPax - 1; j++) {
                    TicketNumber = mPassengers.get(getDriverID()).get(j).getTicketNumber();
                    command = "T-$UE" + TicketNumber + "/FVI/OB" + tax + "0/" + TaxName + "142.80" + "/RF$RD*PENALTY$25|N" + (j + 2) + "." + segSequence + "|ET";
                }
            } else if (PaymentType.equalsIgnoreCase("VOID")) {
                command = "T-ETVOID1";
            } else if (PaymentType.equalsIgnoreCase("REVOKE")) {
                command = "T-ETREVOKE";
            } else if (PaymentType.equalsIgnoreCase("REMOVE REVOKE")) {
                command = "T-ETREMOVE/R1.1";
            }

            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "RESTRICTED ENTRY", "OK", logInfo);
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }
    }

