    public void addGivenFQTV(ExtentTest logInfo, String FQTVCount, String lastNameFQTV) {

//    NOTE: LIMIT OF ADDING FQTV PAX IS 5
        try {
            int fqtvCount = Integer.parseInt(FQTVCount);

            JSONParser jsonParser = new JSONParser();
            FileReader reader = new FileReader(".\\src\\test\\resources\\jsonfiles\\frequentFlyerDetails.json");
            Object obj = jsonParser.parse(reader);

            JSONArray fqtvList = (JSONArray) obj;

            ArrayList<String> Gender = new ArrayList<>();
            Gender.add("Male");
            Gender.add("Female");
            Random random = new Random();

            Faker faker = new Faker(new Locale("en-US"));
            Passenger pax;
            System.out.println("FQTV First Names list =" + lastNameFQTV);

            if (lastNameFQTV.contains("-")) {
                String[] fqtvPaxLastNameslist = lastNameFQTV.split("-");

                for (int j = 0; j < fqtvPaxLastNameslist.length; j++) {
                    for (int i = 0; i < fqtvList.size(); i++) {
                        JSONObject fqtvPassenger = (JSONObject) fqtvList.get(i); // Fetching ith JSON Object From the JSON List in JSON FIle
                        JSONObject fqtvPAX = (JSONObject) fqtvPassenger.get("FrequentFlyer"); //Name of the JSON OBJECT in the LIST
                        String lastName = (String) fqtvPAX.get("surName");

                        if (lastName.equalsIgnoreCase(fqtvPaxLastNameslist[j])) {
                            pax = new Passenger();
                            pax.setfName((String) fqtvPAX.get("firstName"));
                            pax.setlName((String) fqtvPAX.get("surName"));
                            String phoneNumber = faker.phoneNumber().cellPhone().replaceAll("[^a-zA-Z0-9]", "");
                            phoneNumber = phoneNumber.substring(3);
                            pax.setPhoneNumber(phoneNumber);
                            pax.setFFNumber((String) fqtvPAX.get("FFNumber"));
                            pax.setDOB(gl.generateDateOfBirthNew("ADT"));
                            pax.setEmail("testone@testone.com");
                            pax.setGender(Gender.get(random.nextInt(Gender.size())));
                            pax.setCountryCode("US");
                            pax.setDocNumber(faker.regexify("[A-Z]{2}[0-9]{6}"));
                            pax.setPaxType("FQTV");

                            mPassengers.get(getDriverID()).add(pax);
                            break;
                        }

                    }
                }

            } else {
                for (int k = 0; k < fqtvList.size(); k++) {

                    JSONObject fqtvPassenger = (JSONObject) fqtvList.get(k); // Fetching ith JSON Object From the JSON List in JSON FIle
                    JSONObject fqtvPAX = (JSONObject) fqtvPassenger.get("FrequentFlyer"); //Name of the JSON OBJECT in the LIST
                    String lastName = (String) fqtvPAX.get("surName");

                    if (lastName.equalsIgnoreCase(lastNameFQTV)) {
                        pax = new Passenger();
                        pax.setfName((String) fqtvPAX.get("firstName"));
                        pax.setlName((String) fqtvPAX.get("surName"));
                        String phoneNumber = faker.phoneNumber().cellPhone().replaceAll("[^a-zA-Z0-9]", "");
                        phoneNumber = phoneNumber.substring(3);
                        pax.setPhoneNumber(phoneNumber);

                        pax.setFFNumber((String) fqtvPAX.get("FFNumber"));
                        pax.setDOB(gl.generateDateOfBirthNew("ADT"));
                        pax.setEmail("testone@testone.com");
                        pax.setGender(Gender.get(random.nextInt(Gender.size())));
                        pax.setCountryCode("US");
                        pax.setDocNumber(faker.regexify("[A-Z]{2}[0-9]{6}"));
                        pax.setPaxType("FQTV");

                        mPassengers.get(getDriverID()).add(pax);
                        break;
                    }
                }
            }
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

