                    put("EXIT", "E");
                    put("WING", "W");
                    put("ADVANCED", "A");
                    put("HELD", "H");
                    put("PERMBLKD", "P");
                    put("PREMIUM", "V");
                    put("BULKHEAD", "Q");
                    put("INFANT/TAKEN", "F");
                    put("INFANT/SEATED", "$");
                    put("REGULAR", "T");
                    put("PREMIUM WINDOW", "J");
