    public void generateNewPassengerData(ExtentTest logInfo) {
        try {

            int noOfAdt = 0;
            int noOfChd = 0;
            int noOfIns = 0;
            int noOfInf = 0;
            for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("ADT"))
                    noOfAdt++;
                else if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("CHD"))
                    noOfChd++;
                else if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("INF"))
                    noOfInf++;
                else if (mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("INS"))
                    noOfIns++;
            }

            mPassengersPNR2.put(getDriverID(), mPassengers.get(getDriverID()));  //Making mPassengersPNR2 reference to PassengerData for PNR1

            ArrayList<Passenger> passengers = new ArrayList<>();
            mPassengers.put(getDriverID(), passengers);

            isharesPage2.addAdultPassengers(String.valueOf(noOfAdt));
            isharesPage2.addChildPassengers(String.valueOf(noOfChd));
            isharesPage2.addInfantWithSeatPassengers(String.valueOf(noOfInf));
            isharesPage2.addInfantWithoutSeatPassengers(String.valueOf(noOfIns));

            System.out.println("mPassengersPNR2: " + mPassengersPNR2.get(getDriverID()).get(0).getFullName());
            System.out.println("mPassengers: " + mPassengers.get(getDriverID()).get(0).getFullName());

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


    public void sharesCheckinForMultiplePNRSWithDifferentPax(ExtentTest logInfo, String origin) {
        try {

            gl.ignoreTRNS(logInfo);

//        6:M808/05MARPTY-LUCI-FSR-JIM-DEMIN-CLORA
//        B0

            String cmd = "";
            for (Passenger pax : mPassengers.get(getDriverID()))
                cmd = cmd + "-" + pax.getfName();

            for (Passenger pax : mPassengersPNR2.get(getDriverID()))
                cmd = cmd + "-" + pax.getfName();

            cmd = "6:M" + mPassengers.get(getDriverID()).get(0).getSegmentFlight(0)
                    + "/" + gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0))
                    + origin + cmd;

            System.out.println("Command: " + cmd);

            ArrayList<Passenger> allPNRsData = new ArrayList<>();

            allPNRsData.addAll(mPassengers.get(getDriverID()));
            allPNRsData.addAll(mPassengersPNR2.get(getDriverID()));

            mPassengers.put(getDriverID(), allPNRsData);

            for (int j = 0; j < mPassengers.get(getDriverID()).size(); j++) {
                gl.ignoreTRNS(logInfo);

                isharesPageObjects4.FORMSIZE_DROPDOWN.click();
                isharesPageObjects4.FORMSIZE_SELECT24.click();
                isharesPageObjects4.INPUT_TEXT_AREA_ROWS24.click();

                gl.logCommand(logInfo, cmd);
                gl.copyCmdToClipboardAndPaste(cmd, isharesPageObjects4.FORMSIZE_SELECT2_TEXTAREA);
                isharesPageObjects4.SEND_ISHARES.click();
                gl.waitForProfileLoad();
                String response = isharesPageObjects4.SHARES_RESPONSE.getText();
                gl.logResponse(logInfo, response);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                if (response.contains("FLT NOT OPEN") || response.contains("SHIP NOT ASSIGNED")) {
                    isharesPage2.openFlight(logInfo);
                    isharesPageObjects4.FORMSIZE_DROPDOWN.click();
                    isharesPageObjects4.FORMSIZE_SELECT24.click();

                    isharesPageObjects4.INPUT_TEXT_AREA_ROWS24.click();
                    gl.copyCmdToClipboardAndPaste(cmd, isharesPageObjects4.FORMSIZE_SELECT2_TEXTAREA);
                    isharesPageObjects4.SEND_ISHARES.click();

                    response = isharesPageObjects4.SHARES_RESPONSE.getText();
                    gl.logResponse(logInfo, response);
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                }
//
//              //**** PRIMARY DOCUMENT DETAILS*****
//
                String IncompleteADCInfo;
                if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL")) {
                    IncompleteADCInfo = isharesPageObjects4.SHARES_RESPONSE.getText();
                } else {
                    IncompleteADCInfo = isharesPageObjects4.INPUT_TEXT_AREA_ROWS24.getText();
                }
                System.out.println(IncompleteADCInfo);
                String CompleteADCInfo = isharesPage2.add_PrimaryADC(IncompleteADCInfo, j);
                System.out.println(CompleteADCInfo);
                while (!isharesPage2.validatePrimaryADC(CompleteADCInfo, logInfo))  //to check Primary details are entered properly or not
                {
                    CompleteADCInfo = isharesPage2.reformPrimaryADC(j);
                }
                logInfo.pass("Primary Document Details entered for " + mPassengers.get(getDriverID()).get(j).getFullName());
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                Assert.assertTrue(isharesPageObjects4.SHARES_RESPONSE.getText().contains("SEATS ASSIGNED") || isharesPageObjects4.SHARES_RESPONSE.getText().contains("CABIN STBY LIST"));
                break;
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

