    public void search_flightavailabilitywithScommand(ExtentTest logInfo, String origin, String destination, String params, String type) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String StartDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));

            String command = "";
            //S HNLLAX-UA/AA
            //S26SEPLAXPTY800P-CM
            //AC HNL
            if (type.equals("Date")) {
                command = "S" + StartDate + origin + destination + params;
            } else if (type.equals("noDate")) {
                command = "S " + origin + destination + " " + params;
            } else if (type.equals("AC")) {
                command = "AC " + params;
            }
            String validateText = "";
            String validateText1 = "";
            if (params.contains("UA")) {
                validateText = "UA";
                validateText1 = "NO ITEMS FOR DISPLAY";
            } else if (params.contains("CM")) {
                validateText = "CM";
                validateText1 = "NO ITEMS FOR DISPLAY";
            } else if (params.contains("AA")) {
                validateText = "AA";
                validateText1 = "NO ITEMS FOR DISPLAY";
            } else {
                validateText = "UA";
                validateText1 = "NO ITEMS FOR DISPLAY";
            }

            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, validateText, validateText1, logInfo);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

