    public void displayAPISDetailsAfterDividingThePNR(ExtentTest logInfo, String noOfPaxDivided) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String PNR1 = pax.getPnr();
            String PNR2 = pax.getPnr2();
            int Totalpax = mPassengers.get(getDriverID()).size();

            isharesPageObjects4.FORMSIZE_DROPDOWN.click();
            isharesPageObjects4.FORMSIZE_SELECT1.click();

            String command = "*" + PNR1;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "DIVIDED", logInfo);
            for (int j = 1; j <= Totalpax - Integer.parseInt(noOfPaxDivided); j++) {
                gl.logCommand(logInfo, "*AP" + j);
                gl.sendCmdValidateResponse("*AP" + (j), "ADVANCED PASSENGER INFORMATION", logInfo);
            }

            command = "*" + PNR2;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "SPLIT PARTY", logInfo);
            for (int j = 1; j <= Integer.parseInt(noOfPaxDivided); j++) {
                gl.logCommand(logInfo, "*AP" + j);
                gl.sendCmdValidateResponse("*AP" + (j), "ADVANCED PASSENGER INFORMATION", logInfo);
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void changeTheFQTVPassengerName(ExtentTest logInfo, String index) {
        try {
//                   -1@CARRIZO/PATRICIA
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String fname = "";
            String lname = "";

            List<String> FQTVNames = new ArrayList<>();
            FQTVNames.add("COPA/VIRGINIA");
            FQTVNames.add("PLATINUM/JENNY");


            for (String FQTVName : FQTVNames) {
                if (!pax.getfName().contains(FQTVName)) {
                    fname = FQTVName.split("/")[0];
                    lname = FQTVName.split("/")[1];
                }
            }
            String command = "-" + index + "@" + fname + "/" + lname;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, command.toUpperCase(), logInfo);
            logInfo.pass("I change the name of the FQTV passenger");

            gl.logCommand(logInfo, saveAndRetrieve);
            gl.sendCmdValidateResponse(saveAndRetrieve, "6P#ER *", fname.toUpperCase(), "TRANSACT WILL UNSEAT", logInfo);

            gl.sendCmdIfRequired(endAndretrieve, fname.toUpperCase(), "TRANSACT WILL UNSEAT", logInfo);

            String response = isharesPageObjects4.SHARES_RESPONSE.getText();
            Assert.assertTrue(response.contains(fname.toUpperCase() + "/" + lname.toUpperCase()) || response.contains("TRANSACT WILL UNSEAT"));

            if (response.contains("TRANSACT WILL UNSEAT")) {
                gl.logCommand(logInfo, endAndretrieve);
                gl.sendCmdValidateResponse(endAndretrieve, pax.getPnr(), logInfo);
            }

            pax.setfName(fname);
            pax.setlName(lname);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


