    public void deleteAnExistingPaxAndAddANewPaxToThePNR(ExtentTest logInfo, String paxIndex, String paxType) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String fname = null;
            String lname = null;
            Faker faker = new Faker(new Locale("en-US"));

//               -1@
            String command = "-" + paxIndex + "@";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, command + " *", logInfo);
            logInfo.pass("I delete a passenger from the pnr");

            if (paxType.contains("Adult")) {
                fname = faker.name().firstName();
                fname = fname.replaceAll("[^a-zA-Z0-9]", "").toUpperCase();

                lname = faker.name().lastName();
                lname = lname.replaceAll("[^a-zA-Z0-9]", "").toUpperCase();
            }

            //         adding a new passenger
            command = "-" + fname + "/" + lname;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, command + " *", pax.getPnr(), logInfo);

            gl.logCommand(logInfo, "6P");
            gl.sendCmdValidateResponse("6P", "6P *", pax.getPnr(), "PNR MODIFIED", logInfo);

            gl.sendCmdIfRequired("ER", fname, "SIMULT CHGS TO PNR", logInfo);

            if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("SIMULT CHGS TO PNR")) {
                gl.logCommand(logInfo, "IR");
                gl.sendCmdValidateResponse("IR", pax.getPnr(), logInfo);

                //               -1@
                command = "-" + paxIndex + "@";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, command + " *", logInfo);
                logInfo.pass("I delete a passenger from the pnr");

                command = "-" + fname + "/" + lname;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, command + " *", pax.getPnr(), logInfo);

                gl.logCommand(logInfo, "6P");
                gl.sendCmdValidateResponse("6P", "6P *", pax.getPnr(), "PNR MODIFIED", logInfo);

                gl.sendCmdIfRequired("ER", fname, logInfo);
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


    public void checkIfThePOSISFCBEnabled(ExtentTest logInfo) {
        try {
//            KC/CQ/*PTY

            String FinalPOS = null;

            List<String> ListOfPOS = new ArrayList<>();
            ListOfPOS.add("PTY");
            ListOfPOS.add("LAX");
            ListOfPOS.add("MEX");
            ListOfPOS.add("SJO");

            POSCity:
            for (String POS : ListOfPOS) {
                String command = "KC/CQ/*" + POS;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, logInfo);
                String response = isharesPageObjects4.SHARES_RESPONSE.getText();
                for (int i = 0; i < response.split("\n").length; i++) {
                    if (response.split("\n")[i].contains(POS)) {
                        String[] temp = response.split("\n")[i].split(" ");
                        if (temp[temp.length - 1].contains("EF") || temp[temp.length - 1].contains("E")) {
                            FinalPOS = POS;
                            System.out.println("FINALS POS : " + FinalPOS);
                            break POSCity;
                        }
                    }
                }
            }
            mPassengers.get(getDriverID()).get(0).setPOS(FinalPOS);

            String command = "W" + mPassengers.get(getDriverID()).get(0).getLniata() + "C3" + FinalPOS + "CM";
            System.out.println("LNIATA : " + command);
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "AAA CREATED", logInfo);

            gl.logCommand(logInfo, "BSIA");
            gl.sendCmdValidateResponse("BSIA", logInfo);
            logInfo.pass("I enter BSIA command for signing in");
            gl.ignoreTRNS(logInfo);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void enterA_RCommandToCheckReturnAvailabilty(ExtentTest logInfo, String origin, String destination) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String newDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0) + 3);
            String response;

            String command = "A " + origin + destination + " " + date;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, logInfo);
            response = isharesPageObjects4.SHARES_RESPONSE.getText();
            gl.checkForErrors(command, response, logInfo);
            if (!response.contains(origin + destination))
                Assert.fail();


//            Search for Return availability for same date/time
            command = "A*R";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, logInfo);
            response = isharesPageObjects4.SHARES_RESPONSE.getText();
            gl.checkForErrors(command, response, logInfo);
            if (!response.contains(origin + destination))
                Assert.fail();

//            Return availability for same date/new time
            command = "A*R/7P";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, logInfo);
            response = isharesPageObjects4.SHARES_RESPONSE.getText();
            gl.checkForErrors(command, response, logInfo);
            if (!response.contains(origin + destination))
                Assert.fail();

//            Search for Return availability for New date/Same time
            command = "A*R/" + newDate;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, logInfo);
            response = isharesPageObjects4.SHARES_RESPONSE.getText();
            gl.checkForErrors(command, response, logInfo);
            if (!response.contains(origin + destination))
                Assert.fail();

//            Search for Return availability for New date/time
            command = "A*R/" + newDate + "/10A";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, logInfo);
            response = isharesPageObjects4.SHARES_RESPONSE.getText();
            gl.checkForErrors(command, response, logInfo);
            if (!response.contains(origin + destination))
                Assert.fail();

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


