    public void enterT$UE_ETCommandToRunUnEvenExhangeEntry(ExtentTest logInfo) {
        try {
            //T-$UE/FCASH/OB1954.54/OX95.46/XF3.00/AC$CK#ET
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            gl.logCommand(logInfo, "T-ETCKPRICE");
            gl.sendCmdValidateResponse("T-ETCKPRICE", "SUM OF TOTAL FARE", logInfo);

            String Response = isharesPageObjects4.SHARES_RESPONSE.getText();
            String TotalAmount = null;
            String[] response = Response.split("\n");

            for (String s : response) {
                if (s.contains("ADD COLLECT") || s.contains("REFUND")) {
                    String[] seat = s.split(" ");
                    TotalAmount = seat[seat.length - 5].replace("$", "");
                    System.out.println(seat[seat.length - 5]);
                }
            }

            System.out.println("tax amount " + TotalAmount);
            String TaxName = pax.getTax(0);

            float Tax = Integer.parseInt(TotalAmount.substring(0, TotalAmount.indexOf(".")));
            float tax = Tax / pax.getfName().length();
            System.out.println("tax: " + tax);

            String command = "T-$UE/FCASH/OB" + tax + "/" + TaxName + "95.46/XF3.00/AC$CK|ET";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "NON-INVOICE TKT STOCK", "INDIVIDUAL TAX FIELDS", logInfo);

            command = "IR";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "T:$UE", pax.getfName(), logInfo);

            gl.logCommand(logInfo, "FR/ALL");
            gl.sendCmdValidateResponse("FR/ALL", logInfo);
//
            gl.logCommand(logInfo, "6P#ER");
            gl.sendCmdValidateResponse("6P#ER", logInfo);

            gl.logCommand(logInfo, endAndretrieve);
            gl.sendCmdValidateResponse(endAndretrieve, logInfo);
            Response = isharesPageObjects4.SHARES_RESPONSE.getText();

            if (Response.contains("SIMULT")) {
                gl.logCommand(logInfo,"IR");
                gl.sendCmdValidateResponse("IR", mPassengers.get(getDriverID()).get(0).getPnr(), logInfo);
            }

            gl.logCommand(logInfo, ignoreAndRetrieve);
            gl.sendCmdValidateResponse(ignoreAndRetrieve, mPassengers.get(getDriverID()).get(0).getPnr(), logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

