    public void sharesCheckinForMultiplePNRs(ExtentTest logInfo, String origin) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            boolean repeatTrns;
            String response;

            gl.ignoreTRNS(logInfo);

            for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {

                repeatTrns = true;
                String BagCount = "";

                //       ***** Entering Base command *****

                while (repeatTrns) {

                    String Cmd = isharesPage2.addCheckinCmd(origin, i);
                    gl.logCommand(logInfo, Cmd);
                    gl.copyCmdToClipboardAndPaste(Cmd, isharesPageObjects4.FORMSIZE_SELECT2_TEXTAREA);

                    int BaggageInfo = Cmd.indexOf("\n") + 1;
                    BagCount = Cmd.substring(BaggageInfo);
                    System.out.println(BagCount + "BagCount");

                    isharesPageObjects4.SEND_ISHARES.click();
                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    response = isharesPageObjects4.SHARES_RESPONSE.getText();
                    gl.logResponse(logInfo, response);

                    if (response.contains("NOT OPEN")) {
                        isharesPage2.openFlight(logInfo, mPassengers.get(getDriverID()).get(0).getSegmentFlight(0), gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0)), origin);
                        gl.ignoreTRNS(logInfo);
                    } else if (response.contains("PASSENGER DISPLAY") || response.contains("UNABLE TO RETRIEVE FDR-CHK DATA BASE")) {
                        Assert.fail();
                    } else if (response.contains("MULTIPLE ITEMS")) {
                        repeatTrns = false;
                    } else {
                        repeatTrns = false;
                    }

                }

                //***********Multiple item error*************//
                response = isharesPageObjects4.SHARES_RESPONSE.getText();

                if (response.contains("MULTIPLE ITEMS"))
                {

                    //Capturing ID for the PNR
                    if(pax.getPnr()!=null)
                    {
                        enterMultiListCommand(logInfo,response,pax.getPnr(),BagCount);
                        addAPISDetails(logInfo,i);
                        Assert.assertTrue(isharesPageObjects4.SHARES_RESPONSE.getText().contains("SEATS ASSIGNED"),"Checkin Unsuccessful");
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    }


                    if(pax.getPnr2()!=null)
                    {
                        String Cmd = isharesPage2.addCheckinCmd(origin, i);
                        gl.logCommand(logInfo, Cmd);
                        gl.copyCmdToClipboardAndPaste(Cmd, isharesPageObjects4.FORMSIZE_SELECT2_TEXTAREA);

                        isharesPageObjects4.SEND_ISHARES.click();
                        gl.waitForProfileLoad();
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        response = isharesPageObjects4.SHARES_RESPONSE.getText();
                        gl.logResponse(logInfo, response);

                        enterMultiListCommand(logInfo,response,pax.getPnr2(),BagCount);
                        addAPISDetails(logInfo,i);
                        Assert.assertTrue(isharesPageObjects4.SHARES_RESPONSE.getText().contains("SEATS ASSIGNED"),"Checkin Unsuccessful");
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                    }

                }
                else
                {
                    addAPISDetails(logInfo,i);
                    Assert.assertTrue(isharesPageObjects4.SHARES_RESPONSE.getText().contains("SEATS ASSIGNED"), "Checkin Unsuccessful");
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                }

            }// end of pax for loop


            mText.put(getDriverID(), isharesPageObjects4.SHARES_RESPONSE.getText());
            isharesPageObjects4.FORMSIZE_DROPDOWN.click();
            isharesPageObjects4.FORMSIZE_SELECT1.click();

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

