    public void searchFlightAvailabilityUsingDifferentFormat(ExtentTest logInfo, String Origin, String Destination, String format) {
        String command;

        try {
            int departuredate = mPassengers.get(getDriverID()).get(0).getSegmentDate(0);
            String DateFormatted = gl.plusDaysFromTodayNew(departuredate);
            LocalDateTime departureDate = DateUtil.formatToLocalDateTime(DateFormatted, "10:10");
            String departureDateFormatted = DateUtil.formatDateToSharesDateFormat(departureDate.toLocalDate());

            if (format.equalsIgnoreCase("DateAnd$COSAndAirline")) {          // A PTYMCO 1OCT $A-CO
                command = "A " + Origin + Destination + " " + departureDateFormatted + " $" + mPassengers.get(getDriverID()).get(0).getCOS() + "-" + mPassengers.get(getDriverID()).get(0).getAirline(0);
            } else if (format.equalsIgnoreCase("$B4/7")) {          // A 360/22APR PTYLAX $B4/7
                command = "A " + mPassengers.get(getDriverID()).get(0).getSegmentFlight(0) + "/" + departureDateFormatted + " " + Origin + Destination + " $B4/7";
            } else {
                command = "A " + departureDateFormatted + " " + Origin + Destination;
            }

            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, logInfo);

            gl.waitForProfileLoad();

            String response = isharesPageObjects4.SHARES_RESPONSE.getText();
            gl.checkForErrors(command, response, logInfo);
            Assert.assertTrue(response.contains("NO AVBL FLIGHTS") || response.contains(mPassengers.get(getDriverID()).get(0).getSegmentFlight(0)));

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

