    public void releaseHeldSeatBySpecifyingSeatNumber(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String flight = pax.getSegmentFlight(0);
            String origin = pax.getSegmentOriginCity(0);
            String seatNumber = null;

//              6:H334/09JULPTY-TEST/RIO
            String command = "6:H" + flight + "/" + date + origin + "-" + pax.getfName() + "/" + pax.getlName();
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "SEATS ASSIGNED   FLT", flight, logInfo);

            for (int i = 0; i < isharesPageObjects4.SHARES_RESPONSE.getText().split("\n").length; i++) {
                if (isharesPageObjects4.SHARES_RESPONSE.getText().split("\n")[i].contains("ETKT")) {
                    String temp[] = isharesPageObjects4.SHARES_RESPONSE.getText().split("\n")[i].split(" ");
                    seatNumber = temp[temp.length - 1];
                    seatNumber = seatNumber.substring(0, seatNumber.length() - 1);
                    System.out.println("Seat Number : " + seatNumber);
                    break;
                }
            }

//              6:CU334/09JULPTY#6A
            command = "6:CU" + pax.getSegmentFlight(0) + "/" + date + pax.getSegmentOriginCity(0) + "|" + seatNumber;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "SEAT RELEASED", logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

