    public void enterBFCommandToPrintBoardingPassMultiInitial(ExtentTest logInfo, String boardingPassType) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flight = pax.getSegmentFlight(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String origin = pax.getSegmentOriginCity(0);
            int totalpax = mPassengers.get(getDriverID()).size();

            String Command = null;
            //Command = "6:BF" + flight + "/" + date + origin + "-" + mPassengers.get(getDriverID()).get(0).getfName();

            if (boardingPassType.equalsIgnoreCase("ForceBoarding")) {
                Command = "6:BF" + flight + "/" + date + origin + "-" + mPassengers.get(getDriverID()).get(0).getfName();
                for (int i = 0; i < totalpax; i++) {
                    if (mPassengers.get(getDriverID()).get(i).getIsSameSurname()) {

                        Command = Command + "/" + mPassengers.get(getDriverID()).get(i).getlName();

                    }

                }
                gl.logCommand(logInfo, Command);
                gl.sendCmdValidateResponse(Command, pax.getfName(), "FORCE PRINT BOARDING PASSES", logInfo);
            } else if (boardingPassType.equalsIgnoreCase("ThruBoarding")) {
                Command = "6:BF" + flight + "/" + date + origin + "-" + mPassengers.get(getDriverID()).get(0).getfName();
                for (int i = 0; i < totalpax; i++) {
                    if (mPassengers.get(getDriverID()).get(i).getIsSameSurname()) {

                        Command = Command + "/" + mPassengers.get(getDriverID()).get(i).getlName();

                    }
                }
                gl.logCommand(logInfo, Command);
                gl.sendCmdValidateResponse(Command, pax.getfName(), "FORCE PRINT BOARDING PASSES", logInfo);
            } else if (boardingPassType.equalsIgnoreCase("TestBoarding")) {

                Command = "6:BT";
                gl.logCommand(logInfo, Command);
                gl.sendCmdValidateResponse(Command, "TEST BOARDING PASS SENT", logInfo);
                logInfo.pass("TEST BOARDING PASS ");

            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }
    }

