    public String GenerateUniquePnr(ExtentTest logInfo) {
//        *ER-SUSUHU

        String GDSUniquePnr = "";
        String UniquePnr = "S" + RandomStringUtils.randomAlphabetic(5).toUpperCase();
        gl.sendCmdValidateResponse("*ER-" + UniquePnr, logInfo);
        String Response = isharesPageObjects4.SHARES_RESPONSE.getText();
        for (int j = 0; j < mPassengers.get(getDriverID()).size(); j++) {
            mPassengers.get(getDriverID()).get(j).setPnr2(UniquePnr);
        }

        int i = 0;
        while (!Response.contains("NO MATCH FOUND")) {
            UniquePnr = "S" + RandomStringUtils.randomAlphabetic(5).toUpperCase();
            for (int j = 0; j < mPassengers.get(getDriverID()).size(); j++) {
                mPassengers.get(getDriverID()).get(j).setPnr2(UniquePnr);
            }
            gl.logCommand(logInfo, "*ER-" + UniquePnr);
            gl.sendCmdValidateResponse("*ER-" + UniquePnr, logInfo);
            Response = isharesPageObjects4.SHARES_RESPONSE.getText();
            i++;
            if (i > 15) {
                break;
            }
        }

        return UniquePnr;
    }

