    public void T$ToTicketByDifferentMethods(ExtentTest logInfo, String value) {
        try {
            if (value.equalsIgnoreCase("CK#@")) {
                //T-$CK#@

                String Command = "T-$CK#@";
                gl.logCommand(logInfo, Command);
                gl.sendCmdValidateResponse(Command, "NON-INVOICE TKT STOCK", "TKT NBR ISSUED", logInfo);

            } else if (value.equalsIgnoreCase("CK#@FREFLOWEMARK")) {
                //T-$CK#@ F R E F L O W R E M A R K

                String Command = "T-$CK#@ F R E F L O W R E M A R K";
                gl.logCommand(logInfo, Command);
                gl.sendCmdValidateResponse(Command, "NON-INVOICE TKT STOCK", "CK FOR POSSIBLE FULL/PARTIAL EXISTING E-TKT-RETRY", logInfo);

            } else if (value.equalsIgnoreCase("CK#@973370374")) {
                //T-$CK#@973370374
                String Command = "T-$CK#@973370374";
                gl.logCommand(logInfo, Command);
                gl.sendCmdValidateResponse(Command, "FIN OR IGN TRANS", "CK FOR POSSIBLE FULL/PARTIAL EXISTING E-TKT-RETRY", "TKT FLD UPDATED/IGN", logInfo);

            } else if (value.equalsIgnoreCase("T-$EE/FCASH")) {
                //T-$CK#@ F R E F L O W R E M A R K

                String Command = "T-$EE/FCASH";
                gl.logCommand(logInfo, Command);
                gl.sendCmdValidateResponse(Command, "NON-INVOICE TKT STOCK", "CHECK IN REQUIRED", logInfo);
            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


