    public void performVoluntaryUpgradeChangeOfCOSformultiinitial(ExtentTest logInfo, String COS) {
        try {
            gl.ignoreTRNS(logInfo);
            String Command;
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flight = pax.getSegmentFlight(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String origin = pax.getSegmentOriginCity(0);
            int totalpax = mPassengers.get(getDriverID()).size();

            Command = "6:GV" + flight + "/" + date + origin
                    + "-" + pax.getfName();

//                 6:GV473/09AUGLAX-AA/JINI.C
            for (int i = 0; i < totalpax; i++) {

                if (mPassengers.get(getDriverID()).get(i).getIsSameSurname()) {
                    Command = Command + "/" + mPassengers.get(getDriverID()).get(i).getlName();
                }
            }
            Command = Command + "." + COS;
            gl.logCommand(logInfo, Command);
            gl.sendCmdValidateResponse(Command, "SEATS ASSIGNED", logInfo);
            gl.sendCmdValidateResponse("*" + mPassengers.get(getDriverID()).get(0).getPnr(), logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

