    public void ReplaceTheSeatAfterCheckIn(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flight = pax.getSegmentFlight(0);
            String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String Origin = pax.getSegmentOriginCity(0);
            String Destination = pax.getSegmentOriginCity(0);
            String COS = pax.getCOS();

            String Seatcmd = "";
            boolean SeatAssigned = false;
            String[] SeatAlphabet = {"A", "F"};

            //            6:*302/18JANPTY.Y
            String command2 = "6:*" + flight + "/" + Date + Origin + "." + COS;
            gl.sendCmdValidateResponse(command2, Origin, "@-AVAIL  .-TAKEN", logInfo);
            gl.ignoreTRNS(logInfo);

            for (int j = 0; j < mPassengers.get(getDriverID()).size(); j++) {
                pax = mPassengers.get(getDriverID()).get(j);
                gl.ignoreTRNS(logInfo);

                for (String Alphabet : SeatAlphabet) {
                    for (int i = 5; i <= 7; i++) {
                        //6:409/10JULSFO-TEST/PERRY#@35A

                        if (pax.getPaxType().equalsIgnoreCase("INF")) {
                            Seatcmd = "6:" + flight + "/" + Date
                                    + Origin + "-" + pax.getAccompaniedPaxDetails().getfName() + "/" + pax.getAccompaniedPaxDetails().getlName()
                                    + "|@" + i + Alphabet;
                        } else {
                            Seatcmd = "6:" + flight + "/" + Date
                                    + Origin + "-" + pax.getfName() + "/" + pax.getlName()
                                    + "|@" + i + Alphabet;
                        }
                        gl.logCommand(logInfo, Seatcmd);
                        gl.sendCmdValidateResponse(Seatcmd, logInfo);
                        logInfo.pass("I assign seat");

                    }
                    String Response = isharesPageObjects4.SHARES_RESPONSE.getText();

                    if (Response.contains("MULTIPLE ITEMS")) {
                        String response1 = isharesPageObjects4.SHARES_RESPONSE.getText();

                        //Capturing ID for the PNR
                        int index = response1.indexOf(mPassengers.get(getDriverID()).get(0).getPnr());
                        String indexVal = response1.substring((index - 27), (index - 24)).trim();

                        String MultiListCmd = "6:LK-" + indexVal; // Selected pax with ID
                        gl.logCommand(logInfo, MultiListCmd);
                        gl.sendCmdValidateResponse(MultiListCmd, logInfo);
                        logInfo.pass("I enter 6:LK- command");

                    }
                }
            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


    public void ToGetFlightInfoForStarAllianceAirline(ExtentTest logInfo, String Airline) {
        try {
            //      21249/09JULPTY-UA
            //      28565/10JUL/MDE-AV
            //      21916/27MARPTY-AA
            //      277/10JULIST-TK
            //      21002/10JUL-LH
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flight = pax.getSegmentFlight(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String Origin = pax.getSegmentOriginCity(0);
            String Carrier1 = pax.getAirline(0);
            if (!Airline.equalsIgnoreCase(Carrier1)) {
                Carrier1 = Airline;
            }
            String command = "";
            if (Carrier1.equalsIgnoreCase("AV")) {
                command = "2" + flight + "/" + date + "-" + Carrier1;
            } else if (Carrier1.equalsIgnoreCase("LH")) {
                command = "2" + flight + "/" + date + "-" + Carrier1;
            } else {
                command = "2" + flight + "/" + date + Origin + "-" + Carrier1;
            }

            gl.logCommand(logInfo, command);
            if (Carrier1.equalsIgnoreCase("AA") || Carrier1.equalsIgnoreCase("DL") || Carrier1.equalsIgnoreCase("EK") || Carrier1.equalsIgnoreCase("IB")) {
                gl.sendCmdValidateResponse(command, "CARRIER", "CARRIER NOT IN STAR ALLIANCE", logInfo);
            } else {
                gl.sendCmdValidateResponse(command, "STARNET", "*** STARNET FLIFO DATA ***", logInfo);
            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

