    public void enter6BCommandToReplaceTheBagCountandPassengerDetails(ExtentTest logInfo, String BaggageWeight, String BaggageCount) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String Flight = pax.getSegmentFlight(0);
            String Origin = pax.getSegmentOriginCity(0);
            int pcount = mPassengers.get(getDriverID()).size();
            int totalBag = Integer.parseInt(BaggageCount);
            int Weight = pax.getBaggageWeight();
            String TagNum = "";

            while (totalBag >= 1) {
                int x = (int) ((Math.random() * (555555 - 111111)) + 222222);
                TagNum = x + "/" + TagNum;
                totalBag--;
            }
            TagNum = (TagNum.substring(0, TagNum.length() - 1));

            //6:274/05DECPTY-TEST/ONE
            //@B1/50-CM645793@C1.PTY
            String command = "6:" + Flight + "/" + Date + Origin + "-" + pax.getfName() + "/" + pax.getlName()
                    + "\n" + "@B" + BaggageCount + "/" + BaggageWeight + "-CM" + TagNum + "@C1." + Origin;
            gl.logCommand(logInfo, command);
            gl.sendCopiedCmdValidateResponse2(logInfo, command, "MULTIPLE ITEMS", "PASSENGER DISPLAY");

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void enter6KTCommandToDoMassTransferWithAPIS(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String oldFlightNo = pax.getSegmentFlight(0);
            String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String Date1 = gl.sharesFormatDateFromGUI(pax.getSegmentDate(1));
            String newFlightNo = pax.getSegmentFlight(1);
            String destinationCity = pax.getSegmentDestinationCity(0);
            String Origin = pax.getSegmentOriginCity(0);
            String destinationCity1 = pax.getSegmentDestinationCity(1);
            String Origin1 = pax.getSegmentOriginCity(1);

            //6-KT485/16DECPTY-MIA.246/17DECMIA-PTY
            String command = "6-KT" + oldFlightNo + "/" + Date + Origin + "-" + destinationCity + "."
                    + newFlightNo + "/" + Date1 + Origin1 + "-" + destinationCity1;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "MASS TRANSFER COMPLETE", "SHIP NOT ASSIGNED", logInfo);

            if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("SHIP NOT ASSIGNED")) {
                isharesPageObjects4.COMMAND_INPUTAREA_ISHARES.sendKeys(Keys.CONTROL + "a" + Keys.BACK_SPACE);
                isharesPage2.openFlight(logInfo, pax.getSegmentFlight(1), Date1, pax.getSegmentOriginCity(1));

                isharesPageObjects4.FORMSIZE_DROPDOWN.click();
                isharesPageObjects4.FORMSIZE_SELECT1.click();
                gl.waitForProfileLoad();

                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "MASS TRANSFER COMPLETE", logInfo);

            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

