    public void RefundwithExchange(ExtentTest logInfo, String segSequence, String RefundType) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            int TotalPax = mPassengers.get(getDriverID()).size();

            String retrieve = "ER";
            gl.logCommand(logInfo, "ER");
            gl.sendCmdValidateResponse(retrieve, "PNR MODIFIED", "ETKT/PNR MODIFIED- CHK ITIN", "MODIFY REC", logInfo);

            gl.sendCmdIfRequired(retrieve, pax.getPnr(), "RCVD-P", logInfo);

            int lengthOfTaxesArray = pax.getListOfTaxes().size();
            String taxesArraylistlength = Integer.toString(lengthOfTaxesArray);

            if (lengthOfTaxesArray == 2) {
                String allTaxes = pax.getListOfTaxes().get(0) + "/" + pax.getListOfTaxes().get(1);
                for (int j = 1; j <= TotalPax; j++) {
                    pax = mPassengers.get(getDriverID()).get(j - 1);
                    String Ticket = pax.getTicketNumber();
                    String reissue = "";

                    if (RefundType.equalsIgnoreCase("RefundUsingCashRD")) {
                        //T-$UE23022300000612/FCK/OB1959.00/OXS11.06/UK42.63/XT255.35/RF$RD#@XFNIL#ET
                        reissue = "T-$UE" + "/FCASH/OB" + pax.getBaseFare() + "/" + allTaxes + "/RF$RD#@XFNIL#ET";
                    }

                    gl.logCommand(logInfo, reissue);
                    gl.sendCmdValidateResponse(reissue, "FARE", "SEE ADV PURCHASE", "SIMULT", logInfo);

                    // Saving the transaction
                    gl.logCommand(logInfo, ignoreAndRetrieve);
                    gl.sendCmdValidateResponse(ignoreAndRetrieve, pax.getPnr(), logInfo);
                }
            } else if (lengthOfTaxesArray == 3) {
                String allTaxes = pax.getListOfTaxes().get(0) + "/" + pax.getListOfTaxes().get(1) + "/" + pax.getListOfTaxes().get(2);
                for (int j = 1; j <= TotalPax; j++) {
                    pax = mPassengers.get(getDriverID()).get(j - 1);
                    String Ticket = pax.getTicketNumber();
                    String reissue = "";
                    // Doing Reissue  T-$UE23022300006271/FVI/OB1262.00/OXCO49.00/XT142.80/AC$5555555555554444/1230/N1234#N3.2#ET - XT , T1, US, UK, A1, AH
                    if (RefundType.equalsIgnoreCase("Reissue_WithSegment")) {
//
                        reissue = "T-$UE" + Ticket + "/FVI/OB" + pax.getBaseFare() + "/" + allTaxes + "/" + "AC$5555555555554444/1230/N1234|N" + (j) + "." + segSequence + "|ET";
                        // reissue = "T-$UE" + pax.getTicketNumber() + "/FVI/OB" + tax + "0/" + TaxName + "142.80" + "/RF$RD*PENALTY$25|N" + (j + 1) + "." + segSequence + "|ET";

                    } else if (RefundType.equalsIgnoreCase("RefundCashWithRD")) {
                        //T-$UE23022300006400/FCASH/OB2031.00/OXJS15.00/AH1.25/XT32.30/RF$RD#@XFPTY3#ET
                        if (pax.getListOfTaxes().get(0).contains("S1")) {
                            allTaxes = "OX" + pax.getListOfTaxes().get(0) + "/" + pax.getListOfTaxes().get(1) + "/" + pax.getListOfTaxes().get(2);
                        }
                        reissue = "T-$UE/FCASH/OB" + pax.getBaseFare() + "/" + allTaxes + "/RF$RD#@XFNIL|ET";
                    }


                    gl.logCommand(logInfo, reissue);
                    gl.sendCmdValidateResponse(reissue, "FARE", "SEE ADV PURCHASE", "SIMULT", logInfo);

                    // Saving the transaction
                    gl.logCommand(logInfo, ignoreAndRetrieve);
                    gl.sendCmdValidateResponse(ignoreAndRetrieve, pax.getPnr(), logInfo);
                }
            } else if (lengthOfTaxesArray == 1) {
                String allTaxes = pax.getListOfTaxes().get(0) + "/";
                for (int j = 1; j <= TotalPax; j++) {
                    pax = mPassengers.get(getDriverID()).get(j - 1);
                    String Ticket = pax.getTicketNumber();
                    String reissue = "";
                    // Doing Reissue  T-$UE23022300006271/FVI/OB1262.00/OXCO49.00/XT142.80/AC$5555555555554444/1230/N1234#N3.2#ET - XT , T1, US, UK, A1, AH
                    if (RefundType.equalsIgnoreCase("Reissue_WithSegment")) {
                        reissue = "T-$UE" + Ticket + "/FVI/OB" + pax.getBaseFare() + "/" + allTaxes + "/" + "AC$4911830000000/1224/N1234|N" + (j) + "." + segSequence + "|ET";
                    } else if (RefundType.equalsIgnoreCase("RefundUsingCashRD")) {
                        //T-$UE23022300000612/FCK/OB1959.00/OXS11.06/UK42.63/XT255.35/RF$RD#@XFNIL#ET
                        reissue = "T-$UE" + "/FCASH/OB" + pax.getBaseFare() + "/" + allTaxes + "/RF$RD#@XFNIL#ET";
                    }

                    gl.logCommand(logInfo, reissue);
                    gl.sendCmdValidateResponse(reissue, "FARE", "SEE ADV PURCHASE", "SIMULT", logInfo);

                    // Saving the transaction
                    gl.logCommand(logInfo, ignoreAndRetrieve);
                    gl.sendCmdValidateResponse(ignoreAndRetrieve, pax.getPnr(), logInfo);
                }
            }
            //Checking PNR history
            gl.logCommand(logInfo, checkPnrHistory);
            gl.sendCmdValidateResponse(checkPnrHistory, "EXCHANGED", "CPN", logInfo);

            //Check Ticket Status
            gl.logCommand(logInfo, checkTicketStatus);
            gl.sendCmdValidateResponse(checkTicketStatus, "EXCHANGED", "CPN", logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

