    public void checkDividedPnr(ExtentTest logInfo, String uniquePnr) {

        gl.ignoreTRNS(logInfo);

        Passenger pax = mPassengers.get(getDriverID()).get(0);
        gl.logCommand(logInfo, "*ER-" + uniquePnr);
        gl.sendCmdValidateResponse("*ER-" + uniquePnr, "DIVIDED", "SPLIT", logInfo);
        logInfo.pass("I retrieve PNR for TTY message");

        String response = isharesPageObjects4.SHARES_RESPONSE.getText();
        String pnr_split = response.substring(0, 6);

        //To get the divided pnr
        if (response.contains("SPLIT PARTY")) {
            String searchString = "SPLIT PARTY";
            int index = response.indexOf(searchString);

            String split_value = response.substring(index + searchString.length()).trim();
            System.out.println(split_value);
            String replacedString = split_value.replace("/", "");
            String pnr_divided = replacedString.substring(0, 6);
            System.out.println(pnr_divided);

            pax.setPnr(pnr_divided);
        } else if (response.contains("DIVIDED")) {
            String searchString = "DIVIDED";
            int index = response.indexOf(searchString);
            System.out.println(index);
            String split_value = response.substring(index + searchString.length()).trim();
            String replacedString = split_value.replace("/", "");
            System.out.println(replacedString);
            //pnr_divided = split_value.substring(2, 8);
            String pnr_divided = replacedString.substring(3, 9);
            System.out.println(pnr_divided);
            //String pnr_divided_new = replacedString.substring(3,9);
            pax.setPnr(pnr_divided);
        }
        gl.logCommand(logInfo, "*" + pnr_split);
        gl.sendCmdValidateResponse("*" + pnr_split, "SPLIT", pax.getPnr(), logInfo);
        gl.logCommand(logInfo, "*H");
        gl.sendCmdValidateResponse("*H", "REC LOC", "RCVD", logInfo);

        gl.logCommand(logInfo, "*" + pax.getPnr());
        gl.sendCmdValidateResponse("*" + pax.getPnr(), "DIVIDED", pnr_split, logInfo);

        gl.logCommand(logInfo, "*H");
        gl.sendCmdValidateResponse("*H", "REC LOC", "RCVD", logInfo);

        logInfo.pass("I retrive PNR for TTY message");
    }

    public void TTYMessageSameSurnamePassengerPnrWithSSR(ExtentTest logInfo, String SystemType, String SSRType) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String PaxFname = pax.getfName();
            int TotalSegments = mPassengers.get(getDriverID()).get(0).getTotalSegments();
            String totalSegments = String.valueOf(TotalSegments);
            String airline = pax.getAirline(0);
            String flight = pax.getSegmentFlight(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String origin = pax.getSegmentOriginCity(0);
            String destination = pax.getSegmentDestinationCity(0);

//======================================================
//To fetch the correct name for Same surname passenger
            String Surname = null;
            int sameSurnamePaxCount = 0;

            for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                if (mPassengers.get(getDriverID()).get(i).getIsSameSurname()) {
                    Surname = mPassengers.get(getDriverID()).get(i).getfName();
                    sameSurnamePaxCount++;
                }
            }

            String FullName = Surname;

            for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                if (mPassengers.get(getDriverID()).get(i).getIsSameSurname()) {
                    FullName = FullName + "/" + mPassengers.get(getDriverID()).get(i).getlName();
                }
            }

            FullName = "" + FullName;
            System.out.println("Passenger Details Name :" + FullName);

// Create the command to enter message
            String Line2 = null;   //PTYRMCM
            if (globalConstants.testEnv.equalsIgnoreCase("sharesURL")) {
                Line2 = "PTYRMCM";
            } else {
                Line2 = "CLTYSCM";
            }

            String UniquePnr = isharesPage2.GenerateUniquePnr(logInfo);
//            Y
//            PTYRMCM
//            .HDQRM1S 231031
//            HDQ1S ANUBH1
//            2BARRY/BATE/JIM
//            CM0322Y09NOVCLOPTYNN2
            String BasicAirlinePnr = "Y" + "\n" +
                    Line2 + "\n" +
                    ".HDQRM1" + SystemType + " 231031" + "\n" +
                    "HDQ1" + SystemType + " " + UniquePnr + "\n" + mPassengers.get(getDriverID()).size() + FullName + "\n" +
                    airline + "0" + flight + pax.getCOS() + date + origin + destination + "NN" + mPassengers.get(getDriverID()).size();


            isharesPageObjects4.FORMSIZE_DROPDOWN.click();
            isharesPageObjects4.FORMSIZE_SELECT12.click();

            gl.logCommand(logInfo, BasicAirlinePnr);
            System.out.println("BaseCommand " + BasicAirlinePnr);
            gl.copyCmdToClipboardAndPaste(BasicAirlinePnr, isharesPageObjects4.FORMSIZE_SELECT2_TEXTAREA);

            isharesPageObjects4.SEND_ISHARES.click();
            logInfo.pass("I passed TTY message");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            gl.waitForProfileLoad();
            String response = isharesPageObjects4.SHARES_RESPONSE.getText();
            gl.logResponse(logInfo, response);
            Assert.assertTrue(response.contains("MESSAGE ACCEPTED"));

            isharesPageObjects4.FORMSIZE_DROPDOWN.click();
            isharesPageObjects4.FORMSIZE_SELECT1.click();

            isharesPage2.checkTTYPNR(logInfo, UniquePnr);

            logInfo.pass("I enter TTY message to generate PNR");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            //Divide/Split PNR

            if (SSRType.equalsIgnoreCase("Divide")) {
                String PassengerName1 = Surname + "/" + mPassengers.get(getDriverID()).get(0).getlName();
                String SSRCommand = "Y" + "\n" +
                        Line2 + "\n" +
                        ".HDQRM1" + SystemType + " 231031" + "\n" + "DVD" + "\n" +
                        "HDQ1" + SystemType + " " + UniquePnr + "\n" + destination + airline + " " + pax.getPnr()
                        + "\n" + "1" + PassengerName1 + "\n" +
                        airline + "0" + flight + pax.getCOS() + date + origin + destination + "HK1" + "\n" + "OSI YY RLOC HDQ1S TST1DV";


                isharesPageObjects4.FORMSIZE_DROPDOWN.click();
                isharesPageObjects4.FORMSIZE_SELECT12.click();

                gl.logCommand(logInfo, SSRCommand);
                System.out.println("SSR Command " + SSRCommand);
                gl.copyCmdToClipboardAndPaste(SSRCommand, isharesPageObjects4.FORMSIZE_SELECT2_TEXTAREA);

                isharesPageObjects4.SEND_ISHARES.click();
                logInfo.pass("I passed TTY message");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                gl.waitForProfileLoad();
                response = isharesPageObjects4.SHARES_RESPONSE.getText();
                gl.logResponse(logInfo, response);
                Assert.assertTrue(response.contains("MESSAGE ACCEPTED"));

                isharesPageObjects4.FORMSIZE_DROPDOWN.click();
                isharesPageObjects4.FORMSIZE_SELECT1.click();

                checkDividedPnr(logInfo, UniquePnr);

                logInfo.pass("I enter TTY message to generate PNR");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void LA$CommandToGetLowestAvailableFare(ExtentTest logInfo, String value) {
        try {
            String Command = "";
            if (value.equalsIgnoreCase("LA$")) {
                Command = "LA$";
            } else if (value.equalsIgnoreCase("LP$")) {
                Command = "LP$";
            } else if (value.equalsIgnoreCase("LA$B-F")) {
                //Returns the lowest fare in the First class cabin for all fare components
                Command = "LA$B-F";
            } else if (value.equalsIgnoreCase("LA$B-C")) {
                //Returns the lowest fare in the Business class cabin for all fare components
                Command = "LA$B-C";
            } else if (value.equalsIgnoreCase("LA$B-W")) {
                //Returns the lowest fare in the Premium Economy class cabin for all fare components
                Command = "LA$B-W";
            } else if (value.equalsIgnoreCase("LA$B-Y")) {
                //Returns the lowest fare in the Economy class cabin for all fare components
                Command = "LA$B-Y";
            } else if (value.equalsIgnoreCase("LA$S1")) {
                //Returns the lowest fare in the Economy class cabin for all fare components
                Command = "LA$S1";
            }
            else if (value.equalsIgnoreCase("LA$C")) {
                //Returns the lowest fare in the class cabin for all fare components
                Command = "LA$C";
            }

            gl.logCommand(logInfo, Command);
            gl.sendCmdValidateResponse(Command, "USD FARE    TAX-USD", "STANDARD BAGGAGE CHARGES", logInfo);
            gl.scrollPageDown();
            logInfo.pass("To Get Lowest Available Fare");

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }
    }

