    public void A_CommandToCheckTheFlightAvailabilityOfTheFormat(ExtentTest logInfo, String type) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String origin = pax.getSegmentOriginCity(0);
            String destination = pax.getSegmentDestinationCity(0);
            String startDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            if (type.equalsIgnoreCase("N/A")) {
                //$:A
                String command = "$:A";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "ALTERNATE SERVICE", startDate, logInfo);
            } else if (type.equalsIgnoreCase("6P")) {
                //$:A 17MAR 6P
                String command = "$:A " + startDate + " 6P";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "ALTERNATE SERVICE", startDate, logInfo);
            } else if (type.equalsIgnoreCase("6P $YN")) {
                //$:A 17MAR 6P $YN
                String command = "$:A " + startDate + " 6P $YN";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "NO AVBL FLIGHTS", logInfo);
            }
            else if (type.equalsIgnoreCase("6P $Y")) {
                //$:A 17MAR 6P $YN
                String command = "$:A " + startDate + " 6P $Y";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, startDate, logInfo);
            }
            else if (type.equalsIgnoreCase("$:S_6P")) {
                //$:S 06MAR 6P
                String command = "$:S " + startDate + " 6P";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, origin + destination, logInfo);
            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }
    }

