    public void dividePNRUsingPaxNumberToDividePassengers(ExtentTest logInfo, String noOfPaxToDivide) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            DividePNR:
            for (int i = 1; ; i++)
            {
                String command = "D" + noOfPaxToDivide;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, logInfo);
                logInfo.pass("I divide the PNR");

                gl.logCommand(logInfo, "6P");
                gl.sendCmdValidateResponse("6P", "6P *", logInfo);
                logInfo.pass("I save the divided PNR");

                gl.logCommand(logInfo, "F");
                gl.sendCmdValidateResponse("F", "RECORD FILED", logInfo);

                String Response = isharesPageObjects4.SHARES_RESPONSE.getText();
                String PNR2 = Response.substring(13, 19);           // Stored newly created PNR in map mPnr1

                if (pax.getPnr2() == null || pax.getPnr2().isEmpty()) {
                    pax.setPnr2(PNR2);
                    logInfo.pass("I capture divided PNR (PNR2)");
                } else {
                    pax.setPnr3(PNR2);
                    logInfo.pass("I capture divided PNR (PNR3)");
                }
                logInfo.pass("I capture divided PNR");

                gl.logCommand(logInfo, "6P#ER");
                gl.sendCmdValidateResponse("6P#ER", "6P#ER *", pax.getPnr(), logInfo);

                gl.sendCmdIfRequired("ER", pax.getPnr(), "SIMULT CHGS TO PNR", logInfo);
                logInfo.pass("I save and retrieve divided pnr");


                if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("SIMULT CHGS TO PNR")) {
                    gl.logCommand(logInfo, "IR");
                    gl.sendCmdValidateResponse("IR", pax.getPnr(), logInfo);

                } else if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("RCVD-P")) {
                    break;
                }

            }

            if (!pax.getPnr2().isEmpty()) {

                gl.logCommand(logInfo, "*" + pax.getPnr2());
                gl.sendCmdValidateResponse("*" + pax.getPnr2(), pax.getPnr2(), logInfo);
            } else {

                gl.logCommand(logInfo, "*" + pax.getPnr3());
                gl.sendCmdValidateResponse("*" + pax.getPnr3(), pax.getPnr3(), logInfo);

            }
            logInfo.pass("I save and retrieve divided pnr");


        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

