    public void PerformAdjustmentOnETKTCoupon(ExtentTest logInfo) {
        try {
//                   T-$EI/S1#UA-1033PTYIAH27NOV#INVOL#ET
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            gl.logCommand(logInfo, saveAndRetrieve);
            gl.sendCmdValidateResponse(saveAndRetrieve, logInfo);

            String retrieve = "ER";
            gl.logCommand(logInfo, "ER");
            gl.sendCmdValidateResponse(retrieve, "PNR MODIFIED", "ETKT/PNR MODIFIED- CHK ITIN", logInfo);

            gl.sendCmdIfRequired(retrieve, pax.getPnr(), "RCVD-P", logInfo);

            String oldFlightNumber = pax.getOldFlightNumber();
            String origin_old = pax.getOldOrigin();
            String destination_old = pax.getOldDestination();
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));

//            T-$EI/S1#UA-1033PTYIAH27NOV#INVOL#ET     (UA is the old Airline, 1034-Old Flight, PTY-IAH -> Old Markets and 27 Nov-> OlD Date)

            String command = "T-$EI/S1|UA-" + oldFlightNumber
                    + origin_old + destination_old + date + "|INVOL|ET";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "-OK-", logInfo);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

