            gl.sendCmdValidateResponse(Command, "NO FLIGHTS PRESENT", logInfo);

            //    KE*RDY
            Command = "KE*RDY";
            gl.logCommand(logInfo, Command);
            gl.sendCmdValidateResponse(Command, "NO FLIGHTS PRESENT", logInfo);

            //    KSSALL/CM
