    public void enter6HCommandForHeldSeat(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flight = pax.getSegmentFlight(0);
            String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String Origin = pax.getSegmentOriginCity(0);
            String COS = pax.getCOS();

            String Seatcmd = "";
            boolean SeatAssigned = false;
            String[] SeatAlphabet = {"A", "F"};

            for (int j = 0; j < mPassengers.get(getDriverID()).size(); j++) {
                pax = mPassengers.get(getDriverID()).get(j);
                gl.ignoreTRNS(logInfo);

                for (String Alphabet : SeatAlphabet) {
                    for (int i = 5; i <= 35; i++) {

                        // 6:H461/10AUGSJO-PETER/HARRY#6F
                        Seatcmd = "6:H" + flight + "/" + Date
                                + Origin + "-" + pax.getfName() + "/" + pax.getlName()
                                + "|" + i + Alphabet;
                        gl.logCommand(logInfo, Seatcmd);
                        gl.sendCmdValidateResponse(Seatcmd, logInfo);

                        if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("NOT OPEN")) {
                            isharesPage2.openFlight(logInfo, mPassengers.get(getDriverID()).get(0).getSegmentFlight(0), gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0)), Origin);
                            gl.ignoreTRNS(logInfo);
                        } else if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("MULTIPLE ITEMS")) {
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                            String response1 = isharesPageObjects4.SHARES_RESPONSE.getText();

                            // Checking PNR in multiple item list
                            for (int k = 0; k < 7; k++) {
                                if (response1.contains(mPassengers.get(getDriverID()).get(0).getPnr())) {
                                    response1 = isharesPageObjects4.SHARES_RESPONSE.getText();
                                    break;
                                } else {
                                    gl.sendCmdValidateResponse("MD", logInfo);
                                    response1 = isharesPageObjects4.SHARES_RESPONSE.getText();
                                }
                            }

                            //Capturing ID for the PNR
                            int index = response1.indexOf(mPassengers.get(getDriverID()).get(0).getPnr());
                            String indexVal = response1.substring((index - 27), (index - 24)).trim();

                            String MultiListCmd = "6:LH-" + indexVal; // Selected pax with ID
                            gl.logCommand(logInfo, MultiListCmd);
                            gl.sendCmdValidateResponse(MultiListCmd, logInfo);

                        }
                        String Response = isharesPageObjects4.SHARES_RESPONSE.getText();
                        if (Response.contains("SEATS ASSIGNED")) {
                            break;
                        }

                    }
                }
            }
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
        }
    }

