    public void changeAndReplacePaxNameInPaxList(ExtentTest logInfo, String index, String indexPaxList) {
        try {
            int indexOfPaxList = Integer.parseInt(indexPaxList);
//                   -1@POP/SAM
            Passenger pax = mPassengers.get(getDriverID()).get(indexOfPaxList);
            Faker fname = new Faker(new Locale("en-US"));
            String FirstName = fname.name().firstName();
            String LastName = fname.name().lastName();

            String command = "-" + index + "@" + FirstName + "/" + LastName;

            gl.sendCmdValidateResponse(command, command.toUpperCase(), logInfo);
            gl.logCommand(logInfo, command);
            logInfo.pass("I change the name of the passenger");
            pax.setfName(FirstName);
            pax.setlName(LastName);
            gl.logCommand(logInfo, saveAndRetrieve);
            gl.sendCmdValidateResponse(saveAndRetrieve, "6P#ER *", FirstName.toUpperCase(), "TRANSACT WILL UNSEAT", logInfo);

            gl.logCommand(logInfo, endAndretrieve);
            gl.sendCmdIfRequired(endAndretrieve, FirstName.toUpperCase(), "TRANSACT WILL UNSEAT", logInfo);

            String response = isharesPageObjects4.SHARES_RESPONSE.getText();
            Assert.assertTrue(response.contains(FirstName.toUpperCase() + "/" + LastName.toUpperCase()) || response.contains("TRANSACT WILL UNSEAT"));

            if (response.contains("TRANSACT WILL UNSEAT")) {
                gl.sendCmdValidateResponse(endAndretrieve, pax.getPnr(), logInfo);
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

