    public void enterUpGradeCabinCommandWithEachPax(ExtentTest logInfo, String cos1) {
        try {
            ArrayList<Passenger> pax = mPassengers.get(getDriverID());
            String date = gl.sharesFormatDateFromGUI(pax.get(0).getSegmentDate(0));
            String flight = pax.get(0).getSegmentFlight(0);
            String Origin = pax.get(0).getSegmentOriginCity(0);

            for (int i = 0; i < pax.size(); i++) {

                String command = "6:GV" + flight + "/" + date + Origin + "-" + pax.get(i).getfName() + "/" + pax.get(i).getlName() + "." + cos1;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "MULTIPLE ITEMS", "SEATS ASSIGNED", "UNABLE PROC-MULT NAME PNR", logInfo);

                String response = isharesPageObjects4.SHARES_RESPONSE.getText();
                String indexValue = "";
                if (response.contains("MULTIPLE ITEMS")) {

                    //Capturing ID for the PNR
                    String[] lines = response.split("\n");
                    for(int j = 0; j < lines.length; j++) {
                        if (lines[j].contains(pax.get(0).getPnr()) || lines[j].contains(pax.get(0).getPnr2()) || lines[j].contains(pax.get(0).getPnr3())) {
                            String[] indexVal = lines[j].split(" ");
                            indexValue = indexVal[1];
                            break;
                        }
                    }
                    String MultiListCmd = "6:LGV-" + indexValue;
                    gl.logCommand(logInfo, MultiListCmd);
                    gl.sendCmdValidateResponse(MultiListCmd, "SEATS ASSIGNED", logInfo);

                }
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

