    public String addManualBaggageWithoutCheckinCmd(String origin, int paxIndex, int totalBag, int Weight, int tagNum)   //Update for inf
    {
        gl.waitForProfileLoad();
        Passenger pax = mPassengers.get(getDriverID()).get(paxIndex);
        isharesPageObjects4.FORMSIZE_DROPDOWN.click();
        isharesPageObjects4.FORMSIZE_SELECT24.click();

        String cmd = null;
        int TotalBag = totalBag;

        String TagNum = String.valueOf(tagNum);

        while (totalBag > 1) {
            int x = (int) ((Math.random() * (555555 - 111111)) + 222222);
            TagNum = TagNum + "/" + pax.getAirline(0) + x;
            totalBag--;
        }
        if (pax.getPaxType().equalsIgnoreCase("ADT") || pax.getPaxType().equalsIgnoreCase("Ins")
                || pax.getPaxType().equalsIgnoreCase("NRSA") || pax.getPaxType().equalsIgnoreCase("NRPS")
                || pax.getPaxType().equalsIgnoreCase("FQTV")) {
            cmd = "6:" + mPassengers.get(getDriverID()).get(0).getSegmentFlight(0)
                    + "/" + gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0))
                    + origin + "-" + pax.getfName()
                    + "/" + pax.getlName()
                    + "\n" + "#B" + TotalBag + "/" + Weight + "-" + pax.getAirline(0) + TagNum;

        } else if (pax.getPaxType().equalsIgnoreCase("CHD")) {
            cmd = "6:" + mPassengers.get(getDriverID()).get(0).getSegmentFlight(0)
                    + "/" + gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0))
                    + origin + "-" + pax.getfName()
                    + "/" + pax.getlName()
                    + "\n" + "#B" + TotalBag + "C1/" + Weight + "-" + pax.getAirline(0) + TagNum;
        } else if (pax.getPaxType().equalsIgnoreCase("Inf")) {

            cmd = "6:" + mPassengers.get(getDriverID()).get(0).getSegmentFlight(0)
                    + "/" + gl.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0))
                    + origin + "-" + pax.getAccompaniedPaxDetails().getfName()
                    + "/" + pax.getAccompaniedPaxDetails().getlName()
                    + "\n" + "#B" + TotalBag + "I1/" + Weight + "-" + pax.getAirline(0) + TagNum;
        }

        System.out.println(cmd);
        return cmd;
    }

