    public void unEvenExchangeNCFOP(ExtentTest logInfo, String segSequence, String RefundType) throws IOException {
        Passenger pax = mPassengers.get(getDriverID()).get(0);

        gl.sendCmdValidateResponse(saveAndRetrieve, logInfo);

        String retrieve = "ER";
        gl.logCommand(logInfo, "ER");
        gl.sendCmdValidateResponse(retrieve, "PNR MODIFIED", "ETKT/PNR MODIFIED- CHK ITIN", logInfo);
        gl.logCommand(logInfo, "ER");
        gl.sendCmdValidateResponse(retrieve, "ETKT", "MODIFY REC", logInfo);

        gl.logCommand(logInfo, "$-$-ZO80P");
        gl.sendCmdValidateResponse("$-$-ZO80P", "FARE", logInfo);

        gl.logCommand(logInfo, "FF");
        gl.sendCmdValidateResponse("FF", "FARE", logInfo);


        gl.logCommand(logInfo, "ER");
        gl.sendCmdIfRequired(retrieve, "ETKT", logInfo);

        String Response = isharesPageObjects4.SHARES_RESPONSE.getText();
        System.out.println("response" + Response);
        String TotalAmount = Response.substring(Response.indexOf("TTL") + 3, Response.indexOf("TTL") + 10);
        System.out.println("TotalAmount" + TotalAmount);

        System.out.println("tax index " + TotalAmount);

        String TaxName = "XT";

        float Tax = Integer.parseInt(TotalAmount.substring(0, TotalAmount.indexOf(".")));
        float tax = Tax / pax.getfName().length();
        System.out.println("tax: " + tax);

        for (int j = 0; j < pax.getfName().length(); j++) {
            pax = mPassengers.get(getDriverID()).get(j);
            String reissue = "";
            // Doing Reissue  T-$UE23022300006271/FVI/OB1262.00/OXCO49.00/XT142.80/AC$5555555555554444/1230/N1234#N3.2#ET - XT , T1, US, UK, A1, AH
            if (RefundType.equalsIgnoreCase("UsingRefund")) {
//                T-$UE23022300011705/FVI/OB2566.00/OXUS22.20/AY5.60/XT101.72/RF$RD*PENALTY$25#N1.1#ET

                reissue = "T-$UE" + pax.getTicketNumber() + "/FVI/OB" + tax + "0/" + TaxName + "142.80" + "/RF$RD*PENALTY$25|N" + (j + 1) + "." + segSequence + "|ET";

            } else if (RefundType.equalsIgnoreCase("XFNIL")) {
//                T-$UE23021844064310/FDB/OB0.00/OX20.00/XT00.50/AC$36003400300044/1130/N969931#@XFNIL#N1.1#ET

                //reissue = "T-$UE" + pax.getTicketNumber() + "FDB/OB" + tax + "0/" + TaxName + "142.80" + "/AC$36003400300044/1130/N969931|@XFNIL|N" + (j + 1) + "." + segSequence + "|ET";
                reissue = "T-$UE" + pax.getTicketNumber() + "/FDB/OB0.00/OX20.00/XT00.50/AC$36003400300044/1130/N969931#@XFNIL#ET";

            }

            gl.logCommand(logInfo, reissue);
            gl.sendCmdValidateResponse(reissue, "FARE", "SEE ADV PURCHASE", "SIMULT", logInfo);
            String response = isharesPageObjects4.SHARES_RESPONSE.getText();

            if (response.contains("SIMULT")) {
                gl.sendCmdValidateResponse("IR", pax.getPnr(), logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                gl.sendCmdValidateResponse(reissue, "FARE", "SEE ADV PURCHASE", logInfo);
            }

            // Saving the transaction
            gl.logCommand(logInfo, ignoreAndRetrieve);
            gl.sendCmdValidateResponse(ignoreAndRetrieve, pax.getPnr(), logInfo);

            gl.logCommand(logInfo, "X1");
            gl.sendCmdValidateResponse("X1", logInfo);
//
            gl.logCommand(logInfo, "6P#ER");
            gl.sendCmdValidateResponse("6P#ER", logInfo);

            gl.logCommand(logInfo, endAndretrieve);
            gl.sendCmdValidateResponse(endAndretrieve, logInfo);
            response = isharesPageObjects4.SHARES_RESPONSE.getText();

            if (response.contains("SIMULT")) {
                gl.sendCmdValidateResponse("IR", pax.getPnr(), logInfo);
            }

            gl.logCommand(logInfo, ignoreAndRetrieve);
            gl.sendCmdValidateResponse(ignoreAndRetrieve, pax.getPnr(), logInfo);
        }

        //Checking PNR history
        gl.logCommand(logInfo, checkPnrHistory);
        gl.sendCmdValidateResponse(checkPnrHistory, "EXCHANGED", logInfo);

        //Check Ticket Status
        gl.logCommand(logInfo, checkTicketStatus);
        gl.sendCmdValidateResponse(checkTicketStatus, "EXCHANGED", logInfo);

    }

