    public void searchFlightAvailabilityForSecondSegForWaitlistPax(ExtentTest logInfo, String Origin, String Destination) {
        try {

            String COS = mPassengers.get(getDriverID()).get(0).getCOS();
            int totalpax = mPassengers.get(getDriverID()).size();
            String airline = mPassengers.get(getDriverID()).get(0).getAirline(1);
            int initialDepartureDate = mPassengers.get(getDriverID()).get(0).getSegmentDate(1); // Store the initial departure date

            int departureEndDate = initialDepartureDate + 5;

            String[] economyClass = {"Y", "H", "B", "M", "W", "K", "Q", "E", "F"};
            String[] businessClass = {"J", "R", "D", "C"};
            String[] destinationCities = {"MIA", "HAV", "MEX"};

            // Include primary destination first, then fallback destinations
            String[] allDestinations = new String[destinationCities.length + 1];
            allDestinations[0] = Destination;
            System.arraycopy(destinationCities, 0, allDestinations, 1, destinationCities.length);

            if (COS.contains("Y") || COS.contains("B") || COS.contains("H") || COS.contains("M") ||
                    COS.contains("W") || COS.contains("K") || COS.contains("Q") ||
                    COS.contains("E") || COS.contains("F")) {
                Destinations:
// Iterate through destinations
                for (String currentDestination : allDestinations) {

                    int departuredate = initialDepartureDate; // Reset departure date for each class and destination

                    DepartureDate:
                    // Iterate through date range
                    while (departuredate <= departureEndDate) {
                        isharesPage2.displaySeatsAvailabilityForFlights(logInfo, Origin, currentDestination, 1, departuredate);

                        Flight:
                        // Loop for flights
                        for (int j = 1; j <= flightIndex.get(getDriverID()).size(); j++) {
                            ClassOfService:
                            // Iterate through all classes in economyClass
                            for (String tcos : economyClass) {
                                COS = tcos;

                                String command = null;
                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1);  //N2Y1

                                gl.logCommand(logInfo, command);
                                gl.sendCmdValidateResponse(command, logInfo);

                                String response = isharesPageObjects4.SHARES_RESPONSE.getText();
                                gl.checkForErrors(command, response, logInfo);

                                if (response.contains("ETKT ELIGIBLE") && (response.contains("PD") || response.contains("PC"))) {

                                    // Assign flight details to passengers
                                    for (Passenger pax : mPassengers.get(getDriverID())) {
                                        pax.setSegmentFlight(1, response.substring(6, 10).trim());
                                        pax.setSegmentDate(1, departuredate);
                                        pax.setAirline(1, airline);
                                        pax.setCOS(COS);

                                        int len = response.split("\n")[0].split(" ").length;

                                        if (airline.equalsIgnoreCase("CM")) {
                                            pax.setSegmentDepartureTime(1, response.split("\n")[0].split(" ")[len - 3]);
                                            if (pax.getSegmentDepartureTime(1).isEmpty()) {
                                                pax.setSegmentDepartureTime(1, response.split("\n")[0].split(" ")[len - 2]);
                                            }
                                            pax.setSegmentArrivalTime(1, response.split("\n")[0].split(" ")[len - 1]);
                                        } else {
                                            pax.setSegmentDepartureTime(1, response.split("\n")[0].split(" ")[len - 3]);
                                            pax.setSegmentArrivalTime(1, response.split("\n")[0].split(" ")[len - 1].split("/")[0]);
                                        }
                                    }

                                    break Destinations; // Exit as soon as a flight is booked
                                } else {
                                    gl.ignoreTRNS(logInfo);
                                    isharesPage2.displaySeatsAvailabilityForFlights(logInfo, Origin, currentDestination, 1, departuredate);
                                }
                            }

                        }

                        // Move to the next day
                        departuredate++;

                        if (departuredate > departureEndDate) {
                            break; // Exit date loop if all days are checked
                        }
                    }
                }
            } else if (COS.contains("C") || COS.contains("J") || COS.contains("D") || COS.contains("R")) {
                Destinations:
                // Iterate through destinations
                for (String currentDestination : allDestinations) {

                    int departuredate = initialDepartureDate; // Reset departure date for each class and destination

                    DepartureDate:
                    // Iterate through date range
                    while (departuredate <= departureEndDate) {

                        isharesPage2.displaySeatsAvailabilityForFlights(logInfo, Origin, currentDestination, 0, departuredate);
                        Flight:
                        // Loop for flights
                        for (int j = 1; j <= flightIndex.get(getDriverID()).size(); j++) {
                            ClassOfService:
                            // Iterate through all classes in businessClass
                            for (String tcos : businessClass) {
                                COS = tcos;

                                String command = null;

                                command = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j - 1);  //N2Y1

                                gl.logCommand(logInfo, command);
                                gl.sendCmdValidateResponse(command, logInfo);

                                String response = isharesPageObjects4.SHARES_RESPONSE.getText();

                                if (response.contains("ETKT ELIGIBLE") && response.contains("PD")) {

                                    // Assign flight details to passengers
                                    for (Passenger pax : mPassengers.get(getDriverID())) {
                                        pax.setSegmentFlight(1, response.substring(6, 10).trim());
                                        pax.setSegmentDate(1, departuredate);
                                        pax.setAirline(1, airline);
                                        pax.setCOS(COS);

                                        int len = response.split("\n")[0].split(" ").length;

                                        if (airline.equalsIgnoreCase("CM")) {
                                            pax.setSegmentDepartureTime(1, response.split("\n")[0].split(" ")[len - 3]);
                                            if (pax.getSegmentDepartureTime(1).isEmpty()) {
                                                pax.setSegmentDepartureTime(1, response.split("\n")[0].split(" ")[len - 2]);
                                            }
                                            pax.setSegmentArrivalTime(1, response.split("\n")[0].split(" ")[len - 1]);
                                        } else {
                                            pax.setSegmentDepartureTime(1, response.split("\n")[0].split(" ")[len - 3]);
                                            pax.setSegmentArrivalTime(1, response.split("\n")[0].split(" ")[len - 1].split("/")[0]);
                                        }
                                    }

                                    break Destinations; // Exit as soon as a flight is booked
                                } else {
                                    gl.ignoreTRNS(logInfo);
                                    isharesPage2.displaySeatsAvailabilityForFlights(logInfo, Origin, currentDestination, 1, departuredate);
                                }
                            }
                        }
                        // Move to the next day
                        departuredate++;

                        if (departuredate > departureEndDate) {
                            break; // Exit date loop if all days are checked
                        }
                    }
                }
            } else
                logInfo.info(MarkupHelper.createLabel("No seats available for any destination within the specified range.", ExtentColor.RED));

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

