    public void iBlockAllTheSeatsInEconomyClass(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            String[] EconomyClass = {"F", "E", "B", "A", "C", "D"};
            for (int j = 5; j <= 34; j++) {      // loop to block all seats
                //           	6:CP322/06MARPTY.Y#5F
                String displayBrdCmd = "6:CP" + pax.getSegmentFlight(0) + "/" + gl.sharesFormatDateFromGUI(pax.getSegmentDate(0)) +
                        pax.getSegmentOriginCity(0) + ".Y" + "/" + pax.getSegmentDestinationCity(0) + "|" + j + "ABCDEF";//EconomyClass[i];
                gl.logCommand(logInfo, displayBrdCmd);
                gl.sendCmdValidateResponse(displayBrdCmd, logInfo);

                String response = isharesPageObjects4.SHARES_RESPONSE.getText();
                if (response.contains("PREVIOUSLY REMOVED")) {
                    for (int i = 0; i < EconomyClass.length; i++) {
                        for (int x = j; x <= j; x++) {      // loop to block all seats
                            //           	6:CP322/06MARPTY.Y#5F
                            displayBrdCmd = "6:CP" + pax.getSegmentFlight(0) + "/" + gl.sharesFormatDateFromGUI(pax.getSegmentDate(0)) +
                                    pax.getSegmentOriginCity(0) + ".Y" + "/" + pax.getSegmentDestinationCity(0) + "|" + x + EconomyClass[i];
                            gl.logCommand(logInfo, displayBrdCmd);
                            gl.sendCmdValidateResponse(displayBrdCmd, logInfo);
                        }
                    }
                }
            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

