    public List<String> getFlightNumbers(String responseText, int segmentIndex) {
        // Initialize a list to store the flight numbers
        List<String> numbers = new ArrayList<>();

        Passenger pax = mPassengers.get(getDriverID()).get(0);
        // Split the response into lines
        String[] lines = responseText.split("\n");


        String threeDigitRegex = "(\\*?\\d)" + pax.getAirline(segmentIndex) + "\\s?(\\d{3})\\*?";   // Regex to capture 3-digit flight numbers,followed by optional star ex: 4CM 393 or 4CM 393*
        String fourDigitRegex = "(\\*?\\d)" + pax.getAirline(segmentIndex) + "\\s?(\\d{4})\\*?";  // Regex to capture 4-digit flight numbers,followed by optional star ex: 2CM1931 or 2CM1931*, if no 3-digit numbers are found
        String fiveDigitRegex = "(\\*?\\d)" + pax.getAirline(segmentIndex) + "\\s?(\\d{5})\\*?";


        Pattern threeDigitPattern = Pattern.compile(threeDigitRegex); // Compile the regex for 3-digit numbers
        Pattern fourDigitPattern = Pattern.compile(fourDigitRegex);   // Compile the regex for 4-digit numbers
        Pattern fiveDigitPattern = Pattern.compile(fiveDigitRegex);  // Compile the regex for 5-digit numbers

        boolean foundThreeDigit = false;
        boolean foundFourDigit = false;

        // First pass: try to find 3-digit numbers
        for (int i = 0; i < lines.length; i++) {
            Matcher matcher = threeDigitPattern.matcher(lines[i]);
            while (matcher.find()) {
                String numberLeft = matcher.group(2).trim();
                numbers.add(numberLeft);
                foundThreeDigit = true;
                System.out.println("3-digit Number left of CM: " + numberLeft + " on line " + (i + 1));
            }
        }

        // If no 3-digit numbers were found, try finding 4-digit numbers
        if (!foundThreeDigit) {
            for (int i = 0; i < lines.length; i++) {
                Matcher matcher = fourDigitPattern.matcher(lines[i]);
                while (matcher.find()) {
                    String numberLeft = matcher.group(2).trim();
                    foundFourDigit = true;
                    numbers.add(numberLeft);
                    System.out.println("4-digit Number left of CM: " + numberLeft + " on line " + (i + 1));
                }
            }
        }

        // If no 4-digit numbers were found, try finding 5-digit numbers
        if (!foundFourDigit) {
            for (int i = 0; i < lines.length; i++) {
                Matcher matcher = fiveDigitPattern.matcher(lines[i]);
                while (matcher.find()) {
                    String numberLeft = matcher.group(2).trim();
                    numbers.add(numberLeft);
                    System.out.println("5-digit Number left of CM: " + numberLeft + " on line " + (i + 1));
                }
            }
        }

        return numbers;
    }


    public void bookASpecificFlightAndForASpecificDate(ExtentTest logInfo, String Origin, String Destination) {
        Passenger pax = mPassengers.get(getDriverID()).get(0);
        String COS = mPassengers.get(getDriverID()).get(0).getCOS();
        int totalpax = mPassengers.get(getDriverID()).size();
        String airline = mPassengers.get(getDriverID()).get(0).getAirline(0);
        int initialDepartureDate = mPassengers.get(getDriverID()).get(0).getSegmentDate(0); // Store the initial departure date

        int departureEndDate = initialDepartureDate + 5;

        String[] economyClass = {"Y", "H", "B", "M"};
        String[] destinationCities = {"MIA", "HAV", "MEX"};

        // Include primary destination first, then fallback destinations
        String[] allDestinations = new String[destinationCities.length + 1];
        allDestinations[0] = Destination;
        System.arraycopy(destinationCities, 0, allDestinations, 1, destinationCities.length);


        if (COS.contains("Y") || COS.contains("B") || COS.contains("H") || COS.contains("M") ||
                COS.contains("W") || COS.contains("K") || COS.contains("Q") ||
                COS.contains("E") || COS.contains("F")) {

            Destinations:
            for (String currentDestination : allDestinations) // Iterate through destinations
            {
                int departuredate = initialDepartureDate; // Reset departure date for each class and destination
                DepartureDate:
                while (departuredate <= departureEndDate) // Iterate through date range
                {
                    isharesPage2.displaySeatsAvailabilityForFlights(logInfo, Origin, currentDestination, 0, departuredate);
                    String response = isharesPageObjects4.SHARES_RESPONSE.getText();

                    List<String> flightNos = getFlightNumbers(response, 0);
                    List<String> flightPosition = isharesPage2.getFlightPositions(response, 0);
                    Flight:
                    for (int j = 0; j < flightNos.size(); j++)  // Loop for flights
                    {
                        //        A 360/13JUN PTYLAX
                        String command = "A " + flightNos.get(j) + "/" + gl.sharesFormatDateFromGUI(departuredate) + " " + pax.getSegmentOriginCity(0) + pax.getSegmentDestinationCity(0);

                        gl.logCommand(logInfo, command);
                        gl.sendCmdValidateResponse(command, logInfo);

                        ClassOfService:
                        for (String tcos : economyClass)  // Iterate through all classes in businessClass
                        {
                            COS = tcos;
                            command = "N" + totalpax + COS + flightPosition.get(j);  //N2Y1

                            gl.logCommand(logInfo, command);
                            gl.sendCmdValidateResponse(command, logInfo);

                            response = isharesPageObjects4.SHARES_RESPONSE.getText();
                            gl.checkForErrors(command, response, logInfo);

                            if (response.contains("ETKT ELIGIBLE") || response.contains("ADV PAX FLT ARRIVES TERMINAL") ||
                                    response.contains("SS" + totalpax) || response.contains("NN" + totalpax)) {

                                // Assign flight details to passengers
                                for (Passenger pax1 : mPassengers.get(getDriverID())) {
                                    pax1.setSegmentFlight(0, response.substring(6, 10).trim());
                                    pax1.setSegmentDate(0, departuredate);
                                    pax1.setAirline(0, airline);
                                    pax1.setCOS(COS);
                                    pax1.setSegmentDestinationCity(0, currentDestination);

                                    int len = response.split("\n")[0].split(" ").length;

                                    if (airline.equalsIgnoreCase("CM")) {
                                        pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 3]);
                                        if (pax.getSegmentDepartureTime(0).isEmpty()) {
                                            pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 2]);
                                        }
                                        pax.setSegmentArrivalTime(0, response.split("\n")[0].split(" ")[len - 1]);
                                    } else {
                                        pax.setSegmentDepartureTime(0, response.split("\n")[0].split(" ")[len - 3]);
                                        pax.setSegmentArrivalTime(0, response.split("\n")[0].split(" ")[len - 1].split("/")[0]);
                                    }
                                }

                                break Destinations; // Exit as soon as a flight is booked
                            } else
                                isharesPage2.displaySeatsAvailabilityForFlights(logInfo, Origin, currentDestination, 0, departuredate);
                        }
                    }
                }
            }
        }
    }

