    public String getTaxesForPassenger(ExtentTest logInfo, String Response) {
        String Taxes = "";

        try {
            String alphaNumericREGEX = "^\\d+\\.\\d+[A-Za-z0-9]+$";
            Pattern PATTERN = Pattern.compile(alphaNumericREGEX);

            String numericREGEX = "^-?\\d+(\\.\\d+)?$";
            Pattern PATTERN1 = Pattern.compile(numericREGEX);

            String[] responseRows = Response.split("\n");

            for (int i = 1; i < responseRows.length; i++) {
                if (responseRows[i - 1].contains("FARE")) {
                    for (int j = 0; j < responseRows[i].split(" ").length; j++) {
                        if (PATTERN.matcher(responseRows[i].split(" ")[j]).matches() && !PATTERN1.matcher(responseRows[i].split(" ")[j]).matches())
                            Taxes = Taxes + "#" + responseRows[i].split(" ")[j];
                    }
                    break;
                }
            }
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

        return Taxes;
    }

