    public void unEvenExchangeNew(ExtentTest logInfo, String RefundType) throws IOException {

        try {

            ArrayList<Passenger> passengers = mPassengers.get(getDriverID());

//          After making the required changes to PNR which are done in previous steps, we need to Save and retrieve the PNR
//          Hence we are doing 6P#ER
            gl.logCommand(logInfo, saveAndRetrieve);
            gl.sendCmdValidateResponse(saveAndRetrieve,"ETKT/PNR MODIFIED- CHK ITIN", logInfo);

            gl.logCommand(logInfo, "ER");
            gl.sendCmdValidateResponse("ER", "PNR MODIFIED", "ETKT/PNR MODIFIED- CHK ITIN", logInfo);
            //Since we made changes to PNR , it will show PNR Modified , if no changes are made or the made changes have been saved then it wil nt show PNR MODIFIED

            gl.sendCmdIfRequired("ER", passengers.get(0).getPnr(), logInfo);

            gl.logCommand(logInfo, "T-ETCKPRICE");
            gl.sendCmdValidateResponse("T-ETCKPRICE","NEW TOTAL FARE FOR ITINERARY", logInfo);

//          Based on the scenario it will show Refund or Add Collect
            String Response = isharesPageObjects4.SHARES_RESPONSE.getText();

            String TotalAmount = null;

            if (Response.contains("REFUND")) {
                TotalAmount = Response.substring(95, 103).trim().replace("$", "");
                System.out.println("tax index " + TotalAmount);
                logInfo.info(MarkupHelper.createLabel("REFUND: $" + TotalAmount, ExtentColor.BLACK));

            } else if (Response.contains("ADD COLLECT")) {
                TotalAmount = Response.substring(Response.indexOf("COLLECT") + 10, Response.indexOf("COLLECT") + 18).trim().replace("$", "");
                System.out.println("tax index " + TotalAmount);
                logInfo.info(MarkupHelper.createLabel("ADD COLLECT: $" + TotalAmount, ExtentColor.BLACK));
            }

            float exchangeAmt, dividedExchangeAmt;

            if (TotalAmount != null) {
                exchangeAmt = Integer.parseInt(TotalAmount.substring(0, TotalAmount.indexOf(".")));
                dividedExchangeAmt = exchangeAmt / passengers.size(); //Total exchange Amount is being divided here equally amongst all the passengers
                System.out.println("New Exchange Amount after Division amongst Pax: " + dividedExchangeAmt);
            }

            if (passengers.get(0).getIsNRSA() || passengers.get(0).getIsNRPS()) {
                gl.logCommand(logInfo, "$-$-ZO100P"); // For Discounting in case of NRSA And NRPS Pax
                gl.sendCmdValidateResponse("$-$-ZO100P","PERCENTAGE DISCOUNT OVERRIDE APPLIED TO BASE FARE", logInfo);
            }

            int paxSequenceAfterDecimal;
            int sameSurnamePaxSeq = 1;
            int normalPaxSeq = 1;

            for (int j = 0; j < passengers.size(); j++)  //Looping through each Passenger
            {

                if (passengers.get(j).getIsSameSurname())
                    paxSequenceAfterDecimal = sameSurnamePaxSeq++;
                else
                    paxSequenceAfterDecimal = normalPaxSeq;

                String command = "*ET" + (j + 1) + "." + "1";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, passengers.get(j).getfName() + "/" + passengers.get(j).getlName(), logInfo);

                Response = isharesPageObjects4.SHARES_RESPONSE.getText();

                String reissue = "", baseAmount, tax1 = "", tax2 = "", tax3 = "", ticketNumber;

                ticketNumber = getTicketNumberForPassenger(logInfo, Response);
                baseAmount = getBaseAmtForPassenger(logInfo, Response);

                if (getTaxesForPassenger(logInfo, Response).substring(1).split("#").length >= 1) {
                    tax1 = getTaxesForPassenger(logInfo, Response).substring(1).split("#")[0];
                    tax1 = tax1.substring(tax1.length() - 2) + tax1.substring(0, tax1.length() - 2);
                    tax1 = tax1.substring(tax1.indexOf(".") + 1).length() > 2 ? tax1.substring(0, tax1.indexOf(".") + 3) : (tax1.substring(tax1.indexOf(".") + 1).length() < 2 ? tax1 + "0" : tax1);
                    tax1 = tax1 + "/";
                }
                if (getTaxesForPassenger(logInfo, Response).substring(1).split("#").length >= 2) {
                    tax2 = getTaxesForPassenger(logInfo, Response).substring(1).split("#")[1];
                    tax2 = tax2.substring(tax2.length() - 2) + tax2.substring(0, tax2.length() - 2) + "/";
                    tax2 = tax2.substring(tax2.indexOf(".") + 1).length() > 2 ? tax2.substring(0, tax2.indexOf(".") + 3) : (tax2.substring(tax2.indexOf(".") + 1).length() < 2 ? tax2 + "0" : tax2);
                    tax2 = tax2 + "/";
                }
                if (getTaxesForPassenger(logInfo, Response).substring(1).split("#").length >= 3) {
                    tax3 = getTaxesForPassenger(logInfo, Response).substring(1).split("#")[2];
                    tax3 = tax3.substring(tax3.length() - 2) + tax3.substring(0, tax3.length() - 2) + "/";
                    tax3 = tax3.substring(tax3.indexOf(".") + 1).length() > 2 ? tax3.substring(0, tax3.indexOf(".") + 3) : (tax3.substring(tax3.indexOf(".") + 1).length() < 2 ? tax3 + "0" : tax3);
                    tax3 = tax3 + "/";
                }


                if (RefundType.equalsIgnoreCase("UsingCard") || RefundType.equalsIgnoreCase("Reissue_WithSegment"))  //Add Collect
                {
                    //  Add Collect Command :  T-$UE23022300006271/FVI/OB1262.00/OXCO49.00/XT142.80/AC$5555555555554444/1230/N1234#N3.2#ET - XT , T1, US, UK, A1, AH
                    reissue = "T-$UE" + ticketNumber + "/FVI/OB" + baseAmount + "/OX" + tax1 + tax2 + tax3 + "AC$5555555555554444/1230/N1234|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";

                } else if (RefundType.equalsIgnoreCase("UsingRefund")) //Refund
                {
                    // Refund Command: T-$UE23022300011705/FVI/OB2566.00/OXUS22.20/AY5.60/XT101.72/RF$RD*PENALTY$25#N1.1#ET
                    reissue = "T-$UE" + ticketNumber + "/FVI/OB" + baseAmount + "/OX" + tax1 + tax2 + tax3 + "RF$RD*PENALTY$25|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";
                } else if (RefundType.equalsIgnoreCase("WithoutADDR")) //Refund
                {
                    reissue = "T-$UE" + ticketNumber + "/FVI/OB" + baseAmount + "/OX" + tax3 + "RF$RD|@XFPTY3|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";
                }
                else if (RefundType.equalsIgnoreCase("WithoutADDRUsingCash")) //Refund
                {
                  //   T-$UE23021771540784/FCASH/OB1414.00/OXAH1.25/AY5.60/XT38.60/RF$RD#XFPTY3#ET
                    reissue = "T-$UE" + ticketNumber + "/FCASH/OB" + baseAmount + "/OX" + tax1 + tax2 + tax3 + "RF$RD|@XFPTY3|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";
                }
                else if (RefundType.equalsIgnoreCase("AddCollectUsingCash"))  //Add Collect using Cash
                {
                    //  T-$UE23021771278870/FCASH/OB1414.00/OXAH1.25/XT44.20/AC$CASH*$5.83#N2.1#ET
                    reissue = "T-$UE" + ticketNumber + "/FVI/OB" + baseAmount + "/OX" + tax1 + tax3 + "AC$CASH*$5.83|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";
                }
                else if (RefundType.equalsIgnoreCase("RefundUsingCash_RF_CASH"))  //Refund using Cash with RF as CASH
                {
                    //  T-$UE23021771278870/FCASH/OB1414.00/OXAH1.25/XT44.20/RF$CASH*$5.83#N2.1#ET

                    reissue = "T-$UE" + ticketNumber + "/FCASH/OB" + baseAmount + "/OX" + tax1 + tax2+ tax3 + "RF$CASH*$5.83|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";
                }
                else if (RefundType.equalsIgnoreCase("RefundUsingCash"))  //Refund using Cash
                {
                    //   T-$UE23021828129893/FCASH/OB2145.00/OXAH2.50/XT81.65/RF$4444333322221111/1224/N1234*$1415.70#ET
                    reissue = "T-$UE" + ticketNumber + "/FCASH/OB" + baseAmount + "/OX" + tax1 + tax3 + "RF$4444333322221111/1224/N1234|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";
                }
                else if (RefundType.equalsIgnoreCase("RefundUsingCash_RF_CASH"))  //Refund using Cash with RF as CASH
                {
                    //  T-$UE23021771278870/FCASH/OB1414.00/OXAH1.25/XT44.20/RF$CASH*$5.83#N2.1#ET
                    reissue = "T-$UE" + ticketNumber + "/FCASH/OB" + baseAmount + "/OX" + tax1 + tax2+ tax3 + "RF$CASH*$5.83|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";
                }
                else if (RefundType.equalsIgnoreCase("Reissue_WithoutSegment")) {

                    //    T-$UE23022300006422/FVI/OB0809.00/OXXD63.75/XT33.65/AC$4911830000000/1224/N1234#ET
                    reissue = "T-$UE" + ticketNumber + "/FVI/OB" + baseAmount + "/OX" + tax1 + tax2 + tax3 + "AC$4911830000000/1224/N1234|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";
                } else if (RefundType.equalsIgnoreCase("RefundUsingCheck")) {

                    //    T-$UE23022300000612/FCK/OB1959.00/OXS11.06/UK42.63/XT255.35/RF$CASH#ET
                    reissue = "T-$UE" + ticketNumber + "/FCK/OB" + baseAmount + "/OX" + tax1 + tax2 + tax3 + "RF$CASH|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";
                } else if (RefundType.equalsIgnoreCase("AddCollectUsingCheck")) {

                    //    T-$UE23022300020374/FCK899/OB369.00/OXXO9.00/XT0.00/AC$CASH#@XFNIL#ET
                    reissue = "T-$UE" + ticketNumber + "/FCK899/OB" + baseAmount + "/OX" + tax1 + tax3 + "AC$CASH|@XFNIL|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";
                } else if (RefundType.equalsIgnoreCase("RefundWithPenaltyInVisa")) {

                    //   T-$UE23022300031585/FVI/OB3421.00/OXAH2.50/XT35.00/RF$RD*PENALTY$25#N1.1#ET
                    reissue = "T-$UE" + ticketNumber + "/FVI/OB" + baseAmount + "/OX" + tax1 + tax3 + "RF$RD*PENALTY$25|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";
                } else if (RefundType.equalsIgnoreCase("RefundCashWithRD")) {

                    //   T-$UE23022300006400/FCASH/OB2031.00/OXJS15.00/AH1.25/XT32.30/RF$RD#@XFPTY3#ET
                    reissue = "T-$UE" + ticketNumber + "/FCASH/OB" + baseAmount + "/OX" + tax1 + tax2 + tax3 + "RF$RD#@XFPTY3|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";
                } else if (RefundType.equalsIgnoreCase("RefundWithPenaltyInCheck")) {

                    //   T-$UE23022300031585/FCK/OB3421.00/OXAH2.50/XT35.00/RF$RD*PENALTY$25#N1.1#ET
                    reissue = "T-$UE" + ticketNumber + "/FCK/OB" + baseAmount + "/OX" + tax1 + tax3 + "RF$RD*PENALTY$25|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";
                } else if (RefundType.equalsIgnoreCase("RefundUsingCashWithSegment")) {

                    //   T-$UE23022300020794/FCASH/OB2145.00/OXAH2.50/XT81.65/RF$4444333322221111/1224/N1234*$1415.70#ET
                    reissue = "T-$UE" + ticketNumber + "/FCASH/OB" + baseAmount + "/OX" + tax1 + tax3 + "RF$4444333322221111/1224/N1234" + "*$" + TotalAmount + "|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";
                } else if (RefundType.equalsIgnoreCase("RefundUsingFCC")) {

                    //   T-$UE23022300020794/FCC/OB2145.00/OXAH2.50/XT81.65/RF$4444333322221111/1224/N1234*$1415.70#ET
                    reissue = "T-$UE" + ticketNumber + "/FCC/OB" + baseAmount + "/OX" + tax1 + tax2 + tax3 + "RF$4444333322221111/1224/N1234" + "*$" + TotalAmount + "|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";
                } else if (RefundType.equalsIgnoreCase("AddCollectUsingFCC")) {

                    //   T-$UE23022300000122/FCC/OB0.00/OX20.00/XT00.50/AC$36003400300036/1130/N969931*$525 ADDED AS PENALITY CHK ABCDEFGHIJKLMNOPQRSTUNVWXYZR ABCDEFHOUTCDHNGTVDHJKNFRDGHJKLKYJGHVKJBMNMJKNKNGF#@XFNIL#ET
                    reissue = "T-$UE" + ticketNumber + "/FCC/OB" + baseAmount + "/OX" + tax1 + tax2 + tax3 + "AC$36003400300036/1130/N969931" + "*$" + TotalAmount + "|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";
                } else if (RefundType.equalsIgnoreCase("AddCollectWithoutTicketNumber")) {

                    //  T-$UE/FCASH/OB1000.00/AB11.06/UK42.63/XT182.95/AC$#@XFNIL#ET
                    reissue = "T-$UE" + "/FCASH/OB" + baseAmount + "/OX" + tax1 + tax2 + tax3 + "AC$#@XFNIL|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";

                } else if (RefundType.equalsIgnoreCase("RefundUsingCashWithRDandExtraCharacter")) {

                    //  T-$UE/FCASH/OB1081.00/OXYC5.00/XT1135.00/RF$RD1*$525 ADDED AS PENALITY CHK ABCDEFGHIJKLMNOPQRSTUNABCDEFGHIJLAJDALJDLAKALNJGJALOKWXYZR ABCDEFHOUTCDHNGTVDHJKNFRDGHJKLKYJGHVKJBMNMJKNKNGFR#@XFNIL#ET
                    reissue = "T-$UE" + ticketNumber + "/FCASH/OB" + baseAmount + "/OX" + tax1 + tax2 + tax3 + "RF$RD1" + "*$" + TotalAmount + "ADDED AS PENALITY CHK ABCDEFGHIJKLMNOPQRSTUNABCDEFGHIJLAJDALJDLAKALNJGJALOKWXYZR#@XFNIL|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";
                }
                else if (RefundType.equalsIgnoreCase("AddCollectUsingFCCWithRDandExtraCharacter")) {

                    //  T-$UE23022300000122/FCC/OB0.00/OX20.00/XT00.50/AC$36003400300036/1130/N969931*$525 ADDED AS PENALITY CHK ABCDEFGHIJKLMNOPQRSTUNVWXYZR ABCDEFHOUTCDHNGTVDHJKNFRDGHJKLKYJGHVKJBMNMJKNKNGF#@XFNIL#ET
                    reissue = "T-$UE" + ticketNumber + "/FCC/OB" + baseAmount + "/OX" + tax1 + tax2 + tax3 + "AC$36003400300036/1130/N969931" + "*$" + TotalAmount + "ADDED AS PENALITY CHK ABCDEFGHIJKLMNOPQRSTUNVWXYZR ABCDEFHOUTCDHNGTVDHJKNFRDGHJKLKYJGHVKJBMNMJKNKNGF#@XFNIL|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";
                }
                else if (RefundType.equalsIgnoreCase("Addcollect_FDB")) {
                    // T-$UE23021844064310/FDB/OB0.00/OX20.00/XT00.50/AC$36003400300044/1130/N969931#@XFNIL#N1.1#ET
                    reissue = "T-$UE" + ticketNumber + "/FDB/OB" + baseAmount + "/OX" + tax1 + tax2 + tax3 + "AC$36003400300044/1130/N969931#@XFNIL|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal + "|ET";
                }
                else if (RefundType.equalsIgnoreCase("RefundUsingCashWithAC")) {
                    // T-$UE/FCASH/OB1081.00/OXYC5.00/XT1135.00/AC$CK#ET
                    reissue = "T-$UE" + ticketNumber + "/FCASH/OB" + baseAmount + "/OX" + tax1 + tax3 + "AC$CK|ET";
                }


                gl.logCommand(logInfo, reissue);
                gl.sendCmdValidateResponse(reissue, "TKT NBR ISSUED", "SEE ADV PURCHASE", "SIMULT", logInfo);

                Response = isharesPageObjects4.SHARES_RESPONSE.getText();

                if (Response.contains("SIMULT")) {

                    gl.logCommand(logInfo, ignoreAndRetrieve);
                    gl.sendCmdValidateResponse(ignoreAndRetrieve, passengers.get(0).getPnr(), logInfo);

                    gl.logCommand(logInfo, reissue);
                    gl.sendCmdValidateResponse(reissue, "TKT NBR ISSUED", "SEE ADV PURCHASE", logInfo);
                }

                // Saving the transaction
                gl.logCommand(logInfo, ignoreAndRetrieve);
                gl.sendCmdValidateResponse(ignoreAndRetrieve, passengers.get(0).getPnr(), logInfo);

                gl.logCommand(logInfo, "FR/ALL");
                gl.sendCmdValidateResponse("FR/ALL","ALL FILED QUOTES WILL BE SENT TO HISTORY AFTER ET", logInfo);

                gl.logCommand(logInfo, "6P#ER");
                gl.sendCmdValidateResponse("6P#ER",passengers.get(0).getPnr(), logInfo);

                Response = isharesPageObjects4.SHARES_RESPONSE.getText();

                if (Response.contains("SIMULT")) {

                    gl.logCommand(logInfo, ignoreAndRetrieve);
                    gl.sendCmdValidateResponse(ignoreAndRetrieve, passengers.get(0).getPnr(), logInfo);
                }

            }

            //Checking PNR history  EXCHANGED : To confirm Ticket is exchanged/reissued or not  REFUND: For Refund Scenario   ADD COLLECT: For Extra Payment Scenario
            gl.logCommand(logInfo, checkPnrHistory);
            gl.sendCmdValidateResponse(checkPnrHistory, "EXCHANGED","REFUND", "ADD COLLECT", logInfo);

            //Check Ticket Status
            gl.logCommand(logInfo, checkTicketStatus);
            gl.sendCmdValidateResponse(checkTicketStatus, "EXCHANGED", logInfo);


        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }
    }


