    public void performASA(ExtentTest logInfo, String segmentNumber, String AssignType) {
        try {

            int segmentNo = Integer.parseInt(segmentNumber);

            if (AssignType.equalsIgnoreCase("true")) {
                gl.logCommand(logInfo, "6:A");
                gl.sendCmdValidateResponse("6:A", "SEATS ASSIGNED", logInfo);

                if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("UNASSIGNED")) {
                    logInfo.fail(MarkupHelper.createLabel("SEATS UNASSIGNED - COULD NOT PERFORM ADVANCED SEAT ASSIGNMENT", ExtentColor.PURPLE));
                    Assert.fail("SEATS UNASSIGNED");
                } else
                    logInfo.pass(MarkupHelper.createLabel("I perform ASA to all the passengers and validated seat assigned", ExtentColor.GREEN));

            } else if (AssignType.equalsIgnoreCase("SpecificSegment")) {

                gl.logCommand(logInfo, "6:A" + segmentNo);
                gl.sendCmdValidateResponse("6:A" + segmentNo, "SEATS ASSIGNED", logInfo);

                if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("UNASSIGNED")) {
                    logInfo.fail(MarkupHelper.createLabel("SEATS UNASSIGNED - COULD NOT PERFORM ADVANCED SEAT ASSIGNMENT", ExtentColor.PURPLE));
                    Assert.fail("SEATS UNASSIGNED");
                } else
                    logInfo.pass(MarkupHelper.createLabel("I perform Specific Segment ASA to all the passengers and validated seat assigned", ExtentColor.GREEN));

            } else if (AssignType.equalsIgnoreCase("WindowSeat")) {
                gl.logCommand(logInfo, "6:A|W");
                gl.sendCmdValidateResponse("6:A|W", "SEATS ASSIGNED", logInfo);

                if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("UNASSIGNED")) {
                    logInfo.fail(MarkupHelper.createLabel("SEATS UNASSIGNED - COULD NOT PERFORM ADVANCED SEAT ASSIGNMENT", ExtentColor.PURPLE));
                    Assert.fail("SEATS UNASSIGNED");
                } else
                    logInfo.pass(MarkupHelper.createLabel("I perform Window Seat ASA to all the passengers and validated seat assigned", ExtentColor.GREEN));

            } else if (AssignType.equalsIgnoreCase("ExitSeat")) {

                gl.logCommand(logInfo, "6:A|E");
                gl.sendCmdValidateResponse("6:A|E", "SEATS ASSIGNED", "ADVISE CUSTOMER EXIT SEATS ASSIGNED", logInfo);

                if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("UNASSIGNED")) {
                    logInfo.fail(MarkupHelper.createLabel("SEATS UNASSIGNED - COULD NOT PERFORM ADVANCED SEAT ASSIGNMENT", ExtentColor.PURPLE));
                    Assert.fail("SEATS UNASSIGNED");
                } else
                    logInfo.pass(MarkupHelper.createLabel("I perform Exit Seat ASA to all the passengers and validated seat assigned", ExtentColor.GREEN));

            } else if (AssignType.equalsIgnoreCase("InvalidSegment")) {

                gl.logCommand(logInfo, "6:A" + segmentNo);
                gl.sendCmdValidateResponse("6:A" + segmentNo, "INVLD SEG NBR ", logInfo);
                logInfo.pass("I perform Invalid Segment ASA to all the passengers and validated seat assigned");

            } else if (AssignType.equalsIgnoreCase("InvalidPaxCount")) {

                gl.logCommand(logInfo, "6:A|N" + segmentNo);
                gl.sendCmdValidateResponse("6:A|N" + segmentNo, "INVALID DELIMITER", logInfo);
                logInfo.pass("I perform Invalid Pax ASA to all the passengers and validated seat assigned");

            } else if (AssignType.equalsIgnoreCase("AssignAndDivide")) {

                gl.logCommand(logInfo, "D" + segmentNo);
                gl.sendCmdValidateResponse("D" + segmentNo, mPassengers.get(getDriverID()).get(0).getfName(), "FARE QUOTE-AUTO PRICED ", logInfo);
                logInfo.pass("I divide the pnr");

            } else if (AssignType.equalsIgnoreCase("VSeat")) {
                gl.logCommand(logInfo, "6:A|V");
                gl.sendCmdValidateResponse("6:A|V", "SEATS ASSIGNED", logInfo);

                if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("UNASSIGNED")) {
                    logInfo.fail(MarkupHelper.createLabel("SEATS UNASSIGNED - COULD NOT PERFORM ADVANCED SEAT ASSIGNMENT", ExtentColor.PURPLE));
                    Assert.fail("SEATS UNASSIGNED");
                } else
                    logInfo.pass(MarkupHelper.createLabel("I perform V Seat ASA to all the passengers and validated seat assigned", ExtentColor.GREEN));

            } else if (AssignType.equalsIgnoreCase("WaitList")) {

                String Seatcmd = "";
                String flight = mPassengers.get(getDriverID()).get(0).getSegmentFlight(0);
                String date = isharesPage1.sharesFormatDateFromGUI(mPassengers.get(getDriverID()).get(0).getSegmentDate(0));
                String origin = mPassengers.get(getDriverID()).get(0).getSegmentOriginCity(0);

                for (int j = 0; j < mPassengers.get(getDriverID()).size(); j++) {
                    gl.ignoreTRNS(logInfo);

                    Seatcmd = "6:ZT" + flight + "/" + date + origin + "-" +
                            mPassengers.get(getDriverID()).get(j).getfName() + "/" + mPassengers.get(getDriverID()).get(j).getlName() +
                            "\n" + returnEconomySeatNumber(logInfo, "REGULAR");

                    isharesPageObjects4.FORMSIZE_DROPDOWN.click();
                    isharesPageObjects4.FORMSIZE_SELECT24.click();

                    gl.logCommand(logInfo, Seatcmd);
                    gl.copyCmdToClipboardAndPaste(Seatcmd, isharesPageObjects4.FORMSIZE_SELECT2_TEXTAREA);

                    isharesPageObjects4.SEND_ISHARES.click();
                    gl.waitForPageReload(getDriver(), isharesPageObjects4.SHARES_RESPONSE, PAGE_LOAD_TIMEOUT);
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                    gl.logResponse(logInfo, isharesPageObjects4.SHARES_RESPONSE.getText());

                    if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("002-OK-")) {
                        logInfo.pass(MarkupHelper.createLabel("I perform ASA for waitlist passenger", ExtentColor.GREEN));
                    } else {
                        logInfo.fail(MarkupHelper.createLabel("SEATS UNASSIGNED - COULD NOT PERFORM ADVANCED SEAT ASSIGNMENT", ExtentColor.PURPLE));
                        Assert.fail("SEATS UNASSIGNED");
                    }

                }


                isharesPageObjects4.FORMSIZE_DROPDOWN.click();
                isharesPageObjects4.FORMSIZE_SELECT1.click();


            } else {
                int TotalSegments = mPassengers.get(getDriverID()).get(0).getTotalSegments();

                for (int i = 1; i <= TotalSegments; i++)  //Doing for All Segments
                {
                    gl.logCommand(logInfo, "6:A" + i);
                    gl.sendCmdValidateResponse("6:A" + i, "SEATS ASSIGNED", logInfo);

                    if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("UNASSIGNED")) {
                        logInfo.fail(MarkupHelper.createLabel("SEATS UNASSIGNED - COULD NOT PERFORM ADVANCED SEAT ASSIGNMENT", ExtentColor.PURPLE));
                        Assert.fail("SEATS UNASSIGNED");
                    } else
                        logInfo.pass(MarkupHelper.createLabel("I perform ASA to all the passengers and validated seat assigned", ExtentColor.GREEN));

                    gl.logCommand(logInfo, saveAndRetrieve);
                    gl.sendCmdValidateResponse(saveAndRetrieve, "6P#ER *", mPassengers.get(getDriverID()).get(0).getPnr(), logInfo);

                    gl.sendCmdIfRequired("ER", mPassengers.get(getDriverID()).get(0).getPnr(), logInfo);

                }

                gl.logCommand(logInfo, "*S/ALL");
                gl.sendCmdValidateResponse("*S/ALL", "SEATS ASSIGNED", logInfo);
                logInfo.pass("I perform ASA to all the passengers and validated seat assigned");

            }

            if (AssignType.equalsIgnoreCase("true") || AssignType.equalsIgnoreCase("SpecificSegment")
                    || AssignType.equalsIgnoreCase("WindowSeat") || AssignType.equalsIgnoreCase("ExitSeat")
                    || AssignType.equalsIgnoreCase("InvalidSegment")) {

                gl.logCommand(logInfo, saveAndRetrieve);
                gl.sendCmdValidateResponse(saveAndRetrieve, "6P#ER *", mPassengers.get(getDriverID()).get(0).getPnr(), logInfo);

                gl.sendCmdIfRequired("ER", mPassengers.get(getDriverID()).get(0).getPnr(), logInfo);
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }
    }

    public void changeASA(ExtentTest logInfo, String segmentNumber, String AssignType) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);

            if (AssignType.equalsIgnoreCase("true")) {

                gl.logCommand(logInfo, "6:A|@N");
                gl.sendCmdValidateResponse("6:A|@N", "SEATS ASSIGNED", logInfo);
                logInfo.pass("I perform ASA to all the passengers and validated seat assigned");

                gl.logCommand(logInfo, saveAndRetrieve);
                gl.sendCmdValidateResponse(saveAndRetrieve, "6P#ER *", pax.getPnr(), logInfo);

                gl.sendCmdIfRequired("ER", mOrderNumber.get(getDriverID()), logInfo);

            } else if (AssignType.equalsIgnoreCase("Delete")) {

                gl.logCommand(logInfo, "6:A|@");
                gl.sendCmdValidateResponse("6:A|@", "SEATS UNASSIGNED", logInfo);
                logInfo.pass("I perform ASA to all the passengers and validated seat assigned");

                gl.logCommand(logInfo, saveAndRetrieve);
                gl.sendCmdValidateResponse(saveAndRetrieve, "6P#ER *", pax.getPnr(), logInfo);

                gl.sendCmdIfRequired("ER", pax.getPnr(), logInfo);
            } else if (AssignType.equalsIgnoreCase("DeleteSpecificSegment")) {

                gl.logCommand(logInfo, "6:A" + segmentNumber + "|@");
                gl.sendCmdValidateResponse("6:A" + segmentNumber + "|@", "SEATS UNASSIGNED", logInfo);
                logInfo.pass("I perform ASA to all the passengers and validated seat assigned");

                gl.logCommand(logInfo, saveAndRetrieve);
                gl.sendCmdValidateResponse(saveAndRetrieve, "6P#ER *", pax.getPnr(), logInfo);

                gl.sendCmdIfRequired("ER", pax.getPnr(), logInfo);
            } else {

                int TotalSegments = mPassengers.get(getDriverID()).get(0).getTotalSegments();
                for (int i = 1; i <= TotalSegments; i++) {

                    gl.logCommand(logInfo, "6:A" + i);
                    gl.sendCmdValidateResponse("6:A" + i, "SEATS ASSIGNED", logInfo);

                    gl.logCommand(logInfo, saveAndRetrieve);
                    gl.sendCmdValidateResponse(saveAndRetrieve, "6P#ER *", pax.getPnr(), logInfo);

                    gl.sendCmdIfRequired("ER", pax.getPnr(), logInfo);
                }

                gl.logCommand(logInfo, "*S/ALL");
                gl.sendCmdValidateResponse("*S/ALL", "SEATS ASSIGNED", logInfo);
                logInfo.pass("I perform ASA to all the passengers and validated seat assigned");

            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }
    }

    public void enter_passenger_Details_with_Same_Surname_in_normal_way(ExtentTest logInfo) {
        try {

            for (int j = 0; j < mPassengers.get(getDriverID()).size(); j++) {
//
                Passenger pax = mPassengers.get(getDriverID()).get(j);

                if (pax.getPaxType().equalsIgnoreCase("ADT")) {
                    String command = "-" + pax.getfName() + "/" + pax.getlName();

                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, pax.getfName().toUpperCase(), pax.getlName().toUpperCase(), logInfo);
                } else if (pax.getPaxType().equalsIgnoreCase("CHD")) {
                    //-SWAN/KAM*-CHD06
                    String command = "-" + pax.getfName() + "/" + pax.getlName() + "*-CHD06";

                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, pax.getfName().toUpperCase(), pax.getlName().toUpperCase(), logInfo);
                } else if (pax.getPaxType().equalsIgnoreCase("INS")) {
                    //-GAYLE/SWAM*-INS/10JAN21
                    String command = "-" + pax.getfName() + "/" + pax.getlName() + "*-INS/" + pax.getDOB();

                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, pax.getfName().toUpperCase(), pax.getlName().toUpperCase(), logInfo);
                } else if (pax.getPaxType().equalsIgnoreCase("INF")) { //ADT+INF

                    //-JEORGE/BROWN*-INFPUPPY/21JAN21

                    String command = "-" + pax.getAccompaniedPaxDetails().getfName() + "/" +
                            pax.getAccompaniedPaxDetails().getlName() + "*-INF" + pax.getlName() + "/" +
                            pax.getDOB();

                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, pax.getlName().toUpperCase(), logInfo);
                } else if (pax.getPaxType().equalsIgnoreCase("NRSA")) {
                    pax.setIsNRSA(true);
                    String command = "-S01C03/" + pax.getfName() + "/" + pax.getlName();

                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, pax.getfName().toUpperCase(), pax.getlName().toUpperCase(), logInfo);
                } else if (pax.getPaxType().equalsIgnoreCase("NRPS")) {

                    pax.setIsNRPS(true);
                    String command = "-P00B03/" + pax.getfName() + "/" + pax.getlName();

                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, pax.getfName().toUpperCase(), pax.getlName().toUpperCase(), logInfo);
                } else if (pax.getPaxType().equalsIgnoreCase("FQTV")) {

                    pax.setIsFQTV(true);
                    String command = "-" + pax.getfName() + "/" + pax.getlName() + "*" + pax.getFFNumber();

                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command, pax.getfName().toUpperCase(), pax.getlName().toUpperCase(), logInfo);
                }
            }

            logInfo.pass("I am entering pax details");

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

