    public void validateMealAndBoardingPaxDetails(ExtentTest logInfo,String ValidationType) {

        try {
            ArrayList<Passenger> Passengers = mPassengers.get(getDriverID());
            String date = gl.sharesFormatDateFromGUI(Passengers.get(0).getSegmentDate(0));
            String origin = Passengers.get(0).getSegmentOriginCity(0);
            String destination = Passengers.get(0).getSegmentDestinationCity(0);
            String flight = Passengers.get(0).getSegmentFlight(0);

            if(ValidationType.equalsIgnoreCase("Brd")){

                String command ="PBT" + flight + "/" +  flight + origin;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "TOTAL BKD",logInfo);
                logInfo.pass("I validate Boarding passenger details");
            }
            else  if(ValidationType.equalsIgnoreCase("SpecificBrd")){

                String command ="PBT" + flight + "/" + date + origin + "-S";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "SEGMENT DETAIL - BOOKED PASSENGERS",logInfo);
                logInfo.pass("I validate Boarding passenger details");
            }
            else  if(ValidationType.equalsIgnoreCase("SpecificDateBrd")){
                String command ="PBT" + flight + "/" +  date + origin + "-D";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "SEGMENT DETAIL - BOOKED PASSENGERS","TOTAL BKD",logInfo);
                logInfo.pass("I validate Boarding passenger details");
            }
            else  if(ValidationType.equalsIgnoreCase("PreliminaryMeal")){

                String command ="PME" + flight + "/" + date + origin;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse24(command,"PRELIMINARY MEAL ORDER",Passengers.get(0).getSsr(),logInfo); //Whichever Meal we take should show in response
                logInfo.pass("I validate Preliminary Meal order of passenger");
            }
            else  if(ValidationType.equalsIgnoreCase("PreliminaryMealCount")){

                String command ="PMP" + flight + "/" +  date + origin + "-B";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "PRELIM MEAL CNT",flight,logInfo);
                logInfo.pass("I validate Preliminary Meal Count of passenger");
            }
            else  if(ValidationType.equalsIgnoreCase("FinalMeal")){

                String command ="PMX" + flight + "/" + date + origin;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse24(command,"FINAL MEAL",Passengers.get(0).getfName()+"/"+Passengers.get(0).getlName(),logInfo);

                logInfo.pass("I validate Final Meal of passenger");

                isharesPageObjects4.FORMSIZE_DROPDOWN.click();
                isharesPageObjects4.FORMSIZE_SELECT1.click();

            }
            else  if(ValidationType.equalsIgnoreCase("PaxBoardInfo")){
                String command ="PBI" + flight + "/" +  date + origin;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command,"INBOUND  CONN","BOARDING-"+origin,"PBI",logInfo);
                logInfo.pass("I validate passenger boarding info");
            }

            else  if(ValidationType.equalsIgnoreCase("PaxNameList")){
                String command ="PNL" + flight + "/" + date + origin;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command,logInfo);
                logInfo.pass("I validate passenger boarding info");
            }
            else  if(ValidationType.equalsIgnoreCase("PDC")){
                String command ="PDC" + flight + "/" +  date + origin;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command,logInfo);
                logInfo.pass("I validate passenger boarding info");
            }
            else  if(ValidationType.equalsIgnoreCase("CancelMeal")){
                String command ="PMO" + flight + "/" +  date + origin + "0";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command,logInfo);
                logInfo.pass("I validate Cancel Meal of passenger");
            }
            else  if(ValidationType.equalsIgnoreCase("InboundConnectCount")){
//                PBC360/05DECPTY
                String command ="PBC" + flight + "/" +  date + origin;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "INBOUND CONNX",logInfo);
                logInfo.pass("I validate inbound connect count");
            }
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }
    }


    public void enterT_ETREMOVEtoRemoveRevoke(ExtentTest logInfo)
   {
       try
       {
           gl.logCommand(logInfo, "*ET");
           gl.sendCmdValidateResponse("*ET", logInfo);

           String response = isharesPageObjects4.SHARES_RESPONSE.getText();
           String[] responseAsRows = response.split("\n");

           String ticketNoRegex = "\\d+\\."; // \d means one digit and \d+ means any number of digits, and to notify escape sequence we give backslash before \\d, \. means a dot and \\. is for escape seq
           Pattern ticketNoPattern = Pattern.compile(ticketNoRegex);

           String dateRegex = "\\d{2}[A-Z]{3}\\d{2}";  // \d{2} means exactly 2 digits , [A-Z]{3} means exactly 3 capital letters in this range and again \d{2} means 2 digits
           Pattern datePattern = Pattern.compile(dateRegex);

           List<String> ticketCoupons = new ArrayList<>();
           String segmentNo="";
           String couponNo="";

           for(String row : responseAsRows)
           {
               Matcher matcher = ticketNoPattern.matcher(row);
               Matcher matcher1 = datePattern.matcher(row);

               if(!matcher1.find())
                   while(matcher.find())
                       segmentNo=matcher.group().replace(".","");
               else if(row.contains("REVOKED"))
                   while(matcher.find())
                   {
                       couponNo=matcher.group().replace(".","");
                       ticketCoupons.add(segmentNo+"."+couponNo);
                   }
           }

           logInfo.info(MarkupHelper.createLabel("REMOVING REVOKE STATUS FOR EACH COUPON", ExtentColor.BLACK));
           //T-ETREMOVE/R1.1
           for(String coupon : ticketCoupons)
           {
               String command = "T-ETREMOVE/R"+coupon;
               gl.logCommand(logInfo, command);
               gl.sendCmdValidateResponse(command, "-OK-", logInfo);
           }

       }
       catch (AssertionError | Exception e) {
           ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
           Assert.fail("This step failed.. so stopping...");
       }
   }

   public void enterT_ET_STATUS_LIFTEDtoLiftTheTicketStatus(ExtentTest logInfo)
   {
        try
        {
            gl.logCommand(logInfo, "*ET");
            gl.sendCmdValidateResponse("*ET", logInfo);

            String response = isharesPageObjects4.SHARES_RESPONSE.getText();
            String[] responseAsRows = response.split("\n");

            String ticketNoRegex = "\\d+\\."; // \d means one digit and \d+ means any number of digits, and to notify escape sequence we give backslash before \\d, \. means a dot and \\. is for escape seq
            Pattern ticketNoPattern = Pattern.compile(ticketNoRegex);

            String dateRegex = "\\d{2}[A-Z]{3}\\d{2}";  // \d{2} means exactly 2 digits , [A-Z]{3} means exactly 3 capital letters in this range and again \d{2} means 2 digits
            Pattern datePattern = Pattern.compile(dateRegex);

            List<String> ticketCoupons = new ArrayList<>();
            String segmentNo="";
            String couponNo="";

            for(String row : responseAsRows)
            {
                Matcher matcher = ticketNoPattern.matcher(row);
                Matcher matcher1 = datePattern.matcher(row);

                if(!matcher1.find())
                    while(matcher.find())
                        segmentNo=matcher.group().replace(".","");
                else
                    while(matcher.find())
                    {
                        couponNo=matcher.group().replace(".","");
                        ticketCoupons.add(segmentNo+"."+couponNo);
                    }
            }

            logInfo.info(MarkupHelper.createLabel("LIFTING TICKET STATUS FOR EACH COUPON", ExtentColor.BLACK));
            //T-ET/STATUS/LIFTED/1.1*
            for(String coupon : ticketCoupons)
            {
                String command = "T-ET/STATUS/LIFTED/"+coupon+"*";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "-OK-", logInfo);
            }

        }
        catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }



