    public void makeSegmentFLOWN(ExtentTest logInfo, String segmentNumber) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String Lniata = pax.getLniata();

            String command = "W" + Lniata + "*";
            System.out.println("LNIATA : " + command);
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, logInfo);
            if (globalConstants.testEnv.equalsIgnoreCase("sharesCURL") || globalConstants.testEnv.equalsIgnoreCase("sharesD3URL")) {
                String flownSegOne = null;
                if (segmentNumber.equalsIgnoreCase("1")) {
                    //ZAFIL CM 00F1660B 0B4 00
                    flownSegOne = "ZAFIL CM 00" + Lniata + " 0B4 00";
                    gl.logCommand(logInfo, flownSegOne);
                    gl.sendCmdValidateResponse(flownSegOne, logInfo);

                } else if (segmentNumber.equalsIgnoreCase("2")) {
                    //ZAFIL CM 00F1660B 0B4 00
                    flownSegOne = "ZAFIL CM 00" + Lniata + " 0D0 00";
                    gl.logCommand(logInfo, flownSegOne);
                    gl.sendCmdValidateResponse(flownSegOne, logInfo);

                }
            }
            else {

                String response = isharesPageObjects4.SHARES_RESPONSE.getText();

                String[] lines=response.split("\n");
                String value=null;
                for(String line:lines){
                    if(line.startsWith(" FA")){
                        value=line.substring(3).trim();
                        break;
                    }
                }
                String flownSegOne;
                if (segmentNumber.equalsIgnoreCase("1")) {
                    //ZAFIL CM 00F1660B 0B4 00
                    flownSegOne = "ZAFIL CM " + value + " 0B4 00";
                    gl.logCommand(logInfo, flownSegOne);
                    gl.sendCmdValidateResponse(flownSegOne, logInfo);

                }
                else if (segmentNumber.equalsIgnoreCase("2")) {
                    //ZAFIL CM 00F1660B 0B4 00
                    flownSegOne = "ZAFIL CM " + value + " 0D0 00";
                    gl.logCommand(logInfo, flownSegOne);
                    gl.sendCmdValidateResponse(flownSegOne, logInfo);

                }

            }

            String saveFlownSeg = "6AA";
            gl.logCommand(logInfo, saveFlownSeg);
            gl.sendCmdValidateResponse(saveFlownSeg, logInfo);

            gl.logCommand(logInfo, endAndretrieve);
            gl.sendCmdValidateResponse(endAndretrieve, pax.getPnr(), logInfo);

            gl.logCommand(logInfo, endAndretrieve);
            gl.sendCmdValidateResponse(endAndretrieve, logInfo);

            gl.logCommand(logInfo, "*H");
            gl.sendCmdValidateResponse("*H", "RCVD", logInfo);


        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }
    }

