    public void removePaxFromVoluntaryOversoldList(ExtentTest logInfo) {
        try {
//                6:DV360/29DECPTY-EARTH/WORLD

            gl.ignoreTRNS(logInfo);
            String volDeniedBoardingCmd = null;
            String indexNo = null;

            ArrayList<Passenger> passengers = mPassengers.get(getDriverID());
            String date = gl.sharesFormatDateFromGUI(passengers.get(0).getSegmentDate(0));
            String flightNo = passengers.get(0).getSegmentFlight(0);


            //                        6:DVR787/13SEPPTY-TESTER/TWO
            volDeniedBoardingCmd = "6:DVR" + flightNo + "/" + date + passengers.get(0).getSegmentOriginCity(0) + "-"
                    + mPassengers.get(getDriverID()).get(0).getfName() ;

            for (int j = 0; j < mPassengers.get(getDriverID()).size(); j++) {
                volDeniedBoardingCmd = volDeniedBoardingCmd + "/" + mPassengers.get(getDriverID()).get(j).getlName();
            }


            gl.logCommand(logInfo, volDeniedBoardingCmd);

            if (mPassengers.get(getDriverID()).get(0).getPaxType().equalsIgnoreCase("NRSA") || mPassengers.get(getDriverID()).get(0).getPaxType().equalsIgnoreCase("NRPS") || mPassengers.get(getDriverID()).get(0).getPaxType().equalsIgnoreCase("Waitlist")) {
                gl.sendCmdValidateResponse(volDeniedBoardingCmd, "INVLD ENT -PSGR IS NON-REVENUE", "FLT NOT OPEN", "MULTIPLE ITEMS", logInfo);
            }
            else
            {
                gl.sendCmdValidateResponse(volDeniedBoardingCmd, "PSGR REMOVED FROM VOL OVERSOLD LIST", "FLT NOT OPEN", "MULTIPLE ITEMS", logInfo);

                if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("MULTIPLE ITEMS"))
                {
                    String response = isharesPageObjects4.SHARES_RESPONSE.getText();

                    for (int j = 0; j < response.split("\n").length; j++) {
                        if (response.split("\n")[j].contains(passengers.get(0).getfName())) {
                            indexNo = response.split("\n")[j].split(" ")[1];

                            for (int k = 0; k < response.split("\n")[j].split(" ").length; k++) {
                                System.out.println("Sl no.: " + k + " " + "Text: " + response.split("\n")[j].split(" ")[k]);
                            }
                            break;
                        }
                    }

//                    6:LDV-182
                    if (mPassengers.get(getDriverID()).get(0).getPaxType().equalsIgnoreCase("NRSA") || mPassengers.get(getDriverID()).get(0).getPaxType().equalsIgnoreCase("NRPS") || mPassengers.get(getDriverID()).get(0).getPaxType().equalsIgnoreCase("Waitlist")) {

                        gl.logCommand(logInfo, "6:LDV-" + indexNo);
                        gl.sendCmdValidateResponse("6:LDV-" + indexNo, "INVLD ENT -PSGR IS NON-REVENUE", logInfo);
                    }
                    else
                    {
                        gl.logCommand(logInfo,"6:LDV-" + indexNo);
                        gl.sendCmdValidateResponse("6:LDV-" + indexNo, "PSGR REMOVED FROM VOL OVERSOLD LIST", passengers.get(0).getfName(), logInfo);
                    }
                }
            }


            if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("FLT NOT OPEN")) {
                isharesPage2.openFlight(logInfo, flightNo, date, mOriginCity.get(getDriverID()));

                isharesPageObjects4.FORMSIZE_DROPDOWN.click();
                isharesPageObjects4.FORMSIZE_SELECT4.click();

                if (passengers.get(0).getPaxType().contains("NRSA") || passengers.get(0).getPaxType().contains("NRPS")) {
                    gl.logCommand(logInfo, volDeniedBoardingCmd);
                    gl.sendCmdValidateResponse(volDeniedBoardingCmd, "INVLD ENT -PSGR IS NON-REVENUE", "FLT NOT OPEN", logInfo);
                } else {
                    gl.logCommand(logInfo, volDeniedBoardingCmd);
                    gl.sendCmdValidateResponse(volDeniedBoardingCmd, "PSGR REMOVED FROM VOL OVERSOLD LIST", "FLT NOT OPEN", logInfo);

                }
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }

    }


