    public void assignGhostSeat(ExtentTest logInfo) {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            String flight = pax.getSegmentFlight(0);
            String Date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String Origin = pax.getSegmentOriginCity(0);
            String Destination = pax.getSegmentDestinationCity(0);
            String COS = pax.getCOS();
            String Seatcmd = "";
            boolean SeatAssigned = false;
            String[] SeatAlphabet = {"AB", "CD", "EF"};
            outerloop:
            for (int j = 0; j < mPassengers.get(getDriverID()).size(); j++) {
                pax = mPassengers.get(getDriverID()).get(j);

                gl.ignoreTRNS(logInfo);

                for (String Alphabet : SeatAlphabet) {

                    for (int i = 5; i <= 35; i++) {      // loop to block all seats

                        //           	6:CP322/06MARPTY.Y/BOG#5EF
                        Seatcmd = "6:CP" + flight + "/" + Date +
                                Origin + "." + COS + "/" + Destination + "|" + i + Alphabet;
                        gl.logCommand(logInfo, Seatcmd);
                        gl.sendCmdValidateResponse(Seatcmd, logInfo);

                        if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("OK")) {

                            gl.logCommand(logInfo, "*" + pax.getPnr());
                            gl.sendCmdValidateResponse("*" + pax.getPnr(), logInfo);

                            //             6:A#6EF
                            String command = "6:A|" + i + Alphabet;
                            gl.logCommand(logInfo, command);
                            gl.sendCmdValidateResponse(command, "SEATS ASSIGNED"," INVLD SEAT NUMBER SPECIFIED", flight, logInfo);

                            if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("INVLD SEAT NUMBER SPECIFIED")) {

                                gl.logCommand(logInfo,ignoreAndRetrieve);
                                gl.sendCmdValidateResponse(ignoreAndRetrieve,logInfo);

                                gl.ignoreTRNS(logInfo);

                                //6:CP322/06MARPTY.Y/BOG#@5EF
                                Seatcmd = "6:CP" + flight + "/" + Date +
                                        Origin + "." + COS + "/" + Destination + "|@" + i + Alphabet;
                                gl.logCommand(logInfo, Seatcmd);
                                gl.sendCmdValidateResponse(Seatcmd,"OK", logInfo);

                                gl.logCommand(logInfo, "*" + pax.getPnr());
                                gl.sendCmdValidateResponse("*" + pax.getPnr(), logInfo);

                                gl.logCommand(logInfo, command);
                                gl.sendCmdValidateResponse(command, "SEATS ASSIGNED", flight, logInfo);
                            }
                            break outerloop;
                        }
                    }
                }
            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


