    public void addRemarksPnr(ExtentTest logInfo, String RemarkType) {
        try {

            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String origin = pax.getSegmentOriginCity(0);
            String destination = pax.getSegmentDestinationCity(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));

            if (RemarkType.equalsIgnoreCase("AddRemark")) {

                //\par I\tab 6:CG816/09JULPTY
                //\par M\tab HELLO ALL...
                String command =  "6:CG" + pax.getSegmentFlight(0) + "/" + date + pax.getSegmentOriginCity(0) + "\n" + "HELLO ALL";
                gl.logCommand(logInfo, command);
                gl.sendCopiedCmdValidateResponse2(logInfo,command, "FLIGHT INFORMATION");
                logInfo.pass("I add remark to the pnr");
                String response = isharesPageObjects4.SHARES_RESPONSE.getText();
                String[] rows = response.split("\n");
                String[] text = rows[3].split(" ");
                String areacode = text[1];
                pax.setAreaCode(areacode);

            }else if (RemarkType.equalsIgnoreCase("DisplayRemark")) {

                //6:CG816/09JULPTY*#ALL
                String command = "6:CG" + pax.getSegmentFlight(0) + "/" + date +
                        pax.getSegmentOriginCity(0) + "*|ALL";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command,  "FLIGHT INFORMATION", "NO FLIGHT INFORMATION EXISTS",logInfo);
                logInfo.pass("I display remark to the pnr");
            }else if (RemarkType.equalsIgnoreCase("CancelRemark")) {

                String command="6:CG" + pax.getSegmentFlight(0) + "/" + date
                        + pax.getSegmentOriginCity(0) + "@" +pax.getAreaCode();
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command,  "FLIGHT INFORMATION", "MODIFICATION DONE",logInfo);
                logInfo.pass("I cancel remark to the pnr");
            }

            logInfo.pass("I save remarks to the pnr" + RemarkType);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.junit.Assert.fail("This step failed.. so stopping...");
        }
    }



