    public void updateThePassengerToAChildPassenger(ExtentTest logInfo, String index) {
        try {
//                   -1@SAM/KIM*-CHD09
            Passenger pax = mPassengers.get(getDriverID()).get(0);

            Faker fname = new Faker(new Locale("en-US"));
            String FirstName = fname.name().firstName().toUpperCase();
            String LastName = fname.name().lastName().toUpperCase();

            String command = "-" + index + "@" + FirstName + "/" + LastName + "*-CHD09";

            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, command, logInfo);

            logInfo.pass("I update the passenger to a child passenger");

            gl.logCommand(logInfo, saveAndRetrieve);
            gl.sendCmdValidateResponse(saveAndRetrieve, "6P#ER *", FirstName.toUpperCase(), "TRANSACT WILL UNSEAT","SSR RETAINED FOR NEW NAME", logInfo);
            gl.sendCmdIfRequired(endAndretrieve, FirstName.toUpperCase(), "TRANSACT WILL UNSEAT", logInfo);

            String response = isharesPageObjects4.SHARES_RESPONSE.getText();
            Assert.assertTrue(response.contains(FirstName+ "/" + LastName) || response.contains("TRANSACT WILL UNSEAT"));

            if (response.contains("TRANSACT WILL UNSEAT")) {
                gl.logCommand(logInfo, endAndretrieve);
                gl.sendCmdValidateResponse(endAndretrieve, pax.getPnr(), logInfo);
            }

            mPassengers.get(getDriverID()).get(Integer.parseInt(index)-1).setfName(FirstName);
            mPassengers.get(getDriverID()).get(Integer.parseInt(index)-1).setlName(LastName);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

