    public void addSSRforMultiInitialPax(ExtentTest logInfo, String SSR)
    {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flight = pax.getSegmentFlight(0);
            String date = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String pnr = pax.getPnr();
            int TotalPax = mPassengers.get(getDriverID()).size();

            if (SSR.equalsIgnoreCase("WCHR"))
            {
                String WCHR = "3SSRWCHRCMNN"+TotalPax+"$S1N1";

                gl.logCommand(logInfo, WCHR);
                gl.sendCmdValidateResponse(WCHR, WCHR+" *","SSR NOT AVAILABLE", flight, logInfo);

                if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("SSR NOT AVAILABLE")) {

                    removeSSRFromPSCExceptionTable(logInfo,SSR);
                    gl.logCommand(logInfo, WCHR);
                    gl.sendCmdValidateResponse(WCHR, WCHR+" *", logInfo);
                }

                gl.logCommand(logInfo, "6P#ER");
                gl.sendCmdValidateResponse("6P#ER", pnr, "SSR", "SIMULT CHGS TO PNR", logInfo);

                if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("SIMULT CHGS TO PNR"))
                {
                    gl.logCommand(logInfo, "IR");
                    gl.sendCmdValidateResponse("IR", pnr, logInfo);
                    gl.logCommand(logInfo, WCHR);
                    gl.sendCmdValidateResponse(WCHR, "3SSRWCHRCMNN1$S1N1 *","SSR NOT AVAILABLE", flight, logInfo);
                    gl.logCommand(logInfo, "6P#ER");
                    gl.sendCmdValidateResponse("6P#ER", pnr, "SSR", "SIMULT CHGS TO PNR", logInfo);
                    isharesPage2.enterER_MD(logInfo);
                }
                else
                {
                    isharesPage2.enterER_MD(logInfo);
                }

            } else if (SSR.equalsIgnoreCase("PETC"))
            {
                for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++)
                {
                    pax = mPassengers.get(getDriverID()).get(i);
                    String SSR_OTHS = "3SSR" + SSR + "CMNN"+TotalPax + pax.getSegmentOriginCity(0) + pax.getSegmentDestinationCity(0) +
                            pax.getSegmentFlight(0) + pax.getCOS() + date + "-1" + pax.getfName() + "/" + pax.getlName() + ".DOG";
                    gl.logCommand(logInfo, SSR_OTHS);
                    gl.sendCmdValidateResponse(SSR_OTHS, SSR_OTHS, "SSR NOT AVAILABLE", logInfo);

                    if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("SSR NOT AVAILABLE")) {

                        removeSSRFromPSCExceptionTable(logInfo, SSR);
                        gl.logCommand(logInfo, SSR_OTHS);
                        gl.sendCmdValidateResponse(SSR_OTHS, SSR_OTHS, logInfo);
                    }

                    gl.logCommand(logInfo, "6P#ER");
                    gl.sendCmdValidateResponse("6P#ER", pnr, "SSR", "SIMULT CHGS TO PNR", logInfo);

                    if (isharesPageObjects4.SHARES_RESPONSE.getText().contains("SIMULT CHGS TO PNR")) {
                        gl.logCommand(logInfo, "IR");
                        gl.sendCmdValidateResponse("IR", pnr, logInfo);
                        gl.logCommand(logInfo, SSR_OTHS);
                        gl.sendCmdValidateResponse(SSR_OTHS, SSR_OTHS, "SSR NOT AVAILABLE", logInfo);
                        gl.logCommand(logInfo, "6P#ER");
                        gl.sendCmdValidateResponse("6P#ER", pnr, "SSR", "SIMULT CHGS TO PNR", logInfo);
                        isharesPage2.enterER_MD(logInfo);
                    } else {
                        isharesPage2.enterER_MD(logInfo);
                    }
                }
            }

            pax.setSsr(SSR.toUpperCase());

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


