    public void addSameSurnameCorporateToPaxInNativeShares(ExtentTest logInfo, String paxCount) {
        try {
            isharesPageObjects4.NATIVE_SHARES_CLEAR_ALL.click();
            gl.waitProgress();

            Faker faker = new Faker();
            String fname = faker.name().firstName().replaceAll("[^a-zA-Z0-9]", "").toUpperCase();

            System.out.println("The new Surname is  : " + fname);

            for (int i = 0; i < Integer.parseInt(paxCount); i++) {
                if(mPassengers.get(getDriverID()).get(i).getPaxType().equalsIgnoreCase("INF"))
                {
                    mPassengers.get(getDriverID()).get(i).getAccompaniedPaxDetails().setfName(fname);
                    mPassengers.get(getDriverID()).get(i).setIsSameSurnameCorporatePNR(true);
                }else {
                    mPassengers.get(getDriverID()).get(i).setfName(fname);
                    mPassengers.get(getDriverID()).get(i).setIsSameSurnameCorporatePNR(true);
                }

            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public void enterAllPassengerDetailsForSameSurnamePaxInNativeShares(ExtentTest logInfo) {
        try {
            isharesPageObjects4.NATIVE_SHARES_CLEAR_ALL.click();
            gl.waitProgress();

            List<Passenger> pax = mPassengers.get(getDriverID());

            String Surname = null;

            for (int i = 0; i < mPassengers.get(getDriverID()).size(); i++) {
                if (mPassengers.get(getDriverID()).get(0).getIsSameSurnameCorporatePNR() || mPassengers.get(getDriverID()).get(0).getIsSameSurnameGroupPNR()
                        || mPassengers.get(getDriverID()).get(0).getIsSameSurname()) {
                    Surname = mPassengers.get(getDriverID()).get(0).getfName();
                }
            }


            for (Passenger passenger : pax) {
                String command ;
                if (passenger.getPaxType().equalsIgnoreCase("INF")) {
                    command = "-" + Surname + "/" + passenger.getAccompaniedPaxDetails().getlName() + "*-INF" + passenger.getlName() + "/" + passenger.getDOB();
                } else if (passenger.getPaxType().equalsIgnoreCase("INS")) {
                    command = "-" + Surname + "/" + passenger.getlName() + "*-INS/" + passenger.getDOB();
                } else if (passenger.getPaxType().equalsIgnoreCase("CHD")) {
                    command = "-" + Surname + "/" + passenger.getlName() + "*-CHD06";
                } else {
                    command = "-" + Surname + "/" + passenger.getlName();
                }

                isharesPage2.sendCmdToNativeSharesValidateResponse(command, passenger.getlName().toUpperCase(), isharesPageObjects4.NATIVE_SHARES_RESPONSE_VALIDATE_LINE3, logInfo);
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

