    public void ToReissueTicketWithEvenExchange(ExtentTest logInfo, String ExchangeType) {
        try {


            ArrayList<Passenger> passengers = mPassengers.get(getDriverID());
            gl.logCommand(logInfo, saveAndRetrieve);
            gl.sendCmdValidateResponse(saveAndRetrieve,"ETKT/PNR MODIFIED- CHK ITIN", logInfo);

            gl.logCommand(logInfo, "ER");
            gl.sendCmdValidateResponse("ER", "PNR MODIFIED", "ETKT/PNR MODIFIED- CHK ITIN", logInfo);
            //Since we made changes to PNR , it will show PNR Modified , if no changes are made or the made changes have been saved then it wil nt show PNR MODIFIED

            gl.sendCmdIfRequired("ER", passengers.get(0).getPnr(), logInfo);

            gl.logCommand(logInfo, "T-ETCKPRICE");
            gl.sendCmdValidateResponse("T-ETCKPRICE", logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            int paxSequenceAfterDecimal;
            int sameSurnamePaxSeq = 1;
            int normalPaxSeq = 1;

            String Response;
            String ticketNumber;

            for (int j = 0; j < passengers.size(); j++)  //Looping through each Passenger
            {

                if (passengers.get(j).getIsSameSurname())
                    paxSequenceAfterDecimal = sameSurnamePaxSeq++;
                else
                    paxSequenceAfterDecimal = normalPaxSeq;

                String command = "*ET" + (j + 1) + "." + "1";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, passengers.get(j).getfName() + "/" + passengers.get(j).getlName(), logInfo);

                Response = isharesPageObjects4.SHARES_RESPONSE.getText();

                String reissue = "";

                ticketNumber = getTicketNumberForPassenger(logInfo, Response);

                if (ExchangeType.equalsIgnoreCase("EvenExchangeWithVisa")) {

                    //      T-$EE23022300006573/FVI#N1.1#ET
                    reissue = "T-$EE" + ticketNumber + "/FVI|N" + passengers.get(j).getIndexOfPax() + "." + paxSequenceAfterDecimal+ "|ET";
                }

                System.out.println(reissue);
                gl.logCommand(logInfo, reissue);
                gl.sendCmdValidateResponse(reissue, "FARE", "SEE ADV PURCHASE", logInfo);


                // Saving the transaction
                gl.logCommand(logInfo, ignoreAndRetrieve);
                gl.sendCmdValidateResponse(ignoreAndRetrieve, logInfo);

                gl.logCommand(logInfo, "FR/ALL");
                gl.sendCmdValidateResponse("FR/ALL", "ALL FILED QUOTES WILL BE SENT TO HISTORY AFTER ET",logInfo);

                gl.logCommand(logInfo, saveAndRetrieve);
                gl.sendCmdValidateResponse(saveAndRetrieve, logInfo);
            }

            //Check Ticket Status
            gl.logCommand(logInfo, checkTicketStatus);
            gl.sendCmdValidateResponse(checkTicketStatus, "EXCHANGED", logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

