    public void updateOutTimeForFLIFOInIshares(ExtentTest logInfo)
    {
        try {
            Passenger pax = mPassengers.get(getDriverID()).get(0);
            String flightNo = pax.getSegmentFlight(0);
            String startDate = gl.sharesFormatDateFromGUI(pax.getSegmentDate(0));
            String destCity = pax.getSegmentDestinationCity(0);
            String originCity = pax.getSegmentOriginCity(0);
            int time=0;

            String command = "2" + pax.getSegmentFlight(0) + "/" + startDate;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, pax.getSegmentFlight(0), "SKED", logInfo);
            String response=isharesPageObjects4.SHARES_RESPONSE.getText();
            String[] res=response.split("\n");
            String res1 = res[4];
            String[] var=res1.split(" ");
            for(int i=0;i<var.length;i++){
                if(!var[i].isEmpty()){
                    if(!var[i].equals(destCity)){

                        String segment=var[i].trim();
                        String value=segment.substring(0,segment.length()-1);
                        time=Integer.parseInt(value)+10;
                        String str= String.valueOf(time);
                        String x=str.substring(str.length()-2);
                        int z=Integer.parseInt(x);
                        int y=58;
                        if(z>y){
                            time=time-42;
                        }
                        break;
                    }
                }
            }

            command="2P" + flightNo + "/" + startDate + " OUT " + originCity + " " + time + "P";
            gl.logCommand(logInfo, command);
            gl.sendCopiedCmdValidateResponse2(logInfo, command, "MESSAGE ACCEPTED","*");

            Thread.sleep(5000);
            command = "2" + pax.getSegmentFlight(0) + "/" + startDate;
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, originCity + "/OUT","SKED", logInfo);

            String response1 = isharesPageObjects4.SHARES_RESPONSE.getText();
            if (!response1.contains(originCity + "/OUT")) {
                gl.waitProgress();
                command = "2" + pax.getSegmentFlight(0) + "/" + startDate;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, originCity + "/OUT", logInfo);
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


